(window.CLAVE_TODO=window.CLAVE_TODO||{})[3]=[{"a":"Artículos 85 y 86 TFUE — Eurojust y Fiscalía Europea EXOF ✱","q":[{"i":"3-5","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. La función de Eurojust es:","o":["Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes.","Promover y reforzar la coordinación y la cooperación entre las autoridades internacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes.","Apoyar y reforzar la coordinación y la cooperación entre las autoridades internacionales encargadas de investigar y perseguir la delincuencia grave que afecte a tres o más Estados miembros o que deba perseguirse según criterios específicos.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes</mark></span>El <span class=\"ref-norma\">art. 85.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Eurojust es apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes, basándose en las operaciones efectuadas y en la información proporcionada por las autoridades de los Estados miembros y por Europol\"</span>. El artículo 85.1 del TFUE define la función de Eurojust como apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes."},{"i":"3-35","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. La función de Eurojust es:","o":["Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros.","Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a un único Estado miembro.","Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a uno o más Estados miembros.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros</mark></span>El <span class=\"ref-norma\">art. 85.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Eurojust es apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes, basándose en las operaciones efectuadas y en la información proporcionada por las autoridades de los Estados miembros y por Europol\"</span>. El artículo 85.1 del TFUE define la función de Eurojust como apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes."},{"i":"3-74","p":"Tratado de Funcionamiento de la UE. Para combatir las infracciones que perjudiquen a los intereses financieros de la Unión, el Consejo podrá crear:","o":["Una Fiscalía Europea a partir de Europol.","Una Fiscalía Europea a partir de Eurojust.","Una Fiscalía Europea a partir de Interpol.","Una Fiscalía Europea a partir del Tribunal de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una Fiscalía Europea a partir de Eurojust</mark></span>El <span class=\"ref-norma\">art. 86.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo podrá crear, mediante reglamentos adoptados con arreglo a un procedimiento legislativo especial, una Fiscalía Europea a partir de Eurojust\"</span>. El artículo 86.1 del TFUE establece que, para combatir las infracciones que perjudiquen a los intereses financieros de la Unión, el Consejo podrá crear una Fiscalía Europea a partir de Eurojust."},{"i":"3-157","p":"Tratado de Funcionamiento de la Unión Europea. Para combatir las infracciones que perjudiquen a los intereses financieros de la Unión, el Consejo podrá crear, mediante reglamentos adoptados con arreglo a un procedimiento legislativo especial, una fiscalía europea a partir de Eurojust. El Consejo se pronunciará, previa aprobación del Parlamento Europeo:","o":["Por mayoría simple.","Por unanimidad.","Por mayoría cualificada.","Por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por unanimidad</mark></span>El <span class=\"ref-norma\">art. 86.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"una Fiscalía Europea a partir de Eurojust. El Consejo se pronunciará por unanimidad, previa aprobación del Parlamento Europeo\"</span>. El artículo 86.1 del TFUE establece que el Consejo se pronunciará por unanimidad, previa aprobación del Parlamento Europeo, para crear mediante reglamento una Fiscalía Europea a partir de Eurojust."},{"i":"3-219","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién tiene la función de apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes?","o":["Eurojust.","Europol.","El Tribunal de Justicia de la Unión Europea.","Interpol."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Eurojust</mark></span>El <span class=\"ref-norma\">art. 85.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Eurojust es apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes, basándose en las operaciones efectuadas y en la información proporcionada por las autoridades de los Estados miembros y por Europol\"</span>. El artículo 85.1 del TFUE define la función de Eurojust como apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes."},{"i":"3-249","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. ¿Quién determinará la estructura de Europol?","o":["La Comisión y el Consejo.","El Tribunal de Justicia de la Unión Europea.","El Consejo y el Parlamento Europeo.","El Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo y el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 85.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A tal fin, el Parlamento Europeo y el Consejo determinarán, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario, la estructura, el funcionamiento, el ámbito de actuación y las competencias de Eurojust\"</span>. Según el art. 88.2 TFUE, el Parlamento Europeo y el Consejo determinarán mediante reglamentos la estructura, funcionamiento, ámbito de actuación y competencias de Europol."},{"i":"3-286","p":"Tratado de Funcionamiento de la Unión Europea. Determinarán la estructura, el funcionamiento, el ámbito de actuación y las competencias de Eurojust:","o":["El Parlamento Europeo y el Consejo, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario.","El Parlamento Europeo y el Consejo, mediante reglamentos adoptados con arreglo al procedimiento legislativo especial.","El Parlamento Europeo y el Consejo, mediante directivas adoptadas con arreglo al procedimiento legislativo ordinario.","El Parlamento Europeo y el Consejo, mediante directivas adoptadas con arreglo al procedimiento legislativo especial."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario</mark></span>El <span class=\"ref-norma\">art. 88.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo determinarán, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario, la estructura, el funcionamiento, el ámbito de actuación y las competencias de Europol. Estas competencias podrán incluir\"</span>. El artículo 85.1 del TFUE establece que el Parlamento Europeo y el Consejo determinarán, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario, la estructura, el funcionamiento, el ámbito de actuación y las competencias de Eurojust."},{"i":"3-292","p":"Tratado de Funcionamiento de la Unión Europea. Será competente para descubrir a los autores y cómplices de infracciones que perjudiquen a los intereses financieros de la Unión:","o":["Europol.","Interpol.","Eurojust.","La Fiscalía Europea."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Fiscalía Europea</mark></span>El <span class=\"ref-norma\">art. 86.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Fiscalía Europea, en su caso en colaboración con Europol, será competente para descubrir a los autores y cómplices de infracciones que perjudiquen a los intereses financieros de la Unión definidos en el reglamento contemplado en el apartado 1, y para incoar un procedimiento penal y solicitar la apertura de juicio contra ellos\"</span>. El artículo 86.2 del TFUE establece que la Fiscalía Europea será competente para descubrir a los autores y cómplices de infracciones que perjudiquen a los intereses financieros de la Unión, e incoar el correspondiente procedimiento penal."},{"i":"3-313","p":"Tratado de Funcionamiento de la Unión Europea. Para combatir las infracciones que perjudiquen a los intereses financieros de la Unión, el Consejo podrá crear:","o":["Una Fiscalía Europea a partir de Europol.","Una Fiscalía Europea a partir de Eurojust.","Una Fiscalía Europea a partir de Interpol.","Una Fiscalía Europea a partir del Tribunal de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Una Fiscalía Europea a partir de Eurojust</mark></span>El <span class=\"ref-norma\">art. 86.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo podrá crear, mediante reglamentos adoptados con arreglo a un procedimiento legislativo especial, una Fiscalía Europea a partir de Eurojust\"</span>. El artículo 86.1 TFUE permite al Consejo crear una Fiscalía Europea a partir de Eurojust."},{"i":"3-331","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién tiene la función de apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes?","o":["Eurojust.","Europol.","El Tribunal de Justicia de la Unión Europea.","Interpol."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Eurojust</mark></span>El <span class=\"ref-norma\">art. 85.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Eurojust es apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes, basándose en las operaciones efectuadas y en la información proporcionada por las autoridades de los Estados miembros y por Europol\"</span>. El artículo 85 TFUE atribuye esta función a Eurojust."},{"i":"3-ia-3047","p":"Tratado de la Unión Europea. Parlamentos nacionales. Los Parlamentos nacionales participarán en los mecanismos de evaluación de las políticas del espacio de libertad, seguridad y justicia, estarán asociados al control político de Europol y a la evaluación de las actividades de Eurojust y participarán en:","o":["la cooperación judicial en materia penal entre los Estados miembros.","la evaluación de las políticas de la Unión en materia de justicia y asuntos de interior, conforme al procedimiento que se establezca reglamentariamente.","la cooperación interparlamentaria entre los Parlamentos nacionales y con el Parlamento Europeo.","el control político de la Agencia Europea de Fronteras y Costas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la cooperación interparlamentaria entre los Parlamentos nacionales y con el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 12.c y f de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"participarán en la cooperación interparlamentaria entre los Parlamentos nacionales y con el Parla\"</span>. También participan en la cooperación interparlamentaria. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3416","p":"Tratado de Funcionamiento de la Unión Europea. Eurojust. La función de Eurojust es apoyar y reforzar la coordinación y la cooperación entre las autoridades nacionales encargadas de investigar y perseguir la delincuencia grave que afecte a dos o más Estados miembros o que deba perseguirse según criterios comunes, basándose en las operaciones efectuadas y en la información proporcionada por las autoridades de los Estados miembros y por:","o":["la Comisión.","Europol.","la Fiscalía Europea.","el Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Europol</mark></span>El <span class=\"ref-norma\">art. 85.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la información proporcionada por las autoridades de los Estados miembros y por Europol\"</span>. Eurojust se basa en información de las autoridades nacionales y de Europol. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3417","p":"Tratado de Funcionamiento de la Unión Europea. Eurojust. El Parlamento Europeo y el Consejo determinarán, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario, la estructura, el funcionamiento, el ámbito de actuación y las competencias de Eurojust, que podrán incluir el inicio de diligencias de investigación penal, la propuesta de incoación de procedimientos penales por las autoridades nacionales competentes, la coordinación de las investigaciones y:","o":["la intensificación de la cooperación judicial, entre otras cosas mediante la resolución de conflictos de jurisdicción y una estrecha cooperación con la Red Judicial Europea.","la ejecución de las órdenes europeas de detención y entrega y la coordinación de los equipos conjuntos de investigación, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","la acusación ante los tribunales nacionales y la dirección de las investigaciones de las policías nacionales.","la adopción de decisiones vinculantes sobre la competencia judicial entre los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la intensificación de la cooperación judicial, entre otras cosas mediante la resolución de conflictos de jurisdicción y una estrecha cooperación con la Red Judicial Europea</mark></span>El <span class=\"ref-norma\">art. 85.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la intensificación de la cooperación judicial, entre otras cosas mediante la resolución de conflic\"</span>. Intensificar la cooperación judicial, resolver conflictos de jurisdicción y cooperar con la Red Judicial Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3418","p":"Tratado de Funcionamiento de la Unión Europea. Eurojust. En el contexto de las acciones penales contempladas en la función de Eurojust, y sin perjuicio de la Fiscalía Europea, los actos formales de carácter procesal serán llevados a cabo:","o":["por los funcionarios de Eurojust.","por los miembros de la Fiscalía Europea, salvo que se disponga otra cosa en la normativa aplicable.","por los jueces de enlace de Eurojust.","por los funcionarios nacionales competentes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por los funcionarios nacionales competentes</mark></span>El <span class=\"ref-norma\">art. 85.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"los actos formales de carácter procesal serán llevados a cabo por los funcionarios nacionales competentes\"</span>. Los actos procesales los realizan los funcionarios nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3419","p":"Tratado de Funcionamiento de la Unión Europea. Fiscalía Europea. Para combatir las infracciones que perjudiquen a los intereses financieros de la Unión, el Consejo podrá crear, mediante reglamentos adoptados con arreglo a un procedimiento legislativo especial, una Fiscalía Europea a partir de Eurojust; el Consejo se pronunciará:","o":["por mayoría cualificada, previa aprobación del Parlamento Europeo.","por unanimidad, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, a propuesta de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por unanimidad, previa aprobación del Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 86.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad, previa aprobación\"</span>. Procedimiento legislativo especial: unanimidad y aprobación del Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3420","p":"Tratado de Funcionamiento de la Unión Europea. Fiscalía Europea. En caso de falta de unanimidad en la creación de la Fiscalía Europea, un grupo de al menos nueve Estados miembros podrá solicitar que el proyecto de reglamento se remita al Consejo Europeo, en cuyo caso quedará suspendido el procedimiento en el Consejo; previa deliberación y en caso de alcanzarse un consenso, el Consejo Europeo, en el plazo de cuatro meses a partir de dicha suspensión:","o":["adoptará el reglamento por mayoría cualificada.","devolverá el proyecto al Consejo para su adopción.","devolverá el proyecto a la Comisión para su modificación.","remitirá el proyecto al Parlamento Europeo para su aprobación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">devolverá el proyecto al Consejo para su adopción</mark></span>El <span class=\"ref-norma\">art. 86.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"devolverá el proyecto al Consejo para su adopción\"</span>. Con consenso, el Consejo Europeo devuelve el proyecto al Consejo para su adopción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3422","p":"Tratado de Funcionamiento de la Unión Europea. Fiscalía Europea. El Consejo Europeo podrá adoptar una decisión que modifique las disposiciones sobre la Fiscalía Europea con el fin de ampliar sus competencias a la lucha contra la delincuencia grave que tenga una dimensión transfronteriza; se pronunciará:","o":["por mayoría cualificada, previa aprobación del Parlamento Europeo y previa consulta a la Comisión.","por unanimidad, previa consulta al Parlamento Europeo y previa aprobación de la Comisión.","por mayoría cualificada, a propuesta de la Comisión y previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo y previa consulta a la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por unanimidad, previa aprobación del Parlamento Europeo y previa consulta a la Comisión</mark></span>El <span class=\"ref-norma\">art. 86.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo se pronunciará por unanimidad, previa aprobación del Parlamento Europeo y previa consulta a la Comisión\"</span>. Unanimidad, aprobación del Parlamento y consulta a la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 42 — Política común de seguridad y defensa ✱","q":[{"i":"3-8","p":"Tratado de la Unión Europea sobre la política común de seguridad y defensa:","o":["Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo.","Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles, militares y peso gravatorio para contribuir a los objetivos definidos por el Consejo.","Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles, militares y peso gravatorio para contribuir a los objetivos definidos por el Parlamento Europeo.","Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo</mark></span>El <span class=\"ref-norma\">art. 42.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo\"</span>. El artículo 42.3 del TUE establece que los Estados miembros pondrán a disposición de la Unión, a efectos de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo."},{"i":"3-73","p":"Tratado de la Unión Europea. Disposiciones generales relativas a la acción exterior de la Unión y disposiciones específicas relativas a la política exterior y seguridad común. Política exterior y seguridad común. La política común de seguridad y defensa ofrecerá a la Unión una capacidad operativa basada en:","o":["Medios civiles y militares.","Medios políticos y privados.","Medios militares, políticos y privados.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Medios civiles y militares</mark></span>El <span class=\"ref-norma\">art. 42.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La política común de seguridad y defensa forma parte integrante de la política exterior y de seguridad común. Ofrecerá a la Unión una capacidad operativa basada en medios civiles y militares\"</span>. El artículo 42.1 del TUE establece que la política común de seguridad y defensa ofrecerá a la Unión una capacidad operativa basada en medios civiles y militares."},{"i":"3-85","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por:1","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo Europeo.","El Parlamento Europeo.","El Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo</mark></span>Según el <span class=\"ref-norma\">art. 42.3 del TUE</span>: <span class=\"ref-concepto\">\"Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares para contribuir a los objetivos definidos por el Consejo.\"</span> (verificado con el texto del temario)."},{"i":"3-177","p":"Tratado de la Unión Europea. Disposiciones generales relativas a la acción exterior de la Unión y disposiciones específicas relativas a la política exterior y seguridad común. Política exterior y seguridad común. La Agencia Europea de Defensa estará bajo la autoridad:","o":["Del Consejo Europeo.","Del Consejo.","Del Comité Político y Seguridad.","Del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del Consejo</mark></span>El <span class=\"ref-norma\">art. 45.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Agencia Europea de Defensa a que se refiere el apartado 3 del artículo 42 estará bajo la autoridad del Consejo y tendrá como misión\"</span>. El artículo 45.1 del TUE establece que la Agencia Europea de Defensa estará bajo la autoridad del Consejo."},{"i":"3-184","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. ¿Quién podrá encomendar la realización de una misión, en el marco de la Unión, a un grupo de Estados miembros a fin de defender los valores y favorecer los intereses de la Unión?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo.","El Parlamento Europeo.","La Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 42.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo podrá encomendar la realización de una misión, en el marco de la Unión, a un grupo de Estados miembros a fin de defender los valores y favorecer los intereses de la Unión\"</span>. El artículo 42.5 del TUE establece que el Consejo podrá encomendar la realización de una misión, en el marco de la Unión, a un grupo de Estados miembros a fin de defender los valores y favorecer los intereses de la Unión."},{"i":"3-212","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. La política común de seguridad y defensa incluirá la definición progresiva de una política común de defensa de la Unión. Ésta conducirá a una defensa común una vez que:","o":["El Consejo Europeo lo haya decidido por unanimidad.","El Consejo lo haya decidido por mayoría cualificada.","El Parlamento Europeo lo haya decidido por unanimidad.","La Comisión lo haya decidido por mayoría cualificada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo lo haya decidido por unanimidad</mark></span>El <span class=\"ref-norma\">art. 42.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La política común de seguridad y defensa incluirá la definición progresiva de una política común de defensa de la Unión. Ésta conducirá a una defensa común una vez que el Consejo Europeo lo haya decidido por unanimidad\"</span>. El artículo 42.2 del TUE establece que la política común de seguridad y defensa conducirá a una defensa común una vez que el Consejo Europeo lo haya decidido por unanimidad."},{"i":"3-284","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. ¿Quién adoptará las decisiones relativas a la política común de seguridad y defensa?","o":["El Consejo Europeo por mayoría cualificada.","El Consejo por unanimidad.","El Parlamento Europeo por mayoría cualificada.","La Comisión por unanimidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo por unanimidad</mark></span>El <span class=\"ref-norma\">art. 42.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo adoptará por unanimidad, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad o a iniciativa de un Estado miembro\"</span>. El artículo 42.4 del TUE establece que el Consejo adoptará por unanimidad, a propuesta del Alto Representante o a iniciativa de un Estado miembro, las decisiones relativas a la política común de seguridad y defensa."},{"i":"3-293","p":"Tratado de la Unión Europea. ¿Quién adoptará las decisiones relativas a las misiones fuera de la Unión que tengan por objetivo garantizar el mantenimiento de la paz, la prevención de conflictos y el fortalecimiento de la seguridad internacional, conforme a los principios de la Carta de las Naciones Unidas?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo.","La Agencia Europea de Defensa.","El Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 42.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión podrá recurrir a dichos medios en misiones fuera de la Unión que tengan por objetivo garantizar el mantenimiento de la paz, la prevención de conflictos y el fortalecimiento de la seguridad internacional, conforme a los principios de la Carta de las Naciones Unidas\"</span>. El artículo 43.2 del TUE establece que el Consejo adoptará las decisiones relativas a las misiones fuera de la Unión destinadas a garantizar el mantenimiento de la paz, la prevención de conflictos y el fortalecimiento de la seguridad internacional."},{"i":"3-312","p":"Tratado de la Unión Europea. Política exterior y seguridad común. La política común de seguridad y defensa ofrecerá a la Unión una capacidad operativa basada en:","o":["Medios civiles y militares.","Medios políticos y privados.","Medios militares, políticos y privados.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Medios civiles y militares</mark></span>El <span class=\"ref-norma\">art. 42.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La política común de seguridad y defensa forma parte integrante de la política exterior y de seguridad común. Ofrecerá a la Unión una capacidad operativa basada en medios civiles y militares\"</span>. El artículo 42.1 TUE establece que la política común de seguridad y defensa ofrecerá a la Unión una capacidad operativa basada en medios civiles y militares."},{"i":"3-327","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. La política común de seguridad y defensa incluirá la definición progresiva de una política común de defensa de la Unión. Ésta conducirá a una defensa común una vez que:","o":["El Consejo Europeo lo haya decidido por unanimidad.","El Consejo lo haya decidido por mayoría cualificada.","El Parlamento Europeo lo haya decidido por unanimidad.","La Comisión lo haya decidido por mayoría cualificada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo lo haya decidido por unanimidad</mark></span>El <span class=\"ref-norma\">art. 42.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La política común de seguridad y defensa incluirá la definición progresiva de una política común de defensa de la Unión. Ésta conducirá a una defensa común una vez que el Consejo Europeo lo haya decidido por unanimidad\"</span>. El artículo 42.2 TUE exige una decisión unánime del Consejo Europeo para pasar a una defensa común."},{"i":"3-ia-3158","p":"Tratado de la Unión Europea. Iniciativas en materia de PESC. Cualquier Estado miembro, el Alto Representante, o el Alto Representante con el apoyo de la Comisión, podrá plantear al Consejo cualquier cuestión relacionada con la política exterior y de seguridad común y presentar:","o":["proyectos de decisión al Consejo Europeo.","informes de situación al Consejo Europeo.","propuestas legislativas al Consejo.","iniciativas o propuestas al Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">iniciativas o propuestas al Consejo</mark></span>El <span class=\"ref-norma\">art. 30.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"presentar, respectivamente, inicia-tivas o propuestas al Consejo\"</span>. Pueden presentar iniciativas o propuestas al Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3209","p":"Tratado de la Unión Europea. Comité Político y de Seguridad. Un Comité Político y de Seguridad seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo, bien a instancia de éste, del Alto Representante o:","o":["por propia iniciativa.","a petición del Consejo Europeo.","a propuesta de la Comisión.","a petición del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por propia iniciativa</mark></span>El <span class=\"ref-norma\">art. 38 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"bien a instancia de éste, del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad o por propia iniciativa\"</span>. Emite dictámenes a instancia del Consejo, del Alto Representante o por propia iniciativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3219","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. La política común de seguridad y defensa forma parte integrante de la política exterior y de seguridad común y ofrecerá a la Unión una capacidad operativa basada en medios:","o":["militares y de inteligencia.","diplomáticos y militares.","civiles y militares.","civiles y policiales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">civiles y militares</mark></span>El <span class=\"ref-norma\">art. 42.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Ofrecerá a la Unión una capacidad operativa basada en medios civiles y militares\"</span>. Medios civiles y militares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3220","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. La política común de seguridad y defensa incluirá la definición progresiva de una política común de defensa de la Unión, que conducirá a una defensa común una vez que el Consejo Europeo lo haya decidido:","o":["por mayoría cualificada.","por unanimidad.","por mayoría de dos tercios.","a propuesta de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad</mark></span>El <span class=\"ref-norma\">art. 42.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Ésta conducirá a una defensa común una vez que el Consejo Europeo lo haya decidido por unanimidad\"</span>. Hace falta unanimidad del Consejo Europeo y recomendación a los Estados para su adopción conforme a sus normas constitucionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3221","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. La política de la Unión en materia de seguridad y defensa respetará las obligaciones derivadas del Tratado del Atlántico Norte para determinados Estados miembros que consideran que su defensa común se realiza dentro de la OTAN y:","o":["será compatible con la política común de seguridad y de defensa establecida en dicho marco.","prevalecerá sobre los compromisos adquiridos en el marco de dicha organización, en los términos que establezca la propia norma.","sustituirá progresivamente a los compromisos adquiridos en dicha organización.","se coordinará con los compromisos de dicha organización mediante un protocolo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">será compatible con la política común de seguridad y de defensa establecida en dicho marco</mark></span>El <span class=\"ref-norma\">art. 42.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"será compatible con la política común de seguridad y de defensa establecida en dicho marco\"</span>. Debe ser compatible con la política de seguridad de la OTAN. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3223","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. El Consejo adoptará por unanimidad las decisiones relativas a la política común de seguridad y defensa, incluidas las relativas al inicio de una misión, a propuesta del Alto Representante o:","o":["a iniciativa del Consejo Europeo.","a propuesta de la Comisión.","a iniciativa de un Estado miembro.","a iniciativa del Comité Político y de Seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a iniciativa de un Estado miembro</mark></span>El <span class=\"ref-norma\">art. 42.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad o a iniciativa de un Estado miembro\"</span>. A propuesta del Alto Representante o a iniciativa de un Estado miembro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3224","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. El Consejo podrá encomendar la realización de una misión, en el marco de la Unión, a un grupo de Estados miembros a fin de:","o":["garantizar la seguridad y la integridad territorial de la Unión.","defender los valores y favorecer los intereses de la Unión.","asegurar el mantenimiento de la paz y la prevención de conflictos.","proteger los intereses nacionales de los Estados participantes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">defender los valores y favorecer los intereses de la Unión</mark></span>El <span class=\"ref-norma\">art. 42.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a fin de defender los valores y favorecer los intereses de la Unión\"</span>. La finalidad es defender los valores y favorecer los intereses de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3225","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. Los Estados miembros que cumplan criterios más elevados de capacidades militares y que hayan suscrito compromisos más vinculantes en la materia para realizar las misiones más exigentes establecerán:","o":["una cooperación estructurada permanente en el marco de la Unión.","una cooperación reforzada en materia de defensa en el marco de la Unión.","una agencia de capacidades militares en el marco de la Unión.","un cuartel general permanente en el marco de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una cooperación estructurada permanente en el marco de la Unión</mark></span>El <span class=\"ref-norma\">art. 42.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"establecerán una cooperación estructurada permanente en el marco de la Unión\"</span>. Es la cooperación estructurada permanente (PESCO). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3226","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. Si un Estado miembro es objeto de una agresión armada en su territorio, los demás Estados miembros le deberán ayuda y asistencia con todos los medios a su alcance, de conformidad con:","o":["el Tratado del Atlántico Norte.","el Tratado de Funcionamiento de la Unión Europea.","el Protocolo sobre la cooperación estructurada permanente.","la Carta de las Naciones Unidas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la Carta de las Naciones Unidas</mark></span>El <span class=\"ref-norma\">art. 42.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de conformidad con el artículo 51 de la Carta de las Naciones Unidas\"</span>. Es la cláusula de asistencia mutua, conforme al artículo 51 de la Carta de la ONU. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3645","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. El Comité Económico y Social será convocado por su Presidente, a instancia del Parlamento Europeo, del Consejo o de la Comisión y:","o":["también podrá reunirse por propia iniciativa.","solo podrá reunirse a instancia de estas instituciones.","también podrá ser convocado por el Consejo Europeo.","también podrá reunirse a instancia de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">también podrá reunirse por propia iniciativa</mark></span>El <span class=\"ref-norma\">art. 303 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"También podrá reunirse por propia iniciativa\"</span>. Puede reunirse por propia iniciativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3650","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. El Comité de las Regiones designará de entre sus miembros al Presidente y a la Mesa, por un período de dos años y medio, establecerá su reglamento interno y será convocado por su Presidente a instancia del Parlamento Europeo, del Consejo o de la Comisión; también:","o":["podrá reunirse a instancia del Comité Económico y Social.","podrá reunirse a instancia de los Estados miembros.","podrá reunirse a instancia del Consejo Europeo.","podrá reunirse por propia iniciativa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrá reunirse por propia iniciativa</mark></span>El <span class=\"ref-norma\">art. 306 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"También podrá reunirse por propia iniciativa\"</span>. Igual que el CESE, puede reunirse por propia iniciativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 15 — Consejo Europeo y su Presidente EXOF","q":[{"i":"3-14","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. El Consejo Europeo. Señale la CORRECTA.","o":["Ejerce funciones de control político y consultivas, en las condiciones establecidas en los Tratados.","Mediará en los litigios entre los Estados y las restantes instituciones para que las instituciones se sitúen de inicio.","Dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales.","Ejerce funciones de definición de políticas y de coordinación, en las condiciones establecidas en los Tratados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales</mark></span>El <span class=\"ref-norma\">art. 15.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El CONSEJO EUROPEO dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales. No ejercerá función legislativa alguna\"</span>. El artículo 15.1 del TUE establece que el Consejo Europeo dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales, precisando además que no ejercerá función legislativa alguna."},{"i":"3-37","p":"Tratado de la Unión Europea. El Presidente del Consejo Europeo: Señale la incorrecta.","o":["Presidirá e impulsará los trabajos del Consejo Europeo.","Velará por la preparación y continuidad de los trabajos del Consejo Europeo, en cooperación con el Presidente de la Comisión y basándose en los trabajos del Consejo de Asuntos Generales.","Se esforzará por facilitar la cohesión y el consenso en el seno del Consejo Europeo.","Al término de cada reunión del Consejo Europeo, presentará un informe a la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al término de cada reunión del Consejo Europeo, presentará un informe a la Comisión</mark></span>El <span class=\"ref-norma\">art. 15.6 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Velará por la preparación y continuidad de los trabajos del Consejo Europeo, en cooperación con el Presidente de la Comisión y basándose en los trabajos del Consejo de Asuntos Generales. \u0007Esforzará por facilitar la cohesión y el consenso en el seno del Consejo Europeo. \u0007Al término de cada reunión presentará un informe al Parlamento Europeo\"</span>. El artículo 15.6.d) del TUE establece que el Presidente del Consejo Europeo, al término de cada reunión del Consejo Europeo, presentará un informe al Parlamento Europeo, y no a la Comisión."},{"i":"3-38","p":"Tratado de la Unión Europea. El Consejo Europeo se reunirá:","o":["Una vez por semestre por convocatoria de su Presidente.","Dos veces por semestre por convocatoria de su Presidente.","Dos veces al año por convocatoria de su Presidente.","Una vez al mes por convocatoria de su Presidente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos veces por semestre por convocatoria de su Presidente</mark></span>El <span class=\"ref-norma\">art. 15.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente. Cuando el orden del día lo exija, los miembros del Consejo Europeo podrán decidir contar, cada uno de ellos, con la asistencia de un ministro y, en el caso del Presidente de la Comisión, con la de un miembro de la Comisión. Cuando la situación lo exija, el Presidente convocará una reunión extraordinaria del Consejo Europeo\"</span>. El artículo 15.3 del TUE dispone que el Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente."},{"i":"3-39","p":"Tratado de la Unión Europea. El Consejo Europeo estará compuesto por:","o":["Los Jefes de Estado o de Gobierno de los Estados miembros, por su Presidente y por el Presidente de la Comisión, así como por el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","Los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión. Participa en sus trabajos el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","Un representante de cada Estado miembro, de rango ministerial, facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto.","Por un representante de cada Estado miembro, facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho al voto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión. Participa en sus trabajos el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 15.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo estará compuesto por los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión. Participará en sus trabajos el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad\"</span>. El artículo 15.2 del TUE dispone que el Consejo Europeo estará compuesto por los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión, participando en sus trabajos el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, sin ser miembro de pleno derecho."},{"i":"3-147","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. La representación exterior de la Unión en los asuntos de política exterior y de seguridad común, sin perjuicio de las atribuciones del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, la asumirá, en su rango y condición:","o":["El Presidente del Consejo.","El Presidente del Consejo Europeo.","El Consejo de Asuntos Exteriores.","A y C son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente del Consejo Europeo</mark></span>Solo el Presidente del Consejo Europeo; ni el Presidente del Consejo ni el Consejo de Asuntos Exteriores. Según el <span class=\"ref-norma\">art. 15.6 del TUE</span>: <span class=\"ref-concepto\">\"El Presidente del Consejo Europeo asumirá, en su rango y condición, la representación exterior de la Unión en los asuntos de política exterior y de seguridad común, sin perjuicio de las atribuciones del Alto Representante...\"</span> (verificado con el texto del temario)."},{"i":"3-152","p":"Tratado de la Unión Europea. El Consejo Europeo elegirá a su Presidente por ______ para un mandato de dos años y medio, que podrá renovarse una sola vez.","o":["Mayoría simple.","Mayoría cualificada.","Mayoría absoluta.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mayoría cualificada</mark></span>El <span class=\"ref-norma\">art. 15.5 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez. En caso de impedimento o falta grave, el Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El artículo 15.5 del TUE establece que el Consejo Europeo elegirá a su Presidente por mayoría cualificada, para un mandato de dos años y medio, renovable una sola vez."},{"i":"3-194","p":"Tratado de la Unión Europea. El mandato del Presidente del Consejo Europeo es de:","o":["Dos años.","Dos años y medio.","Cuatro años.","Cinco años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos años y medio</mark></span>El <span class=\"ref-norma\">art. 15.5 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez. En caso de impedimento o falta grave, el Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El artículo 15.5 del TUE establece que el Consejo Europeo elegirá a su Presidente por mayoría cualificada para un mandato de dos años y medio, que podrá renovarse una sola vez."},{"i":"3-230","p":"Tratado de la Unión Europea. ¿Cómo se pronunciará el Consejo Europeo, excepto cuando los Tratados dispongan otra cosa?","o":["Por consenso.","Por unanimidad.","Por mayoría cualificada.","Por mayoría de tres cuartos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por consenso</mark></span>El <span class=\"ref-norma\">art. 15.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo se pronunciará por consenso, excepto cuando los Tratados dispongan otra cosa\"</span>. El artículo 15.4 del TUE establece que el Consejo Europeo se pronunciará por consenso, excepto cuando los Tratados dispongan otra cosa."},{"i":"3-270","p":"Tratado de Funcionamiento de la Unión Europea. El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de: señale la INCORRECTA.","o":["De uno de sus miembros.","Del Consejo Europeo.","Del Presidente del Consejo.","De la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 15.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente. Cuando el orden del día lo exija, los miembros del Consejo Europeo podrán decidir contar, cada uno de ellos, con la asistencia de un ministro y, en el caso del Presidente de la Comisión, con la de un miembro de la Comisión. Cuando la situación lo exija, el Presidente convocará una reunión extraordinaria del Consejo Europeo\"</span>. El artículo 237 del TFUE establece que el Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión, sin mencionar al Consejo Europeo entre quienes pueden instar dicha convocatoria."},{"i":"3-363","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Parlamento Europeo. La Comisión podrá asistir a todas las sesiones del Parlamento Europeo y comparecerá ante éste:","o":["Anualmente.","Cada semestre.","Si así lo solicita.","Solo en las sesiones extraordinarias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Si así lo solicita</mark></span>El <span class=\"ref-norma\">art. 230 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La Comisión podrá asistir a todas las sesiones del Parlamento Europeo y comparecerá ante éste si así lo solicita\"</span>. Comparece si el Parlamento así lo solicita."},{"i":"3-369","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. La Comisión. Las responsabilidades que incumben a la Comisión serán estructuradas y repartidas entre sus miembros por:","o":["El Presidente, que podrá reorganizar el reparto a lo largo de su mandato.","El Consejo Europeo, a propuesta del Presidente y por mayoría cualificada.","El Parlamento Europeo, previa consulta al Presidente de la Comisión.","El Colegio de Comisarios por mayoría de sus miembros, a iniciativa del Presidente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente, que podrá reorganizar el reparto a lo largo de su mandato</mark></span>El <span class=\"ref-norma\">art. 248 del TFUE</span> dispone: <span class=\"ref-concepto\">\"serán estructuradas y repartidas entre sus miembros por el Presidente\"</span>. Lo hace el Presidente."},{"i":"3-ia-3056","p":"Tratado de la Unión Europea. Consejo Europeo. El Consejo Europeo dará a la Unión los impulsos necesarios para su desarrollo y definirá sus orientaciones y prioridades políticas generales; en cuanto a la función legislativa:","o":["ejercerá la función legislativa junto con el Consejo.","no ejercerá función legislativa alguna.","ejercerá la función legislativa en materias de política exterior.","ejercerá la función legislativa por delegación del Parlamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no ejercerá función legislativa alguna</mark></span>El <span class=\"ref-norma\">art. 15.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"No ejercerá función legislativa alguna\"</span>. El Consejo Europeo no ejerce función legislativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3057","p":"Tratado de la Unión Europea. Consejo Europeo. El Consejo Europeo estará compuesto por los Jefes de Estado o de Gobierno de los Estados miembros, así como por su Presidente y por el Presidente de la Comisión; en sus trabajos participará:","o":["el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","el Presidente del Parlamento Europeo y el Alto Representante.","el Presidente del Consejo de la Unión y el Alto Representante.","el Presidente del Banco Central Europeo en materias monetarias, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 15.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Participará en sus trabajos el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad\"</span>. Participa en sus trabajos el Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3058","p":"Tratado de la Unión Europea. Consejo Europeo. El Consejo Europeo se reunirá por convocatoria de su Presidente:","o":["una vez por trimestre, salvo que se disponga otra cosa en la normativa aplicable.","dos veces al año.","una vez por semestre.","dos veces por semestre."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">dos veces por semestre</mark></span>El <span class=\"ref-norma\">art. 15.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo se reunirá dos veces por semestre por convocatoria de su Presidente\"</span>. Dos veces por semestre, con reuniones extraordinarias cuando la situación lo exija. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3059","p":"Tratado de la Unión Europea. Consejo Europeo. El Consejo Europeo se pronunciará por consenso, excepto cuando los Tratados dispongan otra cosa, y elegirá a su Presidente por mayoría cualificada para un mandato de:","o":["dos años y medio, que podrá renovarse dos veces, conforme al procedimiento que se establezca reglamentariamente.","cinco años, que podrá renovarse una sola vez.","dos años y medio, que podrá renovarse una sola vez.","dos años, que podrá renovarse una sola vez."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos años y medio, que podrá renovarse una sola vez</mark></span>El <span class=\"ref-norma\">art. 15.4 y 5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"para un mandato de dos años y medio, que podrá renovarse una sola vez\"</span>. Dos años y medio, renovable una sola vez. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3060","p":"Tratado de la Unión Europea. Consejo Europeo. El Presidente del Consejo Europeo presidirá e impulsará los trabajos del Consejo Europeo, velará por su preparación y continuidad, se esforzará por facilitar la cohesión y el consenso y, al término de cada reunión:","o":["presentará un informe al Consejo de la Unión.","presentará un informe al Parlamento Europeo.","presentará un informe a la Comisión Europea.","presentará un informe a los Parlamentos nacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">presentará un informe al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 15.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"al término de cada reunión del Consejo Europeo, presentará un informe al Parlamento Europeo\"</span>. Informa al Parlamento Europeo tras cada reunión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3061","p":"Tratado de la Unión Europea. Consejo Europeo. El Presidente del Consejo Europeo asumirá, en su rango y condición, la representación exterior de la Unión en los asuntos de política exterior y de seguridad común, sin perjuicio de las atribuciones del Alto Representante; además:","o":["no podrá ejercer mandato nacional alguno.","podrá ejercer mandato nacional previa autorización del Consejo Europeo.","no podrá ejercer función ejecutiva en el Estado de su nacionalidad.","podrá ejercer mandato nacional compatible con sus funciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no podrá ejercer mandato nacional alguno</mark></span>El <span class=\"ref-norma\">art. 15.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Consejo Europeo no podrá ejercer mandato nacional alguno\"</span>. No puede ejercer mandato nacional alguno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3125","p":"Tratado de la Unión Europea. El Alto Representante. El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, y podrá poner fin a su mandato:","o":["por el mismo procedimiento.","por unanimidad.","por mayoría simple.","a propuesta del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por el mismo procedimiento</mark></span>El <span class=\"ref-norma\">art. 18.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El cese se acuerda por el mismo procedimiento que el nombramiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 256 y 257 TFUE — Tribunal General y tribunales especializados EXOF ✱","q":[{"i":"3-16","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales, financieras. Instituciones. El Tribunal de Justicia de la Unión Europea. El Tribunal General será competente para conocer en primera instancia de los recursos de su competencia. Contra las resoluciones dictadas por el Tribunal General en virtud del artículo 256 podrá interponerse: Seleccione la correcta.","o":["Recurso de casación ante el Tribunal de Justicia, limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto.","Recurso de alzada ante el Tribunal de Justicia, limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto.","Recurso extraordinario de oposición ante el Tribunal de Justicia, limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto.","No cabrá recurso alguno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Recurso de casación ante el Tribunal de Justicia, limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto</mark></span>El <span class=\"ref-norma\">art. 256.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Contra las resoluciones dictadas por el Tribunal General en virtud del presente apartado podrá interponerse recurso de casación ante el Tribunal de Justicia limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto\"</span>. El artículo 256.1 del TFUE dispone que contra las resoluciones dictadas por el Tribunal General en primera instancia podrá interponerse recurso de casación ante el Tribunal de Justicia, limitado a las cuestiones de Derecho, en las condiciones y dentro de los límites fijados en el Estatuto."},{"i":"3-51","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia de la Unión Europea. ¿Quiénes podrán crear tribunales especializados adjuntos al Tribunal General?","o":["El Consejo y el Tribunal de Justicia de la Unión Europea.","El Parlamento y el Tribunal de Justicia de la Unión Europea.","El Parlamento Europeo y el Consejo.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo</mark></span>El <span class=\"ref-norma\">art. 257 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, podrán crear tribunales especializados adjuntos al Tribunal General, encargados de conocer en primera instancia de determinadas categorías de recursos interpuestos en materias específicas\"</span>. El artículo 257 del TFUE atribuye al Parlamento Europeo y al Consejo, con arreglo al procedimiento legislativo ordinario, la facultad de crear tribunales especializados adjuntos al Tribunal General."},{"i":"3-151","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea. Los miembros de los tribunales especializados serán elegidos entre personas que ofrezcan absolutas garantías de independencia y que posean la capacidad necesaria para el ejercicio de funciones jurisdiccionales. Señale la correcta.","o":["Serán designados por el Consejo por unanimidad.","Serán designados por la Comisión por unanimidad.","Serán designados por el Consejo por mayoría cualificada.","Serán designados por la Comisión por mayoría cualificada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Serán designados por el Consejo por unanimidad</mark></span>Según el <span class=\"ref-norma\">art. 257 del TFUE</span>: <span class=\"ref-concepto\">\"Los miembros de los tribunales especializados serán elegidos entre personas que ofrezcan absolutas garantías de independencia y que posean la capacidad necesaria para el ejercicio de funciones jurisdiccionales. Serán designados por el Consejo por unanimidad.\"</span> (verificado con el texto del temario)."},{"i":"3-269","p":"Tratado de Funcionamiento de la Unión Europea. Los miembros de los tribunales especializados serán elegidos entre personas que ofrezcan plenas garantías de independencia y que posean la capacidad necesaria para el ejercicio de funciones jurisdiccionales. Serán designados por el Consejo:","o":["Por unanimidad.","Por mayoría simple.","Por mayoría cualificada.","Por consenso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por unanimidad</mark></span>El <span class=\"ref-norma\">art. 257 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los miembros de los tribunales especializados serán elegidos entre personas que ofrezcan absolutas garantías de independencia y que posean la capacidad necesaria para el ejercicio de funciones jurisdiccionales. Serán designados por el Consejo por unanimidad\"</span>. El artículo 257 del TFUE dispone que los miembros de los tribunales especializados \"serán designados por el Consejo por unanimidad\"."},{"i":"3-ia-3545","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal General. El Tribunal General será competente para conocer en primera instancia de determinados recursos, con excepción de los que se atribuyan a un tribunal especializado y de los que el Estatuto reserve al Tribunal de Justicia; contra sus resoluciones podrá interponerse:","o":["recurso de casación ante el Tribunal de Justicia limitado a las cuestiones de Derecho.","recurso de apelación ante el Tribunal de Justicia sobre los hechos y el Derecho, en los términos que establezca la propia norma.","recurso de revisión ante el Consejo sobre las cuestiones de Derecho.","recurso de anulación ante el propio Tribunal General en Pleno."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">recurso de casación ante el Tribunal de Justicia limitado a las cuestiones de Derecho</mark></span>El <span class=\"ref-norma\">art. 256.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá interponerse recurso de casación ante el Tribunal de Justicia limitado a las cuestiones de Derecho\"</span>. Casación ante el Tribunal de Justicia limitada a cuestiones de Derecho. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3547","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal General. El Tribunal General será competente para conocer de las cuestiones prejudiciales en materias específicas determinadas por el Estatuto; cuando considere que el asunto requiere una resolución de principio que pueda afectar a la unidad o a la coherencia del Derecho de la Unión:","o":["deberá suspender el procedimiento y consultar a la Comisión.","podrá solicitar al Parlamento Europeo una interpretación auténtica, conforme al procedimiento que se establezca reglamentariamente.","podrá remitir el asunto ante el Tribunal de Justicia para que éste resuelva.","deberá devolver el asunto al órgano jurisdiccional nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá remitir el asunto ante el Tribunal de Justicia para que éste resuelva</mark></span>El <span class=\"ref-norma\">art. 256.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá remitir el asunto ante el Tribunal de Justicia para que éste resuelva\"</span>. Puede remitirlo al Tribunal de Justicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3548","p":"Tratado de Funcionamiento de la Unión Europea. Tribunales especializados. El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, podrán crear tribunales especializados adjuntos al Tribunal General, encargados de conocer en primera instancia de determinadas categorías de recursos interpuestos en materias específicas, mediante reglamentos, a propuesta de la Comisión y previa consulta al Tribunal de Justicia o:","o":["a instancia del Tribunal General y previa aprobación de la Comisión.","a instancia del Tribunal de Justicia y previa consulta a la Comisión.","a iniciativa del Consejo Europeo y previa consulta al Tribunal de Justicia.","a propuesta de la Comisión y previa aprobación del Tribunal de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a instancia del Tribunal de Justicia y previa consulta a la Comisión</mark></span>El <span class=\"ref-norma\">art. 257 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"bien a instancia del Tribunal de Justicia y previa consulta a la Comisión\"</span>. Dos vías: propuesta de la Comisión (consulta al Tribunal) o instancia del Tribunal (consulta a la Comisión). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3549","p":"Tratado de Funcionamiento de la Unión Europea. Tribunales especializados. Contra las resoluciones dictadas por los tribunales especializados podrá interponerse ante el Tribunal General recurso de casación limitado a las cuestiones de Derecho o, cuando el reglamento de creación así lo contemple:","o":["recurso de apelación referente también a las cuestiones de hecho.","recurso de revisión ante el Tribunal de Justicia.","recurso de anulación ante el propio tribunal especializado, en los términos que establezca la propia norma.","recurso de alzada ante el Consejo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">recurso de apelación referente también a las cuestiones de hecho</mark></span>El <span class=\"ref-norma\">art. 257 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"o, cuando el reglamento relativo a la creación del tribunal especializado así lo contemple, recurso de apelación referente también a las cuestiones de hecho\"</span>. Casación (Derecho) o, si el reglamento lo prevé, apelación (también hechos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3550","p":"Tratado de Funcionamiento de la Unión Europea. Tribunales especializados. Los miembros de los tribunales especializados serán elegidos entre personas que ofrezcan absolutas garantías de independencia y que posean la capacidad necesaria para el ejercicio de funciones jurisdiccionales, y serán designados:","o":["por el Consejo por mayoría cualificada.","de común acuerdo por los Gobiernos de los Estados miembros.","por el Parlamento Europeo por mayoría absoluta.","por el Consejo por unanimidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por el Consejo por unanimidad</mark></span>El <span class=\"ref-norma\">art. 257 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Serán designados por el Consejo por unanimidad\"</span>. Los designa el Consejo por unanimidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 43 — Misiones PCSD EXOF","q":[{"i":"3-20","p":"Tratado de la Unión Europea. Se hará cargo de la coordinación de los aspectos civiles y militares de las misiones fuera de la Unión que tengan por objeto garantizar el mantenimiento de la paz, la prevención de conflictos y el fortalecimiento de la seguridad internacional:","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Parlamento Europeo y en contacto estrecho y permanente con el Comité Político y de Seguridad.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Comité Político y de Seguridad.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Consejo.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, con el apoyo de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Comité Político y de Seguridad</mark></span>El <span class=\"ref-norma\">art. 43.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Comité Político y de Seguridad, se hará cargo de la coordinación de los aspectos civiles y militares de dichas misiones\"</span>. El artículo 43.2 del TUE establece que el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Comité Político y de Seguridad, se hará cargo de la coordinación de los aspectos civiles y militares de dichas misiones."},{"i":"3-ia-3228","p":"Tratado de la Unión Europea. Misiones de la política común de seguridad y defensa. Las misiones en las que la Unión podrá recurrir a medios civiles y militares abarcarán las actuaciones conjuntas en materia de desarme, las misiones humanitarias y de rescate, las misiones de asesoramiento y asistencia en cuestiones militares, las de prevención de conflictos y mantenimiento de la paz, las de fuerzas de combate para la gestión de crisis y:","o":["las operaciones de vigilancia de las fronteras exteriores.","las operaciones de estabilización al término de los conflictos.","las operaciones de protección civil en catástrofes naturales, sin perjuicio de lo dispuesto en otras disposiciones.","las operaciones de control de armamentos en terceros países."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las operaciones de estabilización al término de los conflictos</mark></span>El <span class=\"ref-norma\">art. 43.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"incluidas las misiones de restablecimiento de la paz y las opera-ciones de estabilización al término de los conflictos\"</span>. Incluyen las operaciones de estabilización al término de los conflictos (misiones Petersberg). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 46 TFUE — Medidas sobre trabajadores ✱","q":[{"i":"3-21","p":"Tratado de Funcionamiento de la Unión Europea. Adoptarán, mediante directivas o reglamentos, las medidas necesarias a fin de hacer efectiva la libre circulación de los trabajadores:","o":["El Parlamento Europeo o el Consejo Europeo.","El Parlamento Europeo, con arreglo al procedimiento legislativo ordinario, previa consulta al Comité Económico y Social.","El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, previa consulta al Comité Económico y Social.","El Consejo y la Comisión previa consulta al Comité Económico y Social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, previa consulta al Comité Económico y Social</mark></span>El <span class=\"ref-norma\">art. 46 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, adoptarán, mediante directivas o reglamentos, las medidas necesarias a fin de hacer efectiva la libre circulación de los trabajadores, tal como queda definida en el artículo 45, en especial\"</span>. El artículo 46 del TFUE atribuye al Parlamento Europeo y al Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, la adopción mediante directivas o reglamentos de las medidas necesarias para hacer efectiva la libre circulación de los trabajadores."},{"i":"3-83","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién deberá adoptar las medidas necesarias a fin de hacer efectiva la libre circulación de los trabajadores?","o":["El Parlamento Europeo y el Consejo Europeo, con arreglo al procedimiento legislativo especial y previa consulta al Comité Económico y Social.","El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social.","El Parlamento Europeo y el Consejo Europeo con arreglo al procedimiento legislativo especial y previa consulta al Comité de las Regiones.","El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité de las Regiones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social</mark></span>El <span class=\"ref-norma\">art. 46 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, adoptarán, mediante directivas o reglamentos, las medidas necesarias a fin de hacer efectiva la libre circulación de los trabajadores, tal como queda definida en el artículo 45, en especial\"</span>. El artículo 46 del TFUE atribuye al Parlamento Europeo y al Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, la adopción de las medidas necesarias para hacer efectiva la libre circulación de los trabajadores."},{"i":"3-ia-3254","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, adoptarán directivas para la coordinación de las disposiciones que prevean un régimen especial para los extranjeros por razones de orden público, seguridad y salud públicas, mediante:","o":["reglamentos.","decisiones.","recomendaciones.","directivas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">directivas</mark></span>El <span class=\"ref-norma\">art. 52.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"adoptarán directivas para la coordinación de las mencionadas disposiciones\"</span>. Se coordinan mediante directivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 226 a 228 TFUE — Investigación, petición y Defensor del Pueblo EXOF ✱","q":[{"i":"3-23","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. El Parlamento Europeo elegirá a un Defensor del Pueblo Europeo, que estará facultado para recibir las reclamaciones de cualquier ciudadano de la Unión o de cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, relativas a:","o":["Casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales.","Casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión del Consejo Europeo y el Tribunal de Justicia de la Unión Europea.","Casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión con exclusión del Consejo Europeo respecto a temas de Defensa Nacional.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales</mark></span>El <span class=\"ref-norma\">art. 228.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo elegirá a un Defensor del Pueblo Europeo, que estará facultado para recibir las reclamaciones de cualquier ciudadano de la Unión o de cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, relativas a casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales\"</span>. El artículo 228.1 del TFUE establece que el Defensor del Pueblo Europeo estará facultado para recibir reclamaciones relativas a casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales."},{"i":"3-93","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién será competente para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, si dicha controversia le es sometida en virtud de un compromiso?","o":["El Presidente del Parlamento Europeo.","El Presidente del Consejo.","El Tribunal de Justicia.","A y B son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 273 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia será competente para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, si dicha controversia le es sometida en virtud de un compromiso\"</span>. El artículo 273 del TFUE atribuye al Tribunal de Justicia la competencia para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, siempre que dicha controversia le sea sometida en virtud de un compromiso."},{"i":"3-115","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. Señale la incorrecta:","o":["Será ciudadano de la Unión toda persona que resida en un estado miembro.","La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla.","El funcionamiento de la Unión se basa en la democracia representativa.","Las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones representativas y la sociedad civil."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Será ciudadano de la Unión toda persona que resida en un estado miembro</mark></span>El <span class=\"ref-norma\">art. 9 del TUE</span> dispone: <span class=\"ref-concepto\">\"Será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro. La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla\"</span>. La opción correcta es la A, por ser la incorrecta. El artículo 9 del TUE establece que será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro, no toda persona que simplemente resida en él."},{"i":"3-226","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo. Señale la INCORRECTA.","o":["Cualquier ciudadano de la Unión, así como cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, tendrá derecho a presentar al Parlamento Europeo, individualmente o asociado con otros ciudadanos o personas, una petición sobre un asunto propio de los ámbitos de actuación de la Unión que le afecte directamente.","Por decisión de la mayoría de los miembros que lo componen, el Parlamento Europeo podrá solicitar a la Comisión que presente las propuestas oportunas sobre cualquier asunto que a juicio de aquel requiera la elaboración de un acto de la Unión para la aplicación de los Tratados.","El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, establecerán mediante reglamentos el estatuto de los partidos políticos a escala europea.","En cumplimiento de sus cometidos y a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los Tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, incluso cuando un órgano jurisdiccional esté conociendo de los hechos alegados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">En cumplimiento de sus cometidos y a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los Tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, incluso cuando un órgano jurisdiccional esté conociendo de los hechos alegados</mark></span>El <span class=\"ref-norma\">art. 226 del TFUE</span> dispone: <span class=\"ref-concepto\">\"En cumplimiento de sus cometidos y a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los Tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, salvo que de los hechos alegados esté conociendo un órgano jurisdiccional, hasta tanto concluya el procedimiento jurisdiccional\"</span>. (The INCORRECT part is the last clause: the committee may not intervene when an administrative or judicial body is already seized of the facts.)"},{"i":"3-245","p":"Tratado de Funcionamiento de la Unión Europea. ¿Cuándo será elegido el Defensor del Pueblo Europeo?","o":["Será elegido después de cada elección del Parlamento Europeo para toda la legislatura.","Será elegido después de cada elección del Consejo para toda la legislatura.","Será elegido después de cada elección de la Comisión para toda la legislatura.","Será elegido después de cada elección del Consejo Europeo para toda la legislatura."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Será elegido después de cada elección del Parlamento Europeo para toda la legislatura</mark></span>El <span class=\"ref-norma\">art. 228.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Defensor del Pueblo será elegido después de cada elección del Parlamento Europeo para toda la legislatura. Su mandato será renovable. \u0007A petición del Parlamento Europeo, el Tribunal de Justicia podrá destituir al Defensor del Pueblo si éste dejare de cumplir las condiciones necesarias para el ejercicio de sus funciones o hubiere cometido una falta grave\"</span>. El artículo 228.2 del TFUE establece que el Defensor del Pueblo será elegido después de cada elección del Parlamento Europeo para toda la legislatura, y que su mandato será renovable."},{"i":"3-282","p":"Tratado de Funcionamiento de la Unión Europea. En cumplimiento de sus cometidos y a petición de _____ el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los Tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, salvo que de los hechos alegados esté conociendo un órgano jurisdiccional, hasta tanto concluya el procedimiento jurisdiccional.","o":["la cuarta parte de los miembros que lo componen.","la mitad de los miembros que lo componen.","la quinta parte de los miembros que lo componen.","la tercera parte de los miembros que lo componen."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la cuarta parte de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 226 del TFUE</span> dispone: <span class=\"ref-concepto\">\"En cumplimiento de sus cometidos y a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar, sin perjuicio de las competencias que los Tratados confieren a otras instituciones u órganos, alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, salvo que de los hechos alegados esté conociendo un órgano jurisdiccional, hasta tanto concluya el procedimiento jurisdiccional\"</span>. El artículo 226 del TFUE establece que el Parlamento Europeo, a petición de la cuarta parte de los miembros que lo componen, podrá constituir una comisión temporal de investigación."},{"i":"3-290","p":"Tratado de Funcionamiento de la Unión Europea. El Defensor del Pueblo presentará _____ un informe sobre el resultado de sus investigaciones.","o":["Cada año al Parlamento Europeo.","Cada seis meses a la Comisión.","Cada seis meses al Parlamento Europeo.","Cada año a la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cada año al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 228.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones\"</span>. El artículo 228.1 del TFUE establece que el Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones."},{"i":"3-291","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo. Señale la CORRECTA:","o":["El Defensor del Pueblo será elegido después de cada elección del Parlamento Europeo para toda la legislatura. Su mandato no será renovable.","A petición de la Comisión, el Tribunal de Justicia podrá destituir al Defensor del Pueblo si este dejare de cumplir las condiciones necesarias para el ejercicio de sus funciones o hubiere cometido una falta grave.","El Parlamento Europeo fijará, mediante reglamentos adoptados por propia iniciativa, con arreglo a un procedimiento legislativo especial, el estatuto y las condiciones generales de ejercicio de las funciones del Defensor del Pueblo, previo dictamen del Consejo y con la aprobación de la Comisión.","El Defensor del Pueblo ejercerá sus funciones con total independencia. En el ejercicio de tales funciones no solicitará ni admitirá instrucciones de ningún gobierno, institución, órgano u organismo. Durante su mandato, el Defensor del Pueblo no podrá desempeñar ninguna otra actividad profesional, sea o no retribuida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Defensor del Pueblo ejercerá sus funciones con total independencia. En el ejercicio de tales funciones no solicitará ni admitirá instrucciones de ningún gobierno, institución, órgano u organismo. Durante su mandato, el Defensor del Pueblo no podrá desempeñar ninguna otra actividad profesional, sea o no retribuida</mark></span>A falla (el mandato SÍ es renovable), B falla (la destitución es a petición del PARLAMENTO EUROPEO) y C invierte dictamen y aprobación (previo dictamen de la Comisión y aprobación del Consejo). Según el <span class=\"ref-norma\">art. 228.3 del TFUE</span>: <span class=\"ref-concepto\">\"El Defensor del Pueblo ejercerá sus funciones con total independencia. En el ejercicio de tales funciones no solicitará ni admitirá instrucciones de ningún gobierno, institución, órgano u organismo. Durante su mandato, el Defensor del Pueblo no podrá desempeñar ninguna otra actividad profesional, sea o no retribuida.\"</span> (verificado con el texto del temario)."},{"i":"3-310","p":"Tratado de Funcionamiento de la Unión Europea. El Defensor del Pueblo presentará al Parlamento Europeo un informe sobre el resultado de sus investigaciones:","o":["Cada año.","Cada semestre.","Cada dos años.","Cada tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cada año</mark></span>El <span class=\"ref-norma\">art. 228.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones\"</span>. El artículo 228.1 TFUE establece que el Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones."},{"i":"3-362","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Parlamento Europeo. Cualquier ciudadano de la Unión, así como cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, tendrá derecho a presentar una petición sobre un asunto propio de los ámbitos de actuación de la Unión que le afecte directamente:","o":["A la Comisión.","Al Consejo.","Al Defensor del Pueblo Europeo.","Al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 227 del TFUE</span> dispone: <span class=\"ref-concepto\">\"tendrá derecho a presentar al Parlamento Europeo, individualmente o asociado con otros ciudadanos o personas, una petición\"</span>. El derecho de petición se ejerce ante el Parlamento Europeo."},{"i":"3-368","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. La Comisión. Los miembros de la Comisión no podrán, mientras dure su mandato, ejercer ninguna otra actividad profesional:","o":["Retribuida, salvo la docente.","Retribuida o no.","Retribuida, salvo con autorización del Consejo.","Distinta de la política."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Retribuida o no</mark></span>El <span class=\"ref-norma\">art. 245 del TFUE</span> dispone: <span class=\"ref-concepto\">\"no podrán, mientras dure su mandato, ejercer ninguna otra actividad profesional, retribuida o no\"</span>. Incompatibilidad absoluta con otra actividad profesional."},{"i":"3-377","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. La institución, órgano u organismo del que emane el acto anulado, o cuya abstención haya sido declarada contraria a los Tratados, estarán obligados a:","o":["Adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia de la Unión Europea.","Revisar el acto anulado y volver a adoptarlo con arreglo a la sentencia del Tribunal de Justicia de la Unión.","Comunicar la sentencia al Consejo Europeo para que decida sobre su ejecución en la Unión Europea.","Solicitar al Consejo la ejecución de la sentencia mediante un reglamento del Tribunal de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 266 del TFUE</span> dispone: <span class=\"ref-concepto\">\"estarán obligados a adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia de la Unión Europea\"</span>. Deben adoptar las medidas para ejecutar la sentencia."},{"i":"3-ia-3435","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. En cumplimiento de sus cometidos y a petición de la cuarta parte de los miembros que lo componen, el Parlamento Europeo podrá constituir una comisión temporal de investigación para examinar alegaciones de infracción o de mala administración en la aplicación del Derecho de la Unión, salvo que de los hechos alegados esté conociendo un órgano jurisdiccional, hasta tanto:","o":["se dicte resolución administrativa.","finalice el período de sesiones.","concluya el procedimiento jurisdiccional.","se emita el dictamen de la Comisión, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">concluya el procedimiento jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 226 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"hasta tanto concluya el procedimiento jurisdiccional\"</span>. No se puede investigar un asunto sub iudice. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3437","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. Cualquier ciudadano de la Unión, así como cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, tendrá derecho a presentar al Parlamento Europeo, individualmente o asociado con otros, una petición sobre un asunto:","o":["propio de los ámbitos de actuación de la Unión que le afecte directamente.","de interés general para los ciudadanos de la Unión y de los Estados miembros.","relacionado con la aplicación del Derecho de la Unión por los Estados miembros.","de competencia exclusiva de la Unión que afecte a los derechos fundamentales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">propio de los ámbitos de actuación de la Unión que le afecte directamente</mark></span>El <span class=\"ref-norma\">art. 227 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"una petición sobre un asunto propio de los ámbitos de actuación de la\"</span>. Asunto propio de los ámbitos de actuación de la Unión que le afecte directamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3438","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. El Parlamento Europeo elegirá a un Defensor del Pueblo Europeo, que estará facultado para recibir las reclamaciones de cualquier ciudadano de la Unión o de cualquier persona física o jurídica que resida o tenga su domicilio social en un Estado miembro, relativas a casos de mala administración en la acción de las instituciones, órganos u organismos de la Unión, con exclusión:","o":["del Banco Central Europeo en el ejercicio de sus funciones monetarias.","del Consejo Europeo en el ejercicio de sus funciones de orientación política, salvo que se disponga otra cosa en la normativa aplicable.","del Tribunal de Cuentas en el ejercicio de sus funciones de fiscalización.","del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales</mark></span>El <span class=\"ref-norma\">art. 228.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con exclusión del Tribunal de Justicia\"</span>. Excluye al Tribunal de Justicia en el ejercicio de sus funciones jurisdiccionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3439","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. Cuando el Defensor del Pueblo haya comprobado un caso de mala administración, lo pondrá en conocimiento de la institución, órgano u organismo interesado, que dispondrá de un plazo de tres meses para:","o":["subsanar la mala administración comprobada, conforme al procedimiento que se establezca reglamentariamente.","presentar un informe al Parlamento Europeo.","exponer su posición al Defensor del Pueblo.","abonar la indemnización que proceda."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">exponer su posición al Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 228.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"que dispondrá de un plazo de tres meses para exponer su posición al Defensor del Pueblo\"</span>. Tres meses para exponer su posición; luego el Defensor remite un informe al Parlamento y a la institución. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3440","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. El Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones, y en el desempeño de su misión llevará a cabo las investigaciones que considere justificadas, bien por iniciativa propia, bien sobre la base de las reclamaciones recibidas directamente o a través de un miembro del Parlamento Europeo, salvo que los hechos alegados:","o":["afecten a la seguridad de la Unión o de los Estados miembros.","sean o hayan sido objeto de un procedimiento jurisdiccional.","se hayan puesto en conocimiento previo de la institución afectada.","hayan sido objeto de una petición ante el Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sean o hayan sido objeto de un procedimiento jurisdiccional</mark></span>El <span class=\"ref-norma\">art. 228.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"salvo que los hechos alegados sean o hayan sido objeto de un procedimiento jurisdiccional\"</span>. No investiga asuntos que sean o hayan sido objeto de procedimiento jurisdiccional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3441","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. El Defensor del Pueblo será elegido después de cada elección del Parlamento Europeo para toda la legislatura, su mandato será renovable y, a petición del Parlamento Europeo, el Tribunal de Justicia podrá destituirlo si dejare de cumplir las condiciones necesarias para el ejercicio de sus funciones o:","o":["hubiere cometido una falta grave.","hubiere perdido la confianza del Consejo.","hubiere incumplido el deber de informe anual.","hubiere sido condenado por sentencia firme."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">hubiere cometido una falta grave</mark></span>El <span class=\"ref-norma\">art. 228.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"hubiere cometido una falta grave\"</span>. La destitución la acuerda el Tribunal de Justicia a petición del Parlamento por incumplir condiciones o falta grave. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3442","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. El Defensor del Pueblo ejercerá sus funciones con total independencia y, durante su mandato, no podrá desempeñar:","o":["ninguna otra actividad profesional retribuida.","ningún cargo público ni actividad política.","ninguna otra actividad profesional remunerada por un Estado.","ninguna otra actividad profesional, sea o no retribuida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ninguna otra actividad profesional, sea o no retribuida</mark></span>El <span class=\"ref-norma\">art. 228.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no podrá desempeñar ninguna otra actividad profesional, sea o no retribuida\"</span>. Incompatible con cualquier otra actividad profesional, retribuida o no. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 38 — Comité Político y de Seguridad EXOF","q":[{"i":"3-25","p":"Tratado de la Unión Europea. Bajo la responsabilidad del Consejo y del Alto Representante, el control político y la dirección estratégica de las operaciones de gestión de crisis contempladas en el artículo 43, se ejercerá:","o":["Por el Comité de Crisis.","Por el Parlamento Europeo.","Por el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","Por el Comité Político y de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por el Comité Político y de Seguridad</mark></span>El <span class=\"ref-norma\">art. 38 del TUE</span> dispone: <span class=\"ref-concepto\">\"En el marco del presente capítulo, el Comité Político y de Seguridad ejercerá, bajo la responsabilidad del Consejo y del Alto Representante, el control político y la dirección estratégica de las operaciones de gestión de crisis\"</span>. El artículo 38 del TUE atribuye al Comité Político y de Seguridad, bajo la responsabilidad del Consejo y del Alto Representante, el control político y la dirección estratégica de las operaciones de gestión de crisis contempladas en el artículo 43."},{"i":"3-189","p":"Tratado de la Unión Europea. Política exterior y de Seguridad Común. ¿Quién seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo?","o":["Un servicio europeo de acción exterior.","Un representante de exteriores.","Un representante especial.","Un Comité Político y de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un Comité Político y de Seguridad</mark></span>El <span class=\"ref-norma\">art. 38 del TUE</span> dispone: <span class=\"ref-concepto\">\"un Comité Político y de Seguridad seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo\"</span>. El artículo 38 del TUE dispone que un Comité Político y de Seguridad seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo."},{"i":"3-332","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. ¿Quién seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo?","o":["Un servicio europeo de acción exterior.","Un representante de exteriores.","Un representante especial.","Un Comité Político y de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un Comité Político y de Seguridad</mark></span>El <span class=\"ref-norma\">art. 38 del TUE</span> dispone: <span class=\"ref-concepto\">\"un Comité Político y de Seguridad seguirá la situación internacional en los ámbitos concernientes a la política exterior y de seguridad común y contribuirá a definir la política mediante la emisión de dictámenes dirigidos al Consejo\"</span>. El artículo 38 TUE atribuye esta función al Comité Político y de Seguridad."},{"i":"3-ia-3210","p":"Tratado de la Unión Europea. Comité Político y de Seguridad. En el marco del capítulo de la política exterior y de seguridad común, el Comité Político y de Seguridad ejercerá, bajo la responsabilidad del Consejo y del Alto Representante, el control político y la dirección estratégica de:","o":["las operaciones de ayuda humanitaria.","las misiones de observación electoral.","las misiones de la Agencia Europea de Defensa.","las operaciones de gestión de crisis."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las operaciones de gestión de crisis</mark></span>El <span class=\"ref-norma\">art. 38 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el control político y la dirección estratégica de las operaciones de gestión\"</span>. Controla las operaciones de gestión de crisis. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 258 a 261 TFUE — Recurso por incumplimiento · R25 ✱ R25","q":[{"i":"3-28","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia de la Unión Europea. Señale la incorrecta.","o":["El Tribunal de Justicia actuará en Salas o en Gran Sala, de conformidad con las normas establecidas al respecto en el Estatuto del Tribunal de Justicia de la Unión Europea.","Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años. Su mandato será renovable.","Si el Tribunal de Justicia de la Unión Europea declarare que un Estado miembro ha incumplido una de las obligaciones que le incumben en virtud de los Tratados, dicho Estado estará obligado a adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal1.","Los reglamentos adoptados conjuntamente por el Parlamento Europeo y el Consejo de Europa, o por el Consejo de Europa, en virtud de las disposiciones de los Tratados, podrán atribuir al Tribunal de Justicia de la Unión competencias jurisdiccionales para pronunciarse sobre las sanciones previstas en dichos reglamentos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los reglamentos adoptados conjuntamente por el Parlamento Europeo y el Consejo de Europa, o por el Consejo de Europa, en virtud de las disposiciones de los Tratados, podrán atribuir al Tribunal de Justicia de la Unión competencias jurisdiccionales para pronunciarse sobre las sanciones previstas en dichos reglamentos</mark></span>El <span class=\"ref-norma\">art. 261 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los reglamentos adoptados conjuntamente por el Parlamento Europeo y el Consejo, y por el Consejo, en virtud de las disposiciones de los Tratados, podrán atribuir al Tribunal de Justicia de la Unión Europea una competencia jurisdiccional plena respecto de las sanciones previstas en dichos reglamentos\"</span>. El artículo 261 del TFUE se refiere a reglamentos adoptados por el Parlamento Europeo y el Consejo (no 'el Consejo de Europa', que es una organización distinta a la UE), que podrán atribuir al Tribunal de Justicia de la Unión Europea una competencia jurisdiccional plena respecto de las sanciones previstas en dichos reglamentos, por lo que la redacción de la opción D es incorrecta."},{"i":"3-174","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. Disposiciones Institucionales. Instituciones. El Tribunal de Justicia de la Unión Europea. Antes de que un Estado miembro interponga ante el Tribunal de Justicia de la Unión Europea, contra otro Estado miembro, un recurso fundado en un supuesto incumplimiento de las obligaciones que le incumben en virtud de los Tratados, deberá someter el asunto a:","o":["La Comisión.","El Consejo.","El Consejo Europeo.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Comisión</mark></span>El <span class=\"ref-norma\">art. 259 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Antes de que un Estado miembro interponga, contra otro Estado miembro, un recurso fundado en un supuesto incumplimiento de las obligaciones que le incumben en virtud de los Tratados, deberá someter el asunto a la Comisión\"</span>. El artículo 259 del TFUE exige que, antes de que un Estado miembro interponga contra otro Estado miembro un recurso por incumplimiento de los Tratados, deberá someter el asunto a la Comisión."},{"i":"3-372","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Si la Comisión estimare que un Estado miembro ha incumplido una de las obligaciones que le incumben en virtud de los Tratados, emitirá:","o":["Una decisión vinculante, previa audiencia del Consejo y del Estado miembro afectado en el plazo que fije.","Un dictamen motivado, después de haber ofrecido a dicho Estado la posibilidad de presentar sus observaciones.","Un reglamento sancionador, previa consulta al Parlamento Europeo y una vez oído el Estado afectado.","Un informe motivado dirigido al Consejo Europeo, después de haber oído al Estado miembro afectado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un dictamen motivado, después de haber ofrecido a dicho Estado la posibilidad de presentar sus observaciones</mark></span>El <span class=\"ref-norma\">art. 258 del TFUE</span> dispone: <span class=\"ref-concepto\">\"emitirá un dictamen motivado al respecto, después de haber ofrecido a dicho Estado la posibilidad de presentar sus observaciones\"</span>. Dictamen motivado tras ofrecer al Estado presentar observaciones."},{"i":"3-373","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Si la Comisión estimare que el Estado miembro afectado no ha adoptado las medidas necesarias para la ejecución de la sentencia del Tribunal, podrá someter el asunto al Tribunal de Justicia. La Comisión indicará:","o":["El importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado miembro afectado.","El importe de la indemnización por daños que deba ser pagada por el Estado miembro afectado a la Comisión.","El plazo máximo de ejecución de la sentencia que deba ser respetado por el Estado miembro afectado.","La sanción económica que corresponda según el criterio del Consejo para el Estado miembro afectado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado miembro afectado</mark></span>El <span class=\"ref-norma\">art. 260 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La Comisión indicará el importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado miembro afectado\"</span>. La Comisión propone el importe; la impone el Tribunal."},{"i":"3-ia-3551","p":"Tratado de Funcionamiento de la Unión Europea. Recurso por incumplimiento. Si la Comisión estimare que un Estado miembro ha incumplido una de las obligaciones que le incumben en virtud de los Tratados, emitirá un dictamen motivado al respecto, después de haber ofrecido a dicho Estado:","o":["un plazo de tres meses para subsanar el incumplimiento.","la audiencia previa del Consejo.","la posibilidad de presentar sus observaciones.","la posibilidad de solicitar la intervención del Parlamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la posibilidad de presentar sus observaciones</mark></span>El <span class=\"ref-norma\">art. 258 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"emitirá un dictamen motivado al respecto, después de haber ofrecido a dicho Estado la posibilidad de presentar sus observaciones\"</span>. Antes del dictamen motivado se oyen las observaciones del Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3552","p":"Tratado de Funcionamiento de la Unión Europea. Recurso por incumplimiento. Si el Estado de que se trate no se atuviere al dictamen motivado en el plazo determinado por la Comisión, ésta:","o":["deberá recurrir al Tribunal de Justicia de la Unión Europea.","podrá recurrir al Tribunal de Justicia de la Unión Europea.","podrá imponer directamente una sanción pecuniaria.","deberá remitir el asunto al Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">podrá recurrir al Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 258 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"ésta podrá recurrir al Tribunal de Justicia de la Unión Europea\"</span>. Es una facultad: podrá recurrir al Tribunal de Justicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3601","p":"Tratado de Funcionamiento de la Unión Europea. Recurso entre Estados. Antes de que un Estado miembro interponga, contra otro Estado miembro, un recurso fundado en un supuesto incumplimiento de las obligaciones que le incumben en virtud de los Tratados, deberá someter el asunto:","o":["a la Comisión.","al Consejo.","al Parlamento Europeo.","al Tribunal General."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a la Comisión</mark></span>El <span class=\"ref-norma\">art. 259 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"deberá someter el asunto a la Comisión\"</span>. Debe someterlo previamente a la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3602","p":"Tratado de Funcionamiento de la Unión Europea. Recurso entre Estados. La Comisión emitirá un dictamen motivado una vez que los Estados interesados hayan tenido la posibilidad de formular sus observaciones por escrito y oralmente en procedimiento contradictorio; si no hubiere emitido el dictamen en el plazo de tres meses desde la fecha de la solicitud:","o":["el Estado deberá esperar a que la Comisión emita el dictamen para recurrir.","el asunto se remitirá al Consejo para que emita un dictamen.","el recurso quedará caducado y no podrá interponerse.","la falta de dictamen no será obstáculo para poder recurrir al Tribunal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la falta de dictamen no será obstáculo para poder recurrir al Tribunal</mark></span>El <span class=\"ref-norma\">art. 259 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Si la Comisión no hubiere emitido el dictamen en el plazo de tres meses desde la fecha de la solicitud, la falta de dictamen no será obstáculo para poder recurrir al Tribunal\"</span>. Pasados tres meses, el Estado puede recurrir sin dictamen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3603","p":"Tratado de Funcionamiento de la Unión Europea. Ejecución de sentencias por incumplimiento. Si la Comisión estimare que el Estado miembro afectado no ha adoptado las medidas necesarias para la ejecución de la sentencia del Tribunal, podrá someter el asunto al Tribunal de Justicia, después de haber ofrecido a dicho Estado la posibilidad de presentar sus observaciones, indicando:","o":["el plazo máximo para la ejecución de la sentencia y la cuantía de la indemnización a los afectados, conforme al procedimiento que se establezca reglamentariamente.","las medidas concretas de ejecución que deba adoptar el Estado y el calendario de cumplimiento.","el importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado y que considere adaptado a las circunstancias.","el importe de la sanción económica y la parte de los fondos de la Unión que deba retenerse."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado y que considere adaptado a las circunstancias</mark></span>El <span class=\"ref-norma\">art. 260.1 y 2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Comisión indicará el importe de la suma a tanto alzado o de la multa coercitiva que deba ser pagada por el Estado miembro afectado\"</span>. La Comisión propone suma a tanto alzado o multa coercitiva; el Tribunal puede imponerla. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3605","p":"Tratado de Funcionamiento de la Unión Europea. Ejecución de sentencias por incumplimiento. Cuando la Comisión presente un recurso por considerar que el Estado miembro ha incumplido la obligación de informar sobre las medidas de transposición de una directiva adoptada con arreglo a un procedimiento legislativo, podrá indicar el importe de la suma a tanto alzado o de la multa coercitiva; si el Tribunal comprueba el incumplimiento, podrá imponer el pago:","o":["dentro del límite del importe indicado por la Comisión, con efecto en la fecha fijada por el Tribunal en la sentencia.","por el importe que el Tribunal considere adecuado, con efecto desde la fecha de la sentencia.","dentro del límite del importe fijado por el Consejo, con efecto desde la notificación a las partes, en los términos que establezca la propia norma.","por el importe indicado por la Comisión, con efecto desde la fecha del dictamen motivado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">dentro del límite del importe indicado por la Comisión, con efecto en la fecha fijada por el Tribunal en la sentencia</mark></span>El <span class=\"ref-norma\">art. 260.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá imponer al Estado miembro afectado el pago de una suma a tanto alzado o de una multa coercitiva dentro del límite del importe indicado por la Comisión\"</span>. Sanción anticipada por falta de comunicación de la transposición, con límite en el importe indicado por la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3606","p":"Tratado de Funcionamiento de la Unión Europea. Competencia jurisdiccional plena. Los reglamentos adoptados conjuntamente por el Parlamento Europeo y el Consejo, y por el Consejo, podrán atribuir al Tribunal de Justicia de la Unión Europea:","o":["una competencia exclusiva para conocer de los recursos contra los actos de ejecución de dichos reglamentos.","una competencia de control de legalidad de las decisiones de los Estados miembros que apliquen dichos reglamentos.","una competencia consultiva sobre la interpretación de dichos reglamentos.","una competencia jurisdiccional plena respecto de las sanciones previstas en dichos reglamentos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una competencia jurisdiccional plena respecto de las sanciones previstas en dichos reglamentos</mark></span>El <span class=\"ref-norma\">art. 261 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrán atribuir al Tribunal de Justicia de la Unión Europea una competencia jurisdiccional plena respecto de las sanciones previstas en dichos reglamentos\"</span>. Competencia jurisdiccional plena sobre las sanciones de los reglamentos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3617","p":"Tratado de Funcionamiento de la Unión Europea. Ejecución de sentencias. La institución, órgano u organismo del que emane el acto anulado, o cuya abstención haya sido declarada contraria a los Tratados, estarán obligados a:","o":["adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia.","indemnizar a los afectados por los daños causados por el acto anulado.","adoptar un nuevo acto en el plazo de seis meses desde la sentencia.","comunicar la sentencia a los Estados miembros y a las demás instituciones, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 266 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"estarán obligados a adoptar las medidas necesarias para la ejecución de la sentencia del Tribunal de Justicia de la Unión Europea\"</span>. Deben adoptar las medidas de ejecución de la sentencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3626","p":"Tratado de Funcionamiento de la Unión Europea. Banco Europeo de Inversiones y SEBC. El Tribunal de Justicia será competente para conocer de los litigios relativos al cumplimiento de las obligaciones de los Estados miembros que se derivan de los Estatutos del Banco Europeo de Inversiones; el Consejo de Administración del Banco tendrá, a este respecto:","o":["las competencias que el artículo sobre el recurso de anulación atribuye al Consejo.","las competencias que el artículo sobre cuestiones prejudiciales atribuye al Parlamento, salvo que se disponga otra cosa en la normativa aplicable.","las competencias de control de legalidad que se atribuyen al Tribunal de Cuentas.","las competencias que el artículo sobre el recurso por incumplimiento atribuye a la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las competencias que el artículo sobre el recurso por incumplimiento atribuye a la Comisión</mark></span>El <span class=\"ref-norma\">art. 271 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo de Administración del Banco tendrá, a este respecto, las competencias que el artículo 258 atribuye a la Comisión\"</span>. El Consejo de Administración del BEI actúa como la Comisión en el recurso por incumplimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Finalidad de la Unión Europea EX ✱","q":[{"i":"3-29","p":"Tratado de la Unión Europea. Fines y Objetivos de la Unión. ¿Cuál de los siguientes no es un objetivo de la Unión?","o":["Ofrecer a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores.","Fomentar la cohesión económica, social y territorial y la solidaridad entre los Estados miembros.","Combatir la exclusión social y la discriminación y fomentar la justicia y la protección sociales.","La reducción de la jornada laboral para la cohesión social."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La reducción de la jornada laboral para la cohesión social</mark></span>El <span class=\"ref-norma\">art. 3.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión COMBATIRÁ la exclusión social y la discriminación y fomentará la justicia y la protección sociales, la igualdad entre mujeres y hombres, la solidaridad entre las generaciones y la protección de los derechos del niño\"</span>. El artículo 3 del TUE recoge como finalidades de la Unión ofrecer un espacio de libertad, seguridad y justicia, fomentar la cohesión económica, social y territorial, y combatir la exclusión social, pero no menciona la reducción de la jornada laboral como objetivo."},{"i":"3-50","p":"Tratado de la Unión Europea. La Unión ofrecerá a sus ciudadanos un espacio de libertad, seguridad y justicia:","o":["Sin fronteras interiores, en el que se garantiza la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia.","Sin fronteras exteriores, en el que está garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia.","Con fronteras interiores, en el que está garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia.","Con fronteras exteriores, en el que está garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de la seguridad interior, asilo, inmigración y de prevención y lucha contra la delincuencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Sin fronteras interiores, en el que se garantiza la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia</mark></span>El <span class=\"ref-norma\">art. 3.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión OFRECERÁ a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores, en el que esté garantizada la libre circulación de personas conjuntamente con medidas\"</span>. El artículo 3.2 del TUE establece que la Unión ofrecerá a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores, en el que esté garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia."},{"i":"3-96","p":"Tratado de la Unión Europea. Disposiciones comunes. Finalidad de la Unión Europea. Señale la correcta:","o":["Tiene como finalidad promover la paz, sus valores y el bienestar de sus pueblos.","Ofrecerá a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores.","Fomentará la cohesión económica, social y territorial y la solidaridad entre los estados miembros.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 3.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión tiene como FINALIDAD promover la paz, sus valores y el bienestar de sus pueblos\"</span>. El artículo 3 del TUE recoge entre las finalidades de la Unión promover la paz, sus valores y el bienestar de sus pueblos, ofrecer un espacio de libertad, seguridad y justicia sin fronteras interiores, y fomentar la cohesión económica, social y territorial y la solidaridad entre los Estados miembros."},{"i":"3-144","p":"Tratado de la Unión Europea. La Unión tiene como finalidad:","o":["La libre circulación de personas conjuntamente con medidas adecuadas en materia de control de las fronteras exteriores.","Promover la paz, sus valores y el bienestar de sus pueblos.","La lucha contra la delincuencia.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Promover la paz, sus valores y el bienestar de sus pueblos</mark></span>El <span class=\"ref-norma\">art. 3.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión tiene como FINALIDAD promover la paz, sus valores y el bienestar de sus pueblos\"</span>. El artículo 3.1 del TUE establece que la Unión tiene como finalidad promover la paz, sus valores y el bienestar de sus pueblos."},{"i":"3-238","p":"Derecho de la Unión Europea. Tratado de la UE. Disposiciones comunes. La Unión _____ la cohesión económica, social y territorial y la solidaridad entre los Estados miembros","o":["Ofrecerá.","Combatirá.","Fomentará.","Establecerá."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Fomentará</mark></span>El <span class=\"ref-norma\">art. 3.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión FOMENTARÁ la cohesión económica, social y territorial y la solidaridad entre los Estados miembros\"</span>. El artículo 3.3 del TUE establece que la Unión fomentará la cohesión económica, social y territorial y la solidaridad entre los Estados miembros."},{"i":"3-242","p":"Tratado de la Unión Europea. ¿Cuál es la finalidad de la Unión?","o":["Promover la paz, sus valores y el bienestar de sus pueblos.","Combatir la exclusión social y la discriminación.","Ofrecer a sus ciudadanos un espacio de libertad, seguridad y justicia.","Fomentar la cohesión económica, social y territorial y la solidaridad entre los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Promover la paz, sus valores y el bienestar de sus pueblos</mark></span>El <span class=\"ref-norma\">art. 3.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión tiene como FINALIDAD promover la paz, sus valores y el bienestar de sus pueblos\"</span>. (This is the primary and most general objective listed in Article 3 TEU.)"},{"i":"3-ia-3009","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión tiene como FINALIDAD:","o":["promover la paz, sus valores y el bienestar de sus pueblos.","garantizar la paz, la seguridad y el bienestar de sus ciudadanos.","promover la integración económica y la cohesión entre sus pueblos.","proteger sus valores, sus intereses y el bienestar de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">promover la paz, sus valores y el bienestar de sus pueblos</mark></span>El <span class=\"ref-norma\">art. 3.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión tiene como FINALIDAD promover la paz, sus valores y el bienestar de sus pueblos\"</span>. La finalidad es promover la paz, sus valores y el bienestar de sus pueblos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3010","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión OFRECERÁ a sus ciudadanos un espacio de libertad, seguridad y justicia sin fronteras interiores, en el que esté garantizada la libre circulación de personas conjuntamente con medidas adecuadas en materia de:","o":["control de las fronteras exteriores, cooperación policial, asilo y de lucha contra el terrorismo.","control de las fronteras interiores, asilo, inmigración y de prevención del crimen organizado.","vigilancia de las fronteras exteriores, visados, inmigración y de lucha contra la trata de seres humanos.","control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">control de las fronteras exteriores, asilo, inmigración y de prevención y lucha contra la delincuencia</mark></span>El <span class=\"ref-norma\">art. 3.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"adecuadas en materia de control de las fronteras exteriores, asilo, inmigración y de prevención y lucha\"</span>. Las medidas son control de fronteras exteriores, asilo, inmigración y prevención y lucha contra la delincuencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3011","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión ESTABLECERÁ un mercado interior y obrará en pro del desarrollo sostenible de Europa basado en un crecimiento económico equilibrado y en la estabilidad de los precios, en una economía social de mercado altamente competitiva, tendente a:","o":["la plena integración y a la cohesión social.","el pleno empleo y a la competitividad exterior.","el pleno empleo y al progreso social.","el progreso tecnológico y a la estabilidad monetaria."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el pleno empleo y al progreso social</mark></span>El <span class=\"ref-norma\">art. 3.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en una economía social de mercado altamente competitiva, tendente al pleno empleo y al progreso social\"</span>. La economía social de mercado tiende al pleno empleo y al progreso social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3013","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión FOMENTARÁ la cohesión económica, social y territorial y la solidaridad entre los Estados miembros, y RESPETARÁ la riqueza de su diversidad cultural y lingüística y velará por:","o":["la conservación y el desarrollo del patrimonio cultural europeo.","la promoción y la difusión del patrimonio cultural y artístico europeo.","la protección y la salvaguardia de las lenguas minoritarias de los Estados.","la conservación y la valorización del patrimonio natural y cultural europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la conservación y el desarrollo del patrimonio cultural europeo</mark></span>El <span class=\"ref-norma\">art. 3.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"velará por la conservación y el desarrollo del patrimonio cultural europeo\"</span>. Se vela por la conservación y el desarrollo del patrimonio cultural europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3014","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión ESTABLECERÁ una unión económica y monetaria cuya moneda es:","o":["el ecu.","una moneda común que fijará el Consejo.","el euro, para todos los Estados miembros.","el euro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el euro</mark></span>El <span class=\"ref-norma\">art. 3.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión ESTABLECERÁ una unión económica y monetaria cuya moneda es el euro\"</span>. La moneda de la unión económica y monetaria es el euro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 6 — Carta de Derechos Fundamentales y CEDH EXOF","q":[{"i":"3-31","p":"Tratado de la Unión Europea. Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión:","o":["Como principios generales.","Como principios rectores.","Como principios fundamentales.","Como principios de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Como principios generales</mark></span>El <span class=\"ref-norma\">art. 6.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión como principios generales\"</span>. Según el art. 6.3 TUE, dichos derechos fundamentales \"formarán parte del Derecho de la Unión como principios generales\"."},{"i":"3-111","p":"Tratado de la Unión Europea. Reconocimiento jurídico de la Carta de los Derechos Fundamentales de la Unión Europea y mandato de adhesión al Convenio Europeo para la Protección de los Derechos Humanos. Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión como:","o":["Principios consuetudinarios.","Principios generales.","Principios del Derecho de la Unión.","Principios básicos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Principios generales</mark></span>El <span class=\"ref-norma\">art. 6.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión como principios generales\"</span>. El artículo 6.3 del TUE establece que los derechos fundamentales garantizados por el Convenio Europeo para la Protección de los Derechos Humanos y los derivados de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión como principios generales."},{"i":"3-317","p":"Tratado de la Unión Europea. Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión:","o":["Como principios generales.","Como principios rectores.","Como principios fundamentales.","Como principios de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Como principios generales</mark></span>El <span class=\"ref-norma\">art. 6.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los derechos fundamentales que garantiza el Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión como principios generales\"</span>. El artículo 6.3 TUE dispone que dichos derechos formarán parte del Derecho de la Unión como principios generales."},{"i":"3-382","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Sin perjuicio de las competencias que los Tratados atribuyen al Tribunal de Justicia, los litigios en los que la Unión sea parte:","o":["Serán de la competencia exclusiva del Tribunal de Justicia de la Unión Europea en todo caso.","Serán de la competencia del Tribunal General en primera instancia y del Tribunal de Justicia en casación.","Se resolverán por arbitraje ante un órgano designado por el Consejo y la Comisión.","No podrán ser, por tal motivo, sustraídos a la competencia de las jurisdicciones nacionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No podrán ser, por tal motivo, sustraídos a la competencia de las jurisdicciones nacionales</mark></span>El <span class=\"ref-norma\">art. 274 del TFUE</span> dispone: <span class=\"ref-concepto\">\"los litigios en los que la Unión sea parte no podrán ser, por tal motivo, sustraídos a la competencia de las jurisdicciones nacionales\"</span>. Los litigios con la Unión como parte siguen siendo de las jurisdicciones nacionales salvo competencia del Tribunal."},{"i":"3-ia-3001","p":"Tratado de la Unión Europea. Instrumento de creación. El Tratado de la Unión Europea fue firmado en Maastricht el:","o":["7 de febrero de 1992.","25 de marzo de 1957.","13 de diciembre de 2007.","17 de febrero de 1986."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">7 de febrero de 1992</mark></span>El <span class=\"ref-norma\">ficha del TUE de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Tratado de la Unión Europea, firmado en Maastricht, el 7 de febrero de 1992\"</span>. Se firmó el 7 de febrero de 1992 en Maastricht; la última reforma es el Tratado de Lisboa de 13-12-2007. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3003","p":"Tratado de la Unión Europea. Órgano emisor y última reforma. El órgano emisor del Tratado de la Unión Europea es el Parlamento Europeo y el Consejo, y su última reforma es:","o":["el Tratado de Niza de 26-02-2001.","el Tratado de Ámsterdam de 02-10-1997.","el Tratado de Lisboa de 13-12-2007.","el Acta Única Europea de 17-02-1986."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Tratado de Lisboa de 13-12-2007</mark></span>El <span class=\"ref-norma\">ficha del TUE de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Última reforma: Tratado de Lisboa de 13-12-2007\"</span>. La última reforma es el Tratado de Lisboa de 13 de diciembre de 2007. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3016","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. La Unión perseguirá sus objetivos por los medios apropiados, de acuerdo con:","o":["los poderes que le reconocen los Estados miembros.","las competencias que se le atribuyen en los Tratados.","los principios de subsidiariedad y proporcionalidad, sin perjuicio de lo dispuesto en otras disposiciones.","las decisiones adoptadas por el Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las competencias que se le atribuyen en los Tratados</mark></span>El <span class=\"ref-norma\">art. 3.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión perseguirá sus objetivos por los medios apropiados, de acuerdo con las competencias que se le atribuyen en los Tratados\"</span>. Los medios han de ser apropiados y acordes con las competencias atribuidas en los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3026","p":"Tratado de la Unión Europea. Reconocimiento jurídico de la Carta de los Derechos Fundamentales y mandato de adhesión al Convenio Europeo. La Unión reconoce los derechos, libertades y principios enunciados en la Carta de los Derechos Fundamentales de la Unión Europea de 7 de diciembre de 2000, tal como fue adaptada el 12 de diciembre de 2007 en Estrasburgo, la cual tendrá:","o":["un valor jurídico complementario al de los Tratados.","el mismo valor jurídico que el Derecho derivado.","carácter vinculante únicamente para las instituciones.","el mismo valor jurídico que los Tratados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el mismo valor jurídico que los Tratados</mark></span>El <span class=\"ref-norma\">art. 6.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la cual tendrá el mismo valor jurídico que los Tratados\"</span>. La Carta tiene el mismo valor jurídico que los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3028","p":"Tratado de la Unión Europea. Reconocimiento jurídico de la Carta de los Derechos Fundamentales y mandato de adhesión al Convenio Europeo. La Unión se adherirá al Convenio Europeo para la Protección de los Derechos Humanos y de las Libertades Fundamentales; esta adhesión:","o":["ampliará las competencias de la Unión en materia de derechos fundamentales.","no modificará las competencias de la Unión que se definen en los Tratados.","someterá a la Unión a la jurisdicción exclusiva del Tribunal Europeo de Derechos Humanos.","no modificará las competencias de los Estados miembros que se definen en los Tratados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no modificará las competencias de la Unión que se definen en los Tratados</mark></span>El <span class=\"ref-norma\">art. 6.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Esta adhesión no modificará las competencias de la Unión que se definen\"</span>. La adhesión no altera las competencias de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3029","p":"Tratado de la Unión Europea. Reconocimiento jurídico de la Carta de los Derechos Fundamentales y mandato de adhesión al Convenio Europeo. Los derechos fundamentales que garantiza el Convenio Europeo y los que son fruto de las tradiciones constitucionales comunes a los Estados miembros formarán parte del Derecho de la Unión:","o":["como principios generales.","como derechos fundamentales reconocidos.","como normas de Derecho derivado.","como obligaciones de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">como principios generales</mark></span>El <span class=\"ref-norma\">art. 6.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"formarán parte del Derecho de la Unión como principios generales\"</span>. Forman parte del Derecho de la Unión como principios generales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3138","p":"Tratado de la Unión Europea. Principios de la acción exterior. La Unión velará por mantener la coherencia entre los distintos ámbitos de su acción exterior y entre éstos y sus demás políticas; el Consejo y la Comisión, asistidos por el Alto Representante, garantizarán dicha coherencia y:","o":["rendirán cuentas al Consejo Europeo.","informarán al Parlamento Europeo.","se coordinarán con los Estados miembros.","cooperarán a tal efecto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">cooperarán a tal efecto</mark></span>El <span class=\"ref-norma\">art. 21.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"garantizarán dicha coherencia y cooperarán a tal efecto\"</span>. Garantizan la coherencia y cooperan a tal efecto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 17 — La Comisión · R8 EXOF ✱ R8","q":[{"i":"3-32","p":"Tratado de la Unión Europea. Derecho de la Unión Europea. ¿Quién propone el candidato a Presidente de la Comisión?","o":["La Comisión.","El Parlamento Europeo.","El Consejo.","El Consejo Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 17.7 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo Europeo propondrá al Parlamento Europeo, por mayoría cualificada, un candidato al cargo de Presidente de la Comisión\"</span>. El artículo 17.7 del TUE dispone que el Consejo Europeo, teniendo en cuenta el resultado de las elecciones al Parlamento Europeo y tras las consultas apropiadas, propondrá al Parlamento Europeo, por mayoría cualificada, un candidato al cargo de Presidente de la Comisión."},{"i":"3-68","p":"Tratado de la Unión Europea. La Comisión. Señale la incorrecta.","o":["Tendrá una responsabilidad colegiada ante el Parlamento Europeo.","El Consejo, de común acuerdo con el Presidente electo, adoptará la lista de las demás personalidades que se proponga nombrar miembros de la Comisión.","El Consejo Europeo elegirá al candidato al cargo de Presidente de la Comisión.","El Parlamento Europeo podrá votar una moción de censura contra la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo Europeo elegirá al candidato al cargo de Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 17.7 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo Europeo propondrá al Parlamento Europeo, por mayoría cualificada, un candidato al cargo de Presidente de la Comisión. El Parlamento Europeo elegirá al candidato por mayoría de los miembros que lo componen\"</span>. La opción correcta es la C, por ser la incorrecta. Según el artículo 17.7 del TUE, es el Parlamento Europeo, y no el Consejo Europeo, quien elige al candidato propuesto al cargo de Presidente de la Comisión, por mayoría de los miembros que lo componen."},{"i":"3-70","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. La Comisión Europea. Señale la correcta.","o":["Velará por que se apliquen los Tratados.","Asegurará la representación exterior de la Unión en todos los casos.","El mandato de la Comisión será de cuatro años.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Velará por que se apliquen los Tratados</mark></span>El <span class=\"ref-norma\">art. 17.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"Velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos\"</span>. El artículo 17.1 del TUE establece que la Comisión velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos, mientras que la representación exterior corresponde a la Comisión salvo en política exterior y de seguridad común, y el mandato de la Comisión es de cinco años, no de cuatro."},{"i":"3-82","p":"Tratado de la Unión Europea. Tratado de Funcionamiento de la Unión Europea. Los miembros de la Comisión serán elegidos:","o":["Mediante un sistema de rotación establecido por unanimidad por el Consejo Europeo.","Por un periodo de cinco años por unanimidad por el Consejo Europeo.","Mediante elección directa por el Parlamento Europeo.","Por un periodo de cinco años por mayoría por el Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mediante un sistema de rotación establecido por unanimidad por el Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 244 del TFUE</span> dispone: <span class=\"ref-concepto\">\"De conformidad con el apartado 5 del artículo 17 del Tratado de la Unión Europea, los miembros de la Comisión serán elegidos mediante un sistema de rotación establecido por unanimidad por el Consejo Europeo, basado en los principios siguientes\"</span>. El artículo 17.5 del TUE y el artículo 244 del TFUE establecen que los miembros de la Comisión serán seleccionados mediante un sistema de rotación estrictamente igual entre los Estados miembros, establecido por unanimidad por el Consejo Europeo."},{"i":"3-172","p":"Tratado de la Unión Europea. La Comisión realizará, entre otras, las siguientes acciones:","o":["Promoverá el interés general de la Unión y tomará las iniciativas adecuadas con este fin.","Velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de estos.","Supervisará la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia de la Unión Europea.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 17.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La COMISIÓN promoverá el interés general de la Unión y tomará las iniciativas adecuadas con este fin. Velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos. Supervisará la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia de la Unión Europea\"</span>. El artículo 17.1 del TUE atribuye a la Comisión promover el interés general de la Unión, velar por que se apliquen los Tratados y las medidas adoptadas por las instituciones, y supervisar la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia."},{"i":"3-175","p":"Tratado de la Unión Europea. La Comisión. Señale la INCORRECTA:","o":["Los miembros de la Comisión serán elegidos en razón de su competencia general y de su compromiso europeo de entre personalidades que ofrezcan plenas garantías de independencia.","A partir del 1 de noviembre de 2014, la Comisión estará compuesta por un número de miembros correspondiente a los dos tercios del número de Estados miembros, a menos que el Consejo Europeo decida por unanimidad modificar dicho número.","Los miembros de la Comisión serán seleccionados de entre los nacionales de los Estados miembros mediante un sistema de rotación con base proporcional.","Ejercerán sus responsabilidades con plena independencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los miembros de la Comisión serán seleccionados de entre los nacionales de los Estados miembros mediante un sistema de rotación con base proporcional</mark></span>La C es incorrecta: la rotación es «estrictamente igual», no «con base proporcional». A y D reproducen el art. 17.3 y B el art. 17.5. Según el <span class=\"ref-norma\">art. 17.5 del TUE</span>: <span class=\"ref-concepto\">\"Los miembros de la Comisión serán seleccionados de entre los nacionales de los Estados miembros mediante un sistema de rotación estrictamente igual entre los Estados miembros que permita tener en cuenta la diversidad demográfica y geográfica del conjunto de dichos Estados.\"</span> (verificado con el texto del temario)."},{"i":"3-178","p":"Tratado de la Unión Europea. El mandato de la Comisión será de:","o":["Dos años y medio.","Tres años.","Cuatro años.","Cinco años."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 17.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El mandato de la Comisión será de cinco años\"</span>. El artículo 17.3 del TUE establece que el mandato de la Comisión será de cinco años."},{"i":"3-305","p":"Tratado de la Unión Europea. Los actos legislativos de la Unión, excepto cuando los Tratados dispongan otra cosa, sólo podrán adoptarse a propuesta de:","o":["El Parlamento Europeo.","La Comisión.","El Consejo.","El Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Comisión</mark></span>El <span class=\"ref-norma\">art. 17.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los Tratados dispongan otra cosa. Los demás actos se adoptarán a propuesta de la Comisión cuando así lo establezcan los Tratados\"</span>. El artículo 17.2 TUE establece que los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, salvo que los Tratados dispongan otra cosa."},{"i":"3-308","p":"Tratado de la Unión Europea. La Comisión. Señale la incorrecta.","o":["Tendrá una responsabilidad colegiada ante el Parlamento Europeo.","El Consejo, de común acuerdo con el Presidente electo, adoptará la lista de las demás personalidades que se proponga nombrar miembros de la Comisión.","El Consejo Europeo elegirá al candidato al cargo de Presidente de la Comisión.","El Parlamento Europeo podrá votar una moción de censura contra la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo Europeo elegirá al candidato al cargo de Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 17.7 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo Europeo propondrá al Parlamento Europeo, por mayoría cualificada, un candidato al cargo de Presidente de la Comisión. El Parlamento Europeo elegirá al candidato por mayoría de los miembros que lo componen\"</span>. Según el artículo 17.7 TUE, el Consejo Europeo propone al candidato a Presidente de la Comisión por mayoría cualificada; es el Parlamento Europeo quien lo elige."},{"i":"3-309","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. La Comisión Europea. Señale la correcta.","o":["Velará por que se apliquen los Tratados.","Asegurará la representación exterior de la Unión en todos los casos.","El mandato de la Comisión será de cuatro años.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Velará por que se apliquen los Tratados</mark></span>El <span class=\"ref-norma\">art. 17.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"Velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos\"</span>. El artículo 17.1 TUE lo establece así; la Comisión no asegura la representación exterior 'en todos los casos' (excepción de la PESC) y el mandato de la Comisión es de cinco años, no cuatro."},{"i":"3-318","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. El mandato de la Comisión será de:","o":["Cuatro años.","Tres años.","Cinco años.","Ocho años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 17.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El mandato de la Comisión será de cinco años\"</span>. El artículo 17.3 TUE fija el mandato de la Comisión en cinco años."},{"i":"3-ia-3111","p":"Tratado de la Unión Europea. La Comisión. La Comisión promoverá el interés general de la Unión y tomará las iniciativas adecuadas con este fin; velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones, y supervisará la aplicación del Derecho de la Unión:","o":["bajo el control del Parlamento Europeo y del Consejo, conforme al procedimiento que se establezca reglamentariamente.","bajo el control del Tribunal de Cuentas de la Unión.","bajo el control del Tribunal de Justicia de la Unión Europea.","bajo la supervisión del Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">bajo el control del Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 17.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Supervisará la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia de la\"</span>. Supervisa la aplicación del Derecho de la Unión bajo el control del Tribunal de Justicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3112","p":"Tratado de la Unión Europea. La Comisión. La Comisión, con excepción de la política exterior y de seguridad común y de los demás casos previstos por los Tratados:","o":["ejercerá el derecho de iniciativa exclusivo en materia exterior.","asumirá la representación exterior de la Unión.","compartirá la representación exterior con el Consejo.","ejecutará la política exterior junto con el Alto Representante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">asumirá la representación exterior de la Unión</mark></span>El <span class=\"ref-norma\">art. 17.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"asumirá la representación exterior de la Unión\"</span>. Representa a la Unión hacia el exterior salvo en PESC. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3114","p":"Tratado de la Unión Europea. La Comisión. El mandato de la Comisión será de cinco años; sus miembros serán elegidos en razón de su competencia general y de su compromiso europeo, de entre personalidades que ofrezcan:","o":["plenas garantías de imparcialidad.","plenas garantías de experiencia.","plena disponibilidad para el cargo.","plenas garantías de independencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">plenas garantías de independencia</mark></span>El <span class=\"ref-norma\">art. 17.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de entre personalidades que ofrezcan plenas garantías de independencia\"</span>. Plenas garantías de independencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3116","p":"Tratado de la Unión Europea. La Comisión. A partir del 1 de noviembre de 2014, la Comisión estará compuesta por un número de miembros correspondiente a los dos tercios del número de Estados miembros, a menos que el Consejo Europeo decida:","o":["por mayoría cualificada modificar dicho número.","por unanimidad modificar dicho número.","por unanimidad mantener un nacional por Estado.","por mayoría simple modificar dicho número."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad modificar dicho número</mark></span>El <span class=\"ref-norma\">art. 17.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a menos que el Consejo Europeo decida por unanimidad modificar dicho número\"</span>. El Consejo Europeo puede modificar el número, por unanimidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3117","p":"Tratado de la Unión Europea. La Comisión. Los miembros de la Comisión serán seleccionados de entre los nacionales de los Estados miembros mediante un sistema de rotación estrictamente igual que permita tener en cuenta la diversidad demográfica y geográfica de los Estados; este sistema será establecido:","o":["por unanimidad por el Consejo Europeo.","por mayoría cualificada por el Consejo.","por unanimidad por el Consejo.","por mayoría cualificada por el Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por unanimidad por el Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 17.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Este sistema será establecido por unanimidad por el Consejo Europeo de conformidad con el artículo\"</span>. Lo establece el Consejo Europeo por unanimidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3118","p":"Tratado de la Unión Europea. La Comisión. El Presidente de la Comisión definirá las orientaciones con arreglo a las cuales la Comisión desempeñará sus funciones, determinará su organización interna y nombrará:","o":["Vicepresidentes, incluido el Alto Representante, de entre los miembros de la Comisión, salvo que se disponga otra cosa en la normativa aplicable.","a los miembros de la Comisión, de común acuerdo con el Consejo.","Comisarios delegados, de entre los miembros de la Comisión y los Estados.","Vicepresidentes, distintos del Alto Representante, de entre los miembros de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Vicepresidentes, distintos del Alto Representante, de entre los miembros de la Comisión</mark></span>El <span class=\"ref-norma\">art. 17.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"nombrará Vicepresidentes, distintos del Alto Representante de la Unión para Asuntos Exterio\"</span>. Nombra Vicepresidentes distintos del Alto Representante, que lo es por la propia Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3119","p":"Tratado de la Unión Europea. La Comisión. Un miembro de la Comisión presentará su dimisión si se lo pide:","o":["el Parlamento Europeo.","el Consejo Europeo.","el Presidente.","el Consejo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Presidente</mark></span>El <span class=\"ref-norma\">art. 17.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Un miembro de la Comisión presentará su dimisión si se lo pide el Presidente\"</span>. El Presidente puede pedir la dimisión de un miembro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3120","p":"Tratado de la Unión Europea. La Comisión. Teniendo en cuenta el resultado de las elecciones al Parlamento Europeo y tras mantener las consultas apropiadas, el Consejo Europeo propondrá al Parlamento Europeo, por mayoría cualificada, un candidato al cargo de Presidente de la Comisión; el Parlamento Europeo elegirá al candidato:","o":["por mayoría de los votos emitidos.","por mayoría de los miembros que lo componen.","por mayoría de dos tercios de sus miembros, sin perjuicio de lo dispuesto en otras disposiciones.","por mayoría absoluta de los votos emitidos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por mayoría de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 17.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo elegirá al candidato por mayoría\"</span>. El Parlamento elige por mayoría de los miembros que lo componen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3121","p":"Tratado de la Unión Europea. La Comisión. Si el candidato a Presidente de la Comisión no obtiene la mayoría necesaria, el Consejo Europeo propondrá:","o":["en el plazo de un mes, por mayoría cualificada, un nuevo candidato.","en el plazo de dos meses, por unanimidad, un nuevo candidato.","en el plazo de un mes, por mayoría simple, un nuevo candidato.","en el plazo de quince días, por mayoría cualificada, un nuevo candidato."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en el plazo de un mes, por mayoría cualificada, un nuevo candidato</mark></span>El <span class=\"ref-norma\">art. 17.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Consejo Euro-peo propondrá en el plazo de un mes, por mayoría cualificada, un nuevo candidato\"</span>. Un mes y mayoría cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3123","p":"Tratado de la Unión Europea. La Comisión. Sobre la base de la aprobación colegiada del Parlamento Europeo al Presidente, al Alto Representante y a los demás miembros, la Comisión será nombrada:","o":["por el Consejo, por unanimidad.","por el Parlamento Europeo, por mayoría absoluta, conforme al procedimiento que se establezca reglamentariamente.","por el Consejo Europeo, por mayoría cualificada.","por el Consejo Europeo, por unanimidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el Consejo Europeo, por mayoría cualificada</mark></span>El <span class=\"ref-norma\">art. 17.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la Comisión será nombrada por el Consejo Europeo, por mayoría cualificada\"</span>. La nombra el Consejo Europeo por mayoría cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3124","p":"Tratado de la Unión Europea. La Comisión. La Comisión tendrá una responsabilidad colegiada ante el Parlamento Europeo, que podrá votar una moción de censura; si se aprueba dicha moción, los miembros de la Comisión deberán dimitir colectivamente de sus cargos y el Alto Representante:","o":["deberá dimitir de todos sus cargos en la Unión.","deberá dimitir del cargo que ejerce en la Comisión.","continuará en su cargo hasta nueva designación.","quedará sujeto a la decisión del Consejo Europeo, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">deberá dimitir del cargo que ejerce en la Comisión</mark></span>El <span class=\"ref-norma\">art. 17.8 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad deberá dimitir del cargo que ejerce en la Comisión\"</span>. El Alto Representante dimite solo del cargo que ejerce en la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3526","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Con sujeción a la igualdad entre Estados en la determinación del orden de turno, cada una de las sucesivas Comisiones se constituirá de forma que refleje de manera satisfactoria:","o":["la diversidad política y cultural del conjunto de los Estados miembros.","el peso económico y demográfico del conjunto de los Estados miembros.","la representación de los Estados miembros fundadores y de los nuevos Estados.","la diversidad demográfica y geográfica del conjunto de los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la diversidad demográfica y geográfica del conjunto de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 244 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"cada una de las sucesivas Comisiones se constituirá de forma que refleje de manera satisfactoria la diversidad demográfica y geográfica del conjunto de los Estados miembros\"</span>. Diversidad demográfica y geográfica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 269 a 281 TFUE — Otras competencias del TJUE · R27 EXOF EX ✱ R27","q":[{"i":"3-40","p":"Tratado de Funcionamiento de la Unión Europea. ¿Qué institución será competente para pronunciarse sobre cualquier litigio entre la Unión y sus agentes dentro de los límites y en las condiciones que establece el Estatuto de los funcionarios de la Unión?","o":["El Tribunal de Justicia de la Unión Europea.","El Consejo de Europa.","El Banco Central Europeo.","El Tribunal de Cuentas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 270 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia de la Unión Europea será competente para pronunciarse sobre cualquier litigio entre la Unión y sus agentes dentro de los límites y en las condiciones que establezca el Estatuto de los funcionarios de la Unión y el régimen aplicable a los otros agentes de la Unión\"</span>. El artículo 270 del TFUE atribuye al Tribunal de Justicia de la Unión Europea la competencia para pronunciarse sobre cualquier litigio entre la Unión y sus agentes, dentro de los límites y condiciones del Estatuto de los funcionarios de la Unión."},{"i":"3-225","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién será competente para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, si dicha controversia le es sometida en virtud de un compromiso?","o":["El Banco Central Europeo.","El Tribunal de Justicia.","El Parlamento Europeo.","Un Grupo de Estados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 273 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia será competente para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, si dicha controversia le es sometida en virtud de un compromiso\"</span>. El artículo 273 del TFUE atribuye al Tribunal de Justicia la competencia para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, cuando le sea sometida en virtud de un compromiso."},{"i":"3-289","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea. Señale la INCORRECTA:","o":["Las sentencias del Tribunal de Justicia de la Unión Europea tendrán fuerza ejecutiva.","El Estatuto del Tribunal de Justicia de la Unión Europea se fijará en un protocolo independiente.","Los recursos interpuestos ante el Tribunal de Justicia de la Unión Europea no tendrán efecto suspensivo en ningún caso.","El Tribunal de Justicia de la Unión Europea podrá ordenar las medidas provisionales necesarias en los asuntos de que esté conociendo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los recursos interpuestos ante el Tribunal de Justicia de la Unión Europea no tendrán efecto suspensivo en ningún caso</mark></span>El <span class=\"ref-norma\">art. 278 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los recursos interpuestos ante el Tribunal de Justicia de la Unión Europea no tendrán efecto suspensivo. Sin embargo, el Tribunal podrá, si estima que las circunstancias así lo exigen, ordenar la suspensión de la ejecución del acto impugnado\"</span>. (Los recursos no tendrán efecto suspensivo, pero el Tribunal podrá ordenar la suspensión)."},{"i":"3-379","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia será competente para pronunciarse sobre la legalidad de un acto adoptado por el Consejo Europeo o por el Consejo en el procedimiento de constatación de violación de valores de la Unión:","o":["A petición de cualquier Estado miembro de la Unión y por cualquier motivo, incluidos los vicios de fondo del acto adoptado.","A petición del Parlamento Europeo y únicamente por vicios de fondo, sin que pueda examinar el procedimiento seguido.","Solamente a petición del Estado miembro objeto de la constatación y únicamente en lo que se refiere al respeto de las disposiciones de procedimiento.","De oficio y únicamente en lo que se refiere al respeto de las disposiciones de procedimiento, en el plazo de un año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Solamente a petición del Estado miembro objeto de la constatación y únicamente en lo que se refiere al respeto de las disposiciones de procedimiento</mark></span>El <span class=\"ref-norma\">art. 269 del TFUE</span> dispone: <span class=\"ref-concepto\">\"solamente a petición del Estado miembro objeto de la constatación del Consejo Europeo o del Consejo y únicamente en lo que se refiere al respeto de las disposiciones de procedimiento\"</span>. Solo a petición del Estado afectado y solo por vicios de procedimiento."},{"i":"3-380","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Sólo podrán interponer recurso contra los acuerdos del Consejo de Administración del Banco Europeo de Inversiones:","o":["Cualquier Estado miembro, la Comisión y el Consejo de Administración del Banco.","Los Estados miembros o la Comisión.","El Parlamento Europeo o el Consejo.","Cualquier persona física o jurídica afectada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Los Estados miembros o la Comisión</mark></span>El <span class=\"ref-norma\">art. 271 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Sólo podrán interponer recurso contra tales acuerdos los Estados miembros o la Comisión\"</span>. Solo los Estados miembros o la Comisión."},{"i":"3-381","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea será competente para juzgar en virtud de una cláusula compromisoria contenida en un contrato de Derecho público o de Derecho privado:","o":["Celebrado por la Unión o por su cuenta.","Celebrado exclusivamente por la Comisión.","Celebrado entre Estados miembros.","Celebrado por las instituciones con terceros Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Celebrado por la Unión o por su cuenta</mark></span>El <span class=\"ref-norma\">art. 272 del TFUE</span> dispone: <span class=\"ref-concepto\">\"celebrado por la Unión o por su cuenta\"</span>. Contrato celebrado por la Unión o por su cuenta."},{"i":"3-383","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea no será competente para pronunciarse sobre las disposiciones relativas a la política exterior y de seguridad común. No obstante, será competente para pronunciarse sobre los recursos relativos al control de la legalidad de las decisiones del Consejo por las que se establezcan:","o":["Misiones de gestión de crisis fuera de la Unión.","Acuerdos con terceros Estados y organizaciones.","Medidas restrictivas frente a personas físicas o jurídicas.","Posiciones comunes de la Unión en organizaciones internacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Medidas restrictivas frente a personas físicas o jurídicas</mark></span>El <span class=\"ref-norma\">art. 275 del TFUE</span> dispone: <span class=\"ref-concepto\">\"por las que se establezcan medidas restrictivas frente a personas físicas o jurídicas\"</span>. La excepción son las medidas restrictivas frente a personas físicas o jurídicas."},{"i":"3-384","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. En el ámbito del espacio de libertad, seguridad y justicia, el Tribunal de Justicia no será competente para pronunciarse sobre el ejercicio de las responsabilidades que incumben a los Estados miembros respecto del:","o":["Control de las fronteras exteriores y de la política de asilo e inmigración.","Mantenimiento del orden público y de la salvaguardia de la seguridad interior.","Reconocimiento mutuo de resoluciones judiciales y extrajudiciales en materia civil.","Ejercicio de la cooperación judicial en materia penal y de la cooperación policial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mantenimiento del orden público y de la salvaguardia de la seguridad interior</mark></span>El <span class=\"ref-norma\">art. 276 del TFUE</span> dispone: <span class=\"ref-concepto\">\"otros servicios con funciones coercitivas de un Estado miembro, ni para pronunciarse sobre el ejercicio de las responsabilidades que incumben a los Estados miembros respecto del mantenimiento del orden público y de la salvaguardia de la seguridad interior\"</span>. Queda excluido el control de las responsabilidades de orden público y seguridad interior."},{"i":"3-385","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Aunque haya expirado el plazo para interponer recurso de anulación, cualquiera de las partes de un litigio en el que se cuestione un acto de alcance general podrá recurrir al Tribunal alegando:","o":["La inaplicabilidad de dicho acto por los motivos previstos para el recurso de anulación.","La nulidad absoluta de dicho acto por los motivos previstos para el recurso de omisión.","La ilegalidad sobrevenida del acto por los motivos previstos para la queja ante el Tribunal.","La caducidad del acto por el transcurso del plazo fijado para su aplicación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La inaplicabilidad de dicho acto por los motivos previstos para el recurso de anulación</mark></span>El <span class=\"ref-norma\">art. 277 del TFUE</span> dispone: <span class=\"ref-concepto\">\"podrá recurrir al Tribunal de Justicia de la Unión Europea alegando la inaplicabilidad de dicho acto por los motivos previstos\"</span>. Es la excepción de inaplicabilidad."},{"i":"3-386","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea podrá ordenar las medidas necesarias en los asuntos de que esté conociendo:","o":["Preventivas.","Definitivas.","Excepcionales.","Provisionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Provisionales</mark></span>El <span class=\"ref-norma\">art. 279 del TFUE</span> dispone: <span class=\"ref-concepto\">\"podrá ordenar las medidas provisionales necesarias en los asuntos de que esté conociendo\"</span>. Medidas provisionales."},{"i":"3-387","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Las sentencias del Tribunal de Justicia de la Unión Europea tendrán:","o":["Carácter meramente declarativo.","Efectos solo entre las partes.","Fuerza ejecutiva.","Efecto suspensivo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Fuerza ejecutiva</mark></span>El <span class=\"ref-norma\">art. 280 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Las sentencias del Tribunal de Justicia de la Unión Europea tendrán fuerza ejecutiva\"</span>. Las sentencias tienen fuerza ejecutiva."},{"i":"3-388","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Para modificar las disposiciones del Estatuto del Tribunal de Justicia, el Parlamento Europeo y el Consejo se pronunciarán:","o":["Bien a petición del Tribunal de Justicia y previa aprobación de la Comisión, bien a propuesta de la Comisión y previa aprobación del Tribunal de Justicia.","Bien a petición del Tribunal de Justicia y previa consulta a la Comisión, bien a propuesta de la Comisión y previa consulta al Tribunal de Justicia.","Solo a propuesta de la Comisión y previa consulta al Consejo Europeo.","Bien a petición del Consejo Europeo, bien a propuesta del Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Bien a petición del Tribunal de Justicia y previa consulta a la Comisión, bien a propuesta de la Comisión y previa consulta al Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 281 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo se pronunciarán bien a petición del Tribunal de Justicia y previa consulta a la Comisión, bien a propuesta de la Comisión y previa consulta al Tribunal de Justicia\"</span>. Petición del Tribunal y consulta a la Comisión, o propuesta de la Comisión y consulta al Tribunal."},{"i":"3-ia-3333","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Los actos de prevención y lucha contra el terrorismo que definen un marco de medidas sobre movimiento de capitales incluirán las disposiciones necesarias en materia de:","o":["garantías jurídicas.","control judicial.","cooperación policial.","protección de datos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">garantías jurídicas</mark></span>El <span class=\"ref-norma\">art. 75 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los actos contemplados en el presente artículo incluirán las disposiciones necesarias en materia de garantías jurídicas\"</span>. Deben incluir garantías jurídicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3604","p":"Tratado de Funcionamiento de la Unión Europea. Ejecución de sentencias por incumplimiento. Si el Tribunal declarare que el Estado miembro afectado ha incumplido su sentencia, podrá imponerle el pago de una suma a tanto alzado o de una multa coercitiva; este procedimiento se entenderá:","o":["con carácter sustitutivo del recurso entre Estados.","sin perjuicio de lo dispuesto en el recurso entre Estados.","sin perjuicio de la competencia del Consejo para sancionar.","con carácter previo al recurso por incumplimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin perjuicio de lo dispuesto en el recurso entre Estados</mark></span>El <span class=\"ref-norma\">art. 260.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Este procedimiento se entenderá sin perjuicio de lo dispuesto en el artículo 259\"</span>. No excluye el recurso de un Estado contra otro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3609","p":"Tratado de Funcionamiento de la Unión Europea. Recurso de anulación. El Tribunal será competente para pronunciarse sobre los recursos por incompetencia, vicios sustanciales de forma, violación de los Tratados o de cualquier norma jurídica relativa a su ejecución, o desviación de poder, interpuestos por un Estado miembro, el Parlamento Europeo, el Consejo o:","o":["la Comisión.","el Tribunal de Cuentas.","el Banco Central Europeo.","el Comité de las Regiones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Comisión</mark></span>El <span class=\"ref-norma\">art. 263 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"interpuestos por un Estado miembro, el Parlamento Europeo, el Consejo o la Comisión\"</span>. Legitimados privilegiados: Estados, Parlamento, Consejo y Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3623","p":"Tratado de Funcionamiento de la Unión Europea. Control del procedimiento de violación de valores. El Tribunal de Justicia será competente para pronunciarse sobre la legalidad de un acto adoptado por el Consejo Europeo o por el Consejo en virtud del procedimiento de riesgo de violación de los valores de la Unión, solamente a petición del Estado miembro objeto de la constatación y únicamente en lo que se refiere:","o":["a la proporcionalidad de las medidas de suspensión adoptadas.","a la existencia de la violación grave y persistente constatada.","al respeto de las disposiciones de procedimiento establecidas.","a la competencia del órgano que haya adoptado la constatación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al respeto de las disposiciones de procedimiento establecidas</mark></span>El <span class=\"ref-norma\">art. 269 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"únicamente en lo que se refiere al respeto de las disposiciones de procedimiento establecidas en el citado artículo\"</span>. Control limitado al respeto de las disposiciones de procedimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3624","p":"Tratado de Funcionamiento de la Unión Europea. Control del procedimiento de violación de valores. La petición del Estado miembro objeto de la constatación deberá presentarse en el plazo de un mes a partir de la constatación y el Tribunal se pronunciará:","o":["en el plazo de dos meses a partir de la fecha de la petición.","en el plazo de un mes a partir de la fecha de la petición.","en el plazo de tres meses a partir de la fecha de la petición.","con la mayor brevedad, sin sujeción a plazo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en el plazo de un mes a partir de la fecha de la petición</mark></span>El <span class=\"ref-norma\">art. 269 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Tribunal se pronunciará en el plazo de un mes a partir de la fecha de la petición\"</span>. Un mes para pedir y un mes para resolver. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3625","p":"Tratado de Funcionamiento de la Unión Europea. Litigios con agentes de la Unión. El Tribunal de Justicia de la Unión Europea será competente para pronunciarse sobre cualquier litigio entre la Unión y sus agentes dentro de los límites y en las condiciones que establezca:","o":["el Estatuto de los funcionarios de la Unión y el régimen aplicable a los otros agentes de la Unión.","el Estatuto del Tribunal de Justicia de la Unión Europea y su Reglamento de Procedimiento, en los términos que establezca la propia norma.","los Tratados y los reglamentos internos de cada una de las instituciones.","el Protocolo sobre los privilegios e inmunidades de la Unión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Estatuto de los funcionarios de la Unión y el régimen aplicable a los otros agentes de la Unión</mark></span>El <span class=\"ref-norma\">art. 270 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"dentro de los límites y en las condiciones que establezca el Estatuto de los funcionarios de la Unión y el régimen aplicable a los otros agentes de la Unión\"</span>. Litigios entre la Unión y sus agentes: Estatuto de los funcionarios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3628","p":"Tratado de Funcionamiento de la Unión Europea. Cláusula compromisoria. El Tribunal de Justicia de la Unión Europea será competente para juzgar en virtud de una cláusula compromisoria contenida:","o":["en un convenio internacional celebrado por la Unión con terceros Estados.","en un contrato de Derecho público o de Derecho privado celebrado por la Unión o por su cuenta.","en un acuerdo interinstitucional celebrado entre las instituciones de la Unión, sin perjuicio de lo dispuesto en otras disposiciones.","en un contrato de trabajo celebrado entre la Unión y sus agentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en un contrato de Derecho público o de Derecho privado celebrado por la Unión o por su cuenta</mark></span>El <span class=\"ref-norma\">art. 272 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"contenida en un contrato de Derecho público o de Derecho privado celebrado por la Unión o por su cuenta\"</span>. Cláusula compromisoria en contratos de Derecho público o privado de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3629","p":"Tratado de Funcionamiento de la Unión Europea. Controversias entre Estados. El Tribunal de Justicia será competente para pronunciarse sobre cualquier controversia entre Estados miembros relacionada con el objeto de los Tratados, si dicha controversia le es sometida:","o":["en virtud de un compromiso.","por la Comisión mediante dictamen motivado.","por decisión del Consejo por unanimidad.","a instancia de cualquiera de las partes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en virtud de un compromiso</mark></span>El <span class=\"ref-norma\">art. 273 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"si dicha controversia le es sometida en virtud de un compromiso\"</span>. Hace falta un compromiso entre los Estados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3631","p":"Tratado de Funcionamiento de la Unión Europea. Exclusión de la PESC. El Tribunal de Justicia de la Unión Europea no será competente para pronunciarse sobre las disposiciones relativas a la política exterior y de seguridad común ni sobre los actos adoptados sobre la base de éstas; no obstante, será competente para controlar el respeto de la delimitación entre la PESC y las demás competencias de la Unión y para pronunciarse sobre los recursos relativos al control de la legalidad de las decisiones del Consejo:","o":["por las que se establezcan operaciones de gestión de crisis en terceros países.","por las que se designen representantes especiales de la Unión.","por las que se establezcan medidas restrictivas frente a personas físicas o jurídicas.","por las que se fijen las posiciones de la Unión en las organizaciones internacionales, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por las que se establezcan medidas restrictivas frente a personas físicas o jurídicas</mark></span>El <span class=\"ref-norma\">art. 275 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por las que se establezcan medidas restrictivas frente a personas físicas o jurídicas\"</span>. Salvedad de las sanciones individuales (medidas restrictivas) y del control de la delimitación de competencias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3632","p":"Tratado de Funcionamiento de la Unión Europea. Exclusión en materia de ELSJ. En el ejercicio de sus atribuciones respecto del espacio de libertad, seguridad y justicia en materia de cooperación judicial penal y policial, el Tribunal de Justicia no será competente para comprobar la validez o proporcionalidad de operaciones efectuadas por la policía u otros servicios con funciones coercitivas de un Estado miembro, ni para pronunciarse sobre:","o":["la aplicación de las directivas de aproximación de las legislaciones penales de los Estados miembros.","el ejercicio de las responsabilidades que incumben a los Estados miembros respecto del mantenimiento del orden público y de la salvaguardia de la seguridad interior.","el funcionamiento de Europol y de Eurojust en el ámbito de sus competencias respectivas.","la legalidad de los actos del Consejo que establezcan normas mínimas en materia de procedimiento penal, sin perjuicio de lo dispuesto en otras disposiciones, en los términos que establezca la propia norma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el ejercicio de las responsabilidades que incumben a los Estados miembros respecto del mantenimiento del orden público y de la salvaguardia de la seguridad interior</mark></span>El <span class=\"ref-norma\">art. 276 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"ni para pronunciarse sobre el ejercicio de las responsabilidades que incumben a los Estados miembros respecto del mantenimiento del orden público y de\"</span>. Quedan fuera las operaciones policiales y el orden público y la seguridad interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3633","p":"Tratado de Funcionamiento de la Unión Europea. Excepción de ilegalidad. Aunque haya expirado el plazo previsto para el recurso de anulación, cualquiera de las partes de un litigio en el que se cuestione un acto de alcance general adoptado por una institución, órgano u organismo de la Unión podrá recurrir al Tribunal de Justicia alegando:","o":["la inaplicabilidad de dicho acto por los motivos previstos para el recurso de anulación.","la nulidad de dicho acto por infracción de los principios generales del Derecho.","la inconstitucionalidad de dicho acto en el ordenamiento jurídico del Estado miembro, en los términos que establezca la propia norma.","la caducidad de dicho acto por el transcurso del tiempo desde su adopción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la inaplicabilidad de dicho acto por los motivos previstos para el recurso de anulación</mark></span>El <span class=\"ref-norma\">art. 277 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá recurrir al Tribunal de Justicia de la Unión Europea alegando la inaplicabilidad de dicho acto por los motivos previstos en el párrafo segundo\"</span>. Es la excepción de ilegalidad: se alega la inaplicabilidad del acto de alcance general. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3634","p":"Tratado de Funcionamiento de la Unión Europea. Efecto suspensivo. Los recursos interpuestos ante el Tribunal de Justicia de la Unión Europea no tendrán efecto suspensivo; sin embargo, el Tribunal podrá, si estima que las circunstancias así lo exigen:","o":["declarar la nulidad provisional del acto impugnado.","acordar la devolución del acto a la institución emisora.","imponer a la institución la adopción de un acto alternativo.","ordenar la suspensión de la ejecución del acto impugnado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ordenar la suspensión de la ejecución del acto impugnado</mark></span>El <span class=\"ref-norma\">art. 278 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá, si estima que las circunstancias así lo exigen, ordenar la suspensión de la ejecución del acto impugnado\"</span>. No hay efecto suspensivo automático. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3635","p":"Tratado de Funcionamiento de la Unión Europea. Medidas provisionales. El Tribunal de Justicia de la Unión Europea podrá ordenar las medidas provisionales necesarias:","o":["en los asuntos que le sean sometidos por los Estados miembros.","en los asuntos que afecten a los derechos fundamentales.","en los asuntos de que esté conociendo.","en los asuntos pendientes ante los órganos jurisdiccionales nacionales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en los asuntos de que esté conociendo</mark></span>El <span class=\"ref-norma\">art. 279 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá ordenar las medidas provisionales necesarias en los asuntos de que esté conociendo\"</span>. En los asuntos de que esté conociendo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 45 — Agencia Europea de Defensa EXOF","q":[{"i":"3-43","p":"Tratado de la Unión Europea. Tendrá como misión contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos de capacidades contraídos por los Estados miembros:","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","La Agencia Europea de Defensa.","El Presidente del Parlamento Europeo.","El Presidente del Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Agencia Europea de Defensa</mark></span>El <span class=\"ref-norma\">art. 45.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Agencia Europea de Defensa a que se refiere el apartado 3 del artículo 42 estará bajo la autoridad del Consejo y tendrá como misión: a) \u0007contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos de capacidades contraídos por los Estados miembros\"</span>. El artículo 45.1.a) del TUE atribuye a la Agencia Europea de Defensa la misión de contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos de capacidades contraídos por estos."},{"i":"3-173","p":"Tratado de la Unión Europea. Disposiciones sobre la política común de seguridad y defensa. La Agencia Europea de Defensa. El Consejo adoptará por ______ una decisión en la que se determinará el estatuto, la sede y la forma de funcionamiento de la Agencia.","o":["Unanimidad.","Mayoría simple.","Mayoría absoluta.","Mayoría cualificada."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Mayoría cualificada</mark></span>Según el <span class=\"ref-norma\">art. 45.2 del TUE</span>: <span class=\"ref-concepto\">\"El Consejo adoptará por mayoría cualificada una decisión en la que se determinará el estatuto, la sede y la forma de funcionamiento de la Agencia.\"</span> (verificado con el texto del temario)."},{"i":"3-223","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. ¿Quién tendrá como misión contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos de capacidades contraídos por los Estados miembros?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo.","La Agencia Europea de Defensa.","El Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Agencia Europea de Defensa</mark></span>El <span class=\"ref-norma\">art. 45.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Agencia Europea de Defensa a que se refiere el apartado 3 del artículo 42 estará bajo la autoridad del Consejo y tendrá como misión: a) \u0007contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos de capacidades contraídos por los Estados miembros\"</span>. El artículo 45.1.a) del TUE atribuye a la Agencia Europea de Defensa la misión de contribuir a definir los objetivos de capacidades militares de los Estados miembros y a evaluar el respeto de los compromisos contraídos por estos."},{"i":"3-294","p":"Tratado de la Unión Europea. Disposiciones sobre la política común de seguridad y defensa. ¿Quién determinará las necesidades operativas y fomentará medidas para satisfacerlas?","o":["La Agencia Europea de Defensa.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo.","El Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Agencia Europea de Defensa</mark></span>El <span class=\"ref-norma\">art. 42.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Agencia en el ámbito del desarrollo de las capacidades de defensa, la investigación, la adquisición y el armamento (en lo sucesivo denominada “Agencia Europea de Defensa”) determinará las necesidades operativas, fomentará medidas para satisfacerlas\"</span>. El artículo 45.1.a) y b) del TUE atribuye a la Agencia Europea de Defensa determinar las necesidades operativas y fomentar medidas para satisfacerlas."},{"i":"3-297","p":"Tratado de la Unión Europea. ¿Quién tendrá como misión apoyar la investigación sobre tecnología de defensa y coordinar y planificar actividades de investigación conjuntas y estudios de soluciones técnicas que respondan a las futuras necesidades operativas?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo.","La Agencia Europea de Defensa.","El Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Agencia Europea de Defensa</mark></span>El <span class=\"ref-norma\">art. 45.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007apoyar la investigación sobre tecnología de defensa y coordinar y planificar actividades de investigación conjuntas y estudios de soluciones técnicas que respondan a las futuras necesidades operativas\"</span>. El artículo 45.1.d) del TUE atribuye a la Agencia Europea de Defensa apoyar la investigación sobre tecnología de defensa y coordinar y planificar actividades de investigación conjuntas y estudios de soluciones técnicas que respondan a las futuras necesidades operativas."},{"i":"3-ia-3222","p":"Tratado de la Unión Europea. Política común de seguridad y defensa. Los Estados miembros pondrán a disposición de la Unión, a efectos de la aplicación de la política común de seguridad y defensa, capacidades civiles y militares; la Agencia en el ámbito del desarrollo de las capacidades de defensa, la investigación, la adquisición y el armamento se denomina:","o":["Agencia Europea de Armamento.","Agencia de Capacidades de la Unión.","Agencia Europea de Seguridad y Defensa.","Agencia Europea de Defensa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Agencia Europea de Defensa</mark></span>El <span class=\"ref-norma\">art. 42.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en lo sucesivo denominada “Agencia Europea de Defensa”\"</span>. La denominación es Agencia Europea de Defensa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3233","p":"Tratado de la Unión Europea. Agencia Europea de Defensa. La Agencia Europea de Defensa estará bajo la autoridad del Consejo y tendrá como misión, entre otras, contribuir a definir los objetivos de capacidades militares de los Estados miembros, fomentar la armonización de las necesidades operativas y:","o":["proponer proyectos multilaterales para cumplir los objetivos de capacidades militares y coordinar los programas ejecutados por los Estados miembros.","aprobar los programas de armamento de los Estados miembros y supervisar su ejecución presupuestaria, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","dirigir las operaciones militares de la Unión y coordinar los mandos nacionales participantes.","gestionar los fondos de cooperación en materia de defensa y distribuirlos entre los Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">proponer proyectos multilaterales para cumplir los objetivos de capacidades militares y coordinar los programas ejecutados por los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 45.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"proponer proyectos multilaterales para cumplir los objetivos de capacidades militares y coor-dinar los programas ejecutados por los Estados miembros\"</span>. Propone proyectos multilaterales y coordina programas de los Estados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 71 a 76 TFUE — COSI, orden público y cooperación administrativa ✱","q":[{"i":"3-45","p":"Tratado de Funcionamiento de la Unión Europea. Se creará un comité permanente en ________ con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior.","o":["La Comisión.","El Consejo.","El Parlamento Europeo.","El Consejo de Europa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 71 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior\"</span>. El artículo 71 del TFUE establece que se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior."},{"i":"3-205","p":"Tratado de Funcionamiento de la Unión Europea. ¿Dónde se creará un comité permanente con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior?","o":["En el Parlamento Europeo.","En el Consejo.","En la Comisión.","En el Tribunal de Justicia de la Unión Europea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el Consejo</mark></span>El <span class=\"ref-norma\">art. 71 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior\"</span>. El artículo 71 del TFUE establece que se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior."},{"i":"3-320","p":"Tratado de Funcionamiento de la Unión Europea. ¿Dónde se creará un comité permanente con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior?","o":["En el Parlamento Europeo.","En el Consejo.","En la Comisión.","En el Tribunal de Justicia de la Unión Europea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En el Consejo</mark></span>El <span class=\"ref-norma\">art. 71 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de seguridad interior\"</span>. El artículo 71 TFUE crea en el seno del Consejo el Comité Permanente de Seguridad Interior (COSI)."},{"i":"3-352","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. El título del espacio de libertad, seguridad y justicia se entenderá sin perjuicio del ejercicio de las responsabilidades que incumben a los Estados miembros en cuanto al:","o":["Mantenimiento del orden público y la salvaguardia de la seguridad exterior.","Mantenimiento del orden público y la salvaguardia de la seguridad interior.","Control de las fronteras exteriores y la seguridad nacional.","Ejercicio de la política de asilo y la política de inmigración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Mantenimiento del orden público y la salvaguardia de la seguridad interior</mark></span>El <span class=\"ref-norma\">art. 72 del TFUE</span> dispone: <span class=\"ref-concepto\">\"mantenimiento del orden público y la salvaguardia de la seguridad interior\"</span>. Los Estados conservan el orden público y la seguridad interior."},{"i":"3-353","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. Los Estados miembros tendrán la posibilidad de organizar entre ellos y bajo su responsabilidad formas de cooperación y coordinación entre los servicios competentes de sus administraciones responsables de velar por la:","o":["Seguridad nacional.","Seguridad interior.","Seguridad pública.","Defensa común."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Seguridad nacional</mark></span>El <span class=\"ref-norma\">art. 73 del TFUE</span> dispone: <span class=\"ref-concepto\">\"responsables de velar por la seguridad nacional\"</span>. Cooperación voluntaria entre servicios responsables de la seguridad nacional."},{"i":"3-354","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. El Consejo adoptará medidas para garantizar la cooperación administrativa entre los servicios competentes de los Estados miembros en los ámbitos del espacio de libertad, seguridad y justicia. Se pronunciará:","o":["A propuesta del Parlamento Europeo y previa consulta a la Comisión.","Por iniciativa de un tercio de los Estados miembros.","Previa aprobación del Parlamento Europeo.","A propuesta de la Comisión y previa consulta al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A propuesta de la Comisión y previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 74 del TFUE</span> dispone: <span class=\"ref-concepto\">\"a propuesta de la Comisión, sin perjuicio del artículo 76, y previa consulta al Parlamento Europeo\"</span>. A propuesta de la Comisión y previa consulta al Parlamento Europeo."},{"i":"3-356","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. Los actos sobre cooperación judicial en materia penal y cooperación policial se adoptarán:","o":["A propuesta de la Comisión o por iniciativa de un tercio de los Estados miembros de la Unión.","A propuesta de la Comisión o por iniciativa de la cuarta parte de los Estados miembros.","A propuesta del Consejo o por iniciativa de la mitad de los Estados miembros de la Unión.","Por iniciativa del Parlamento Europeo o de la cuarta parte de los Estados miembros de la Unión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A propuesta de la Comisión o por iniciativa de la cuarta parte de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 76 del TFUE</span> dispone: <span class=\"ref-concepto\">\"a propuesta de la Comisión, o b) por iniciativa de la cuarta parte de los Estados miembros\"</span>. Propuesta de la Comisión o iniciativa de la cuarta parte de los Estados miembros."},{"i":"3-ia-3328","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Se creará un comité permanente en el Consejo con objeto de garantizar dentro de la Unión el fomento y la intensificación de la cooperación operativa en materia de:","o":["seguridad exterior.","seguridad interior.","seguridad nacional.","seguridad ciudadana."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seguridad interior</mark></span>El <span class=\"ref-norma\">art. 71 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el fomento y la intensificación de la cooperación operativa en materia de seguridad interior\"</span>. Es el Comité Permanente de Seguridad Interior (COSI). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3329","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. El título del espacio de libertad, seguridad y justicia se entenderá sin perjuicio del ejercicio de las responsabilidades que incumben a los Estados miembros en cuanto:","o":["al mantenimiento del orden público y la salvaguardia de la seguridad interior.","al mantenimiento de la seguridad nacional y la integridad territorial.","a la defensa de la soberanía y la salvaguardia del orden constitucional, en los términos que establezca la propia norma.","a la protección de los ciudadanos y la prevención de la delincuencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al mantenimiento del orden público y la salvaguardia de la seguridad interior</mark></span>El <span class=\"ref-norma\">art. 72 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en cuanto al mantenimiento del orden público y la salvaguardia de la seguridad interior\"</span>. Orden público y seguridad interior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3330","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Los Estados miembros tendrán la posibilidad de organizar entre ellos y bajo su responsabilidad formas de cooperación y coordinación en la medida en que lo estimen apropiado, entre los servicios competentes de sus administraciones responsables de:","o":["velar por el orden público.","velar por la seguridad ciudadana.","velar por la protección civil.","velar por la seguridad nacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">velar por la seguridad nacional</mark></span>El <span class=\"ref-norma\">art. 73 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"responsables de velar por la seguridad nacional\"</span>. Se refiere a los servicios responsables de la seguridad nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3331","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. El Consejo adoptará medidas para garantizar la cooperación administrativa entre los servicios competentes de los Estados miembros y entre dichos servicios y la Comisión, pronunciándose a propuesta de la Comisión y:","o":["previa aprobación del Parlamento Europeo.","previa consulta al Consejo Europeo.","previa consulta al Parlamento Europeo.","previo dictamen del Comité de las Regiones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 74 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se pronunciará a propuesta de la Comisión, sin perjuicio del artículo 76, y previa consulta al Parlamento Europeo\"</span>. A propuesta de la Comisión y previa consulta al Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3332","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. En lo que se refiere a la prevención y lucha contra el terrorismo y las actividades con él relacionadas, el Parlamento Europeo y el Consejo definirán mediante reglamentos, con arreglo al procedimiento legislativo ordinario, un marco de medidas administrativas sobre movimiento de capitales y pagos, tales como:","o":["la intervención de cuentas bancarias y la prohibición de transacciones con entidades de terceros países.","la inmovilización de fondos, activos financieros o beneficios económicos cuya propiedad, posesión o tenencia ostenten personas físicas o jurídicas, grupos o entidades no estatales.","la supervisión de las transferencias internacionales de fondos y el registro de operaciones sospechosas.","el embargo preventivo de bienes y la prohibición de operaciones con personas incluidas en listas del Consejo, sin perjuicio de lo dispuesto en otras disposiciones, en los términos que establezca la propia norma."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la inmovilización de fondos, activos financieros o beneficios económicos cuya propiedad, posesión o tenencia ostenten personas físicas o jurídicas, grupos o entidades no estatales</mark></span>El <span class=\"ref-norma\">art. 75 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la inmovilización de fondos, activos financieros o beneficios económicos cuya propiedad, posesión o tenencia ostenten personas físicas o jurídicas, grupos o entidades no estatales\"</span>. Marco de medidas administrativas: inmovilización de fondos de personas, grupos o entidades no estatales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3334","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Los actos de cooperación judicial en materia penal y de cooperación policial se adoptarán a propuesta de la Comisión o:","o":["por iniciativa de un tercio de los Estados miembros, salvo que se disponga otra cosa en la normativa aplicable.","por iniciativa del Parlamento Europeo y del Consejo.","por iniciativa de la mitad de los Estados miembros.","por iniciativa de la cuarta parte de los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por iniciativa de la cuarta parte de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 76 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por iniciativa de la cuarta parte de los Estados miembros\"</span>. A propuesta de la Comisión o por iniciativa de la cuarta parte de los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3503","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. Salvo disposición en contrario de los Tratados, el Parlamento Europeo decidirá por mayoría de los votos emitidos, y el quórum lo fijará:","o":["el Consejo mediante reglamento.","el Tratado de Funcionamiento de la Unión Europea.","el reglamento interno.","una decisión de la Mesa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el reglamento interno</mark></span>El <span class=\"ref-norma\">art. 231 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Salvo disposición en contrario de los Tratados, el Parlamento Europeo decidirá por mayoría de los vo-tos emitidos. El reglamento interno fijará el quórum\"</span>. Mayoría de los votos emitidos y quórum fijado por el reglamento interno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3651","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. El Comité de las Regiones será consultado por el Parlamento Europeo, el Consejo o la Comisión, en los casos previstos en los Tratados y en cualesquiera otros, en particular aquellos que afecten a:","o":["la cohesión económica y social.","las políticas regionales y de desarrollo.","la cooperación transfronteriza.","los fondos estructurales de la Unión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la cooperación transfronteriza</mark></span>El <span class=\"ref-norma\">art. 307 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en particular aquellos que afecten a la cooperación transfronteriza\"</span>. Casos que afecten a la cooperación transfronteriza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 251 a 255 TFUE — Composición del TJUE EXOF ✱","q":[{"i":"3-47","p":"Tratado de Funcionamiento de la Unión Europea. ¿Cada cuántos años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea?","o":["Cada dos años.","Cada cuatro años.","Cada tres años.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cada tres años</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea\"</span>. El artículo 253 del TFUE establece que cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales del Tribunal de Justicia, en las condiciones establecidas en su Estatuto."},{"i":"3-56","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Señale la opción incorrecta en referencia al Tribunal de Justicia de la Unión Europea:","o":["Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales.","Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años.","Los jueces y los abogados generales salientes podrán ser nuevamente designados.","El Tribunal de Justicia aprobará su Reglamento de Procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal de Justicia aprobará su Reglamento de Procedimiento</mark></span>El TJ no lo aprueba él mismo: requiere aprobación del Consejo. A, B y C son literales del art. 253. Según el <span class=\"ref-norma\">art. 253 del TFUE</span>: <span class=\"ref-concepto\">\"El Tribunal de Justicia establecerá su Reglamento de Procedimiento. Dicho reglamento requerirá la aprobación del Consejo.\"</span> (verificado con el texto del temario)."},{"i":"3-57","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. Señale la incorrecta:","o":["Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años.","Los jueces y los abogados generales salientes podrán ser nuevamente designados.","El Tribunal de Justicia nombrará a su secretario y establecerá el estatuto de este.","El Tribunal de Justicia establecerá y aprobará su Reglamento de Procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal de Justicia establecerá y aprobará su Reglamento de Procedimiento</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia establecerá su Reglamento de Procedimiento\"</span>. La opción correcta es la D, por ser la incorrecta. El artículo 253 del TFUE establece que el Tribunal de Justicia establecerá su Reglamento de Procedimiento, pero dicho reglamento requerirá la aprobación del Consejo, por lo que el Tribunal no lo aprueba por sí solo."},{"i":"3-105","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea. Se constituirá un comité para que se pronuncie sobre la idoneidad de los candidatos para el ejercicio de las funciones de juez y abogado general del Tribunal de Justicia. El comité:","o":["Estará compuesto por siete personalidades.","Estará compuesto por cinco personalidades.","Estará compuesto por seis personalidades.","Estará compuesto por nueve personalidades."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Estará compuesto por siete personalidades</mark></span>El <span class=\"ref-norma\">art. 255 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El comité estará compuesto por siete personalidades elegidas de entre antiguos miembros del Tribunal de Justicia y del Tribunal General, miembros de los órganos jurisdiccionales nacionales superiores y juristas de reconocida competencia, uno de los cuales será propuesto por el Parlamento Europeo\"</span>. El artículo 255 del TFUE establece que el comité que se pronuncia sobre la idoneidad de los candidatos a juez y abogado general estará compuesto por siete personalidades."},{"i":"3-109","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea actuará en: Señale la INCORRECTA.","o":["Juez único.","Salas.","Gran Sala.","Pleno, cuando el Estatuto así lo disponga."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Juez único</mark></span>El <span class=\"ref-norma\">art. 251 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia actuará en Salas o en Gran Sala, de conformidad con las normas establecidas al respecto en el Estatuto del Tribunal de Justicia de la Unión Europea. Cuando el Estatuto así lo disponga, el Tribunal de Justicia también podrá actuar en Pleno\"</span>. La opción correcta es la A, por ser la incorrecta. El artículo 251 del TFUE establece que el Tribunal de Justicia actuará en Salas o en Gran Sala, y en Pleno cuando el Estatuto así lo disponga, sin que se prevea que actúe como juez único."},{"i":"3-126","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia estará asistido por:","o":["Ocho abogados generales.","Diez abogados generales.","Nueve abogados generales.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ocho abogados generales</mark></span>Según el <span class=\"ref-norma\">art. 252 del TFUE</span>: <span class=\"ref-concepto\">\"El Tribunal de Justicia estará asistido por ocho abogados generales. Si el Tribunal de Justicia lo solicitare, el Consejo, por unanimidad, podrá aumentar el número de abogados generales.\"</span> (verificado con el texto del temario)."},{"i":"3-224","p":"Tratado de Funcionamiento de la Unión Europea. ¿En qué consiste la función del abogado general?","o":["Procurarán apoyar los derechos humanos y las libertades fundamentales reconocidos por el derecho de la Unión Europea.","Presentarán públicamente, con toda imparcialidad e independencia, conclusiones motivadas sobre los asuntos que, de conformidad con el Estatuto del Tribunal de Justicia de la Unión Europea, requieran su intervención.","Asesorar al Tribunal de Justicia de la Unión Europea en la interpretación del Tratado de la Unión Europea y el Tratado de Funcionamiento de la Unión Europea.","Todos son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Presentarán públicamente, con toda imparcialidad e independencia, conclusiones motivadas sobre los asuntos que, de conformidad con el Estatuto del Tribunal de Justicia de la Unión Europea, requieran su intervención</mark></span>El <span class=\"ref-norma\">art. 252 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La función del abogado general consistirá en presentar públicamente, con toda imparcialidad e independencia, conclusiones motivadas sobre los asuntos que, de conformidad con el Estatuto del Tribunal de Justicia de la Unión Europea, requieran su intervención\"</span>. El artículo 252 del TFUE establece que la función del abogado general consiste en presentar públicamente, con toda imparcialidad e independencia, conclusiones motivadas sobre los asuntos que, conforme al Estatuto del Tribunal de Justicia, requieran su intervención."},{"i":"3-229","p":"Tratado de Funcionamiento de la Unión Europea. ¿Cada cuánto tiempo tendrá lugar una renovación parcial de los jueces del Tribunal General?","o":["2 años.","4 años.","3 años.","1 año."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">3 años</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea\"</span>. (Judges of the General Court are appointed for six years, with a partial renewal every three years.)"},{"i":"3-235","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal General establecerá su Reglamento de Procedimiento de acuerdo con el Tribunal de Justicia. Dicho reglamento requerirá la aprobación:","o":["Del Consejo Europeo.","De la Comisión.","Del Consejo.","Del Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Del Consejo</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia establecerá su Reglamento de Procedimiento. Dicho reglamento requerirá la aprobación del Consejo\"</span>. El artículo 254 del TFUE dispone que el Tribunal General establecerá su Reglamento de Procedimiento de acuerdo con el Tribunal de Justicia y que dicho reglamento requerirá la aprobación del Consejo."},{"i":"3-274","p":"Tratado de Funcionamiento de la Unión Europea. El número de jueces del Tribunal General será fijado:","o":["Por el Estatuto del Tribunal General.","Por el Estatuto del Tribunal de Justicia de la Unión Europea.","Por el Estatuto del Tribunal de Justicia.","Por el Estatuto de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por el Estatuto del Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 252 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La función del abogado general consistirá en presentar públicamente, con toda imparcialidad e independencia, conclusiones motivadas sobre los asuntos que, de conformidad con el Estatuto del Tribunal de Justicia de la Unión Europea, requieran su intervención\"</span>. El artículo 254 del TFUE establece que el número de jueces del Tribunal General será fijado por el Estatuto del Tribunal de Justicia de la Unión Europea."},{"i":"3-276","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia de la Unión Europea. ¿Con qué periodicidad tendrá lugar una renovación parcial de los jueces y abogados generales?","o":["Tres años.","Cuatro años.","Cinco años.","Nueve años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Tres años</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea\"</span>. El artículo 253 del TFUE establece que cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales del Tribunal de Justicia."},{"i":"3-288","p":"Tratado de Funcionamiento de la Unión Europea. Los jueces y los abogados generales del Tribunal de Justicia, elegidos entre personalidades que ofrezcan absolutas garantías de independencia y que reúnan las condiciones requeridas para el ejercicio, en sus respectivos países, de las más altas funciones jurisdiccionales o que sean jurisconsultos de reconocida competencia, serán designados de común acuerdo por los Gobiernos de los Estados miembros por un periodo de:","o":["3 años.","5 años.","6 años.","4 años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">6 años</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los jueces y los abogados generales del Tribunal de Justicia, elegidos entre personalidades que ofrezcan absolutas garantías de independencia y que reúnan las condiciones requeridas para el ejercicio, en sus respectivos países, de las más altas funciones jurisdiccionales o que sean jurisconsultos de reconocida compe-\"</span>. El artículo 253 del TFUE establece que los jueces y los abogados generales del Tribunal de Justicia serán designados de común acuerdo por los Gobiernos de los Estados miembros por un período de seis años."},{"i":"3-295","p":"Tratado de Funcionamiento de la Unión Europea. Tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea, cada:","o":["3 años.","5 años.","6 años.","4 años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">3 años</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea\"</span>. El artículo 253 del TFUE establece que cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales, en las condiciones establecidas en el Estatuto del Tribunal de Justicia de la Unión Europea."},{"i":"3-299","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. Señale la incorrecta:","o":["Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años.","Los jueces y los abogados generales salientes podrán ser nuevamente designados.","El Tribunal de Justicia nombrará a su secretario y establecerá el estatuto de este.","El Tribunal de Justicia establecerá y aprobará su Reglamento de Procedimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal de Justicia establecerá y aprobará su Reglamento de Procedimiento</mark></span>El <span class=\"ref-norma\">art. 253 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia establecerá su Reglamento de Procedimiento\"</span>. Según el artículo 253 TFUE, el Tribunal de Justicia establece su Reglamento de Procedimiento, pero este requiere la aprobación del Consejo; el Tribunal no puede aprobarlo por sí solo."},{"i":"3-330","p":"Tratado de Funcionamiento de la Unión Europea. Se constituirá un comité para que se pronuncie sobre la idoneidad de los candidatos para el ejercicio de las funciones de juez y abogado general del Tribunal de Justicia y del Tribunal General. ¿Por cuántas personalidades estará integrado dicho comité?","o":["Cinco.","Seis.","Siete.","Ocho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Siete</mark></span>El <span class=\"ref-norma\">art. 255 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El comité estará compuesto por siete personalidades elegidas de entre antiguos miembros del Tribunal de Justicia y del Tribunal General, miembros de los órganos jurisdiccionales nacionales superiores y juristas de reconocida competencia, uno de los cuales será propuesto por el Parlamento Europeo\"</span>. El artículo 255 TFUE fija en siete el número de personalidades que integran este comité."},{"i":"3-ia-3534","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. El Tribunal de Justicia actuará en Salas o en Gran Sala, de conformidad con las normas establecidas en su Estatuto, y cuando el Estatuto así lo disponga:","o":["también podrá actuar en Sección.","también podrá actuar como Tribunal único.","también podrá actuar en Comité.","también podrá actuar en Pleno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">también podrá actuar en Pleno</mark></span>El <span class=\"ref-norma\">art. 251 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Cuando el Estatuto así lo disponga, el Tribunal de Justicia también podrá actuar en Pleno\"</span>. Puede actuar en Pleno si lo dispone el Estatuto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3535","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. El Tribunal de Justicia estará asistido por ocho abogados generales; si el Tribunal lo solicitare, el Consejo, por unanimidad, podrá:","o":["reducir el número de abogados generales.","nombrar abogados generales adicionales por mayoría.","aumentar el número de abogados generales.","fijar el estatuto de los abogados generales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">aumentar el número de abogados generales</mark></span>El <span class=\"ref-norma\">art. 252 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia estará asistido por ocho abogados generales. Si el Tribunal de Justicia lo solicitare, el Consejo, por unanimidad, podrá aumentar el número de abogados generales\"</span>. Ocho abogados generales, ampliables por unanimidad del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3536","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. La función del abogado general consistirá en presentar públicamente, con toda imparcialidad e independencia:","o":["informes sobre la jurisprudencia aplicable a los asuntos que requieran su intervención.","conclusiones motivadas sobre los asuntos que requieran su intervención.","propuestas de resolución sobre los asuntos que requieran su intervención.","dictámenes vinculantes sobre los asuntos que requieran su intervención."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">conclusiones motivadas sobre los asuntos que requieran su intervención</mark></span>El <span class=\"ref-norma\">art. 252 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"presentar públicamente, con toda imparcialidad e independen-cia, conclusiones motivadas sobre los asuntos\"</span>. Presenta conclusiones motivadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3537","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. Los jueces y los abogados generales del Tribunal de Justicia serán designados de común acuerdo por los Gobiernos de los Estados miembros por un período de seis años, tras consultar al comité previsto; cada tres años tendrá lugar:","o":["una renovación parcial de los jueces y abogados generales.","una renovación total de los jueces y abogados generales, en los términos que establezca la propia norma.","una evaluación de los jueces y abogados generales.","una elección del Presidente del Tribunal de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una renovación parcial de los jueces y abogados generales</mark></span>El <span class=\"ref-norma\">art. 253 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial de los jueces y abogados generales\"</span>. Renovación parcial cada tres años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3539","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. El Tribunal de Justicia establecerá su Reglamento de Procedimiento; dicho reglamento requerirá:","o":["la aprobación del Parlamento Europeo.","la consulta de la Comisión.","la aprobación del Consejo.","la aprobación del Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la aprobación del Consejo</mark></span>El <span class=\"ref-norma\">art. 253 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia establecerá su Reglamento de Procedimiento. Dicho reglamento requerirá la aproba-ción del Consejo\"</span>. Requiere la aprobación del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3540","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal General. El número de jueces del Tribunal General será fijado por el Estatuto del Tribunal de Justicia de la Unión Europea, que podrá disponer que el Tribunal General esté asistido:","o":["por magistrados suplentes.","por abogados generales.","por jueces ponentes.","por tribunales especializados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por abogados generales</mark></span>El <span class=\"ref-norma\">art. 254 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Estatuto podrá disponer que el Tribunal General esté asistido por abogados generales\"</span>. Puede estar asistido por abogados generales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3541","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal General. Los miembros del Tribunal General serán designados de común acuerdo por los Gobiernos de los Estados miembros por un período de seis años, tras consultar al comité previsto; cada tres años tendrá lugar una renovación parcial y los miembros salientes:","o":["podrán ser nuevamente designados.","no podrán ser nuevamente designados.","podrán ser reelegidos una sola vez.","serán sustituidos por designación del Consejo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrán ser nuevamente designados</mark></span>El <span class=\"ref-norma\">art. 254 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Cada tres años tendrá lugar una renovación parcial. Los miembros salientes podrán ser nuevamente designados\"</span>. Seis años, renovación parcial trienal y posible redesignación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3542","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal General. El Tribunal General establecerá su Reglamento de Procedimiento:","o":["de forma autónoma, y dicho reglamento requerirá la aprobación del Parlamento Europeo.","de acuerdo con el Consejo, y dicho reglamento requerirá la aprobación del Tribunal de Justicia, salvo que se disponga otra cosa en la normativa aplicable.","de forma autónoma, y dicho reglamento no requerirá aprobación alguna.","de acuerdo con el Tribunal de Justicia, y dicho reglamento requerirá la aprobación del Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">de acuerdo con el Tribunal de Justicia, y dicho reglamento requerirá la aprobación del Consejo</mark></span>El <span class=\"ref-norma\">art. 254 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Tribunal General establecerá su Reglamento de Procedimiento de acuerdo con el Tribunal de Justicia. Dicho reglamento requerirá la aprobación del Consejo\"</span>. De acuerdo con el Tribunal de Justicia y con aprobación del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3543","p":"Tratado de Funcionamiento de la Unión Europea. Comité de selección. Se constituirá un comité para que se pronuncie sobre la idoneidad de los candidatos para el ejercicio de las funciones de juez y abogado general antes de que los Gobiernos procedan a los nombramientos; el comité estará compuesto por siete personalidades, una de las cuales será propuesta:","o":["por el Consejo Europeo.","por la Comisión.","por el Parlamento Europeo.","por el Presidente del Tribunal de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 255 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"uno de los cuales será propuesto por el Parlamento Europeo\"</span>. Siete personalidades, una de ellas propuesta por el Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3544","p":"Tratado de Funcionamiento de la Unión Europea. Comité de selección. El Consejo adoptará una decisión por la que se establezcan las normas de funcionamiento del comité de idoneidad de jueces y abogados generales, así como una decisión por la que se designe a sus miembros, pronunciándose:","o":["a propuesta de la Comisión.","por iniciativa del Presidente del Tribunal de Justicia.","previa aprobación del Parlamento Europeo, sin perjuicio de lo dispuesto en otras disposiciones.","por iniciativa del Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por iniciativa del Presidente del Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 255 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por iniciativa del Presidente del Tribunal\"</span>. Por iniciativa del Presidente del Tribunal de Justicia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 301 a 304 TFUE — Comité Económico y Social · R28 ✱ R28","q":[{"i":"3-52","p":"Tratado de Funcionamiento de la Unión Europea. El número de miembros del Comité Económico y Social no excederá de:","o":["Trescientos cuarenta.","Trescientos cincuenta.","Doscientos cincuenta.","Doscientos cuarenta."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Trescientos cincuenta</mark></span>El <span class=\"ref-norma\">art. 301 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El número de miembros del Comité Económico y Social no excederá de trescientos cincuenta. El Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca la composición del Comité. El Consejo establecerá las dietas de los miembros del Comité\"</span>. Según el art. 301 TFUE, el número de miembros del Comité Económico y Social no excederá de trescientos cincuenta."},{"i":"3-140","p":"Tratado de Funcionamiento de la Unión Europea. El Comité Económico y Social. Señale la correcta:","o":["El número de miembros del Comité Económico y Social no excederá de trescientos cincuenta.","El Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca la composición del Comité.","El Consejo establecerá las dietas de los miembros del Comité.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>A, B y C son literales del art. 301. Según el <span class=\"ref-norma\">art. 301 del TFUE</span>: <span class=\"ref-concepto\">\"El número de miembros del Comité Económico y Social no excederá de trescientos cincuenta. El Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca la composición del Comité. El Consejo establecerá las dietas de los miembros del Comité.\"</span> (verificado con el texto del temario)."},{"i":"3-389","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Órganos consultivos de la Unión. El Comité Económico y Social designará de entre sus miembros al Presidente y a la Mesa, por un período de:","o":["Dos años y medio.","Tres años y medio.","Cinco años.","Dos años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos años y medio</mark></span>El <span class=\"ref-norma\">art. 303 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Comité designará de entre sus miembros al Presidente y a la Mesa, por un período de dos años y medio\"</span>. Presidente y Mesa: dos años y medio."},{"i":"3-390","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Órganos consultivos de la Unión. El Parlamento Europeo, el Consejo o la Comisión podrán fijar al Comité Económico y Social un plazo para la presentación de su dictamen, que no podrá ser inferior a:","o":["Quince días a partir de la fecha de la notificación.","Dos meses a partir de la fecha de la notificación.","Tres meses a partir de la fecha de la notificación.","Un mes a partir de la fecha de la notificación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un mes a partir de la fecha de la notificación</mark></span>El <span class=\"ref-norma\">art. 304 del TFUE</span> dispone: <span class=\"ref-concepto\">\"que no podrá ser inferior a un mes a partir de la fecha de la notificación que, a tal fin, se curse al Presidente\"</span>. Plazo mínimo de un mes."},{"i":"3-411","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. Los miembros del Comité Económico y Social serán nombrados para un período de cinco años. El mandato de los miembros del Comité será:","o":["Renovable.","No renovable.","Renovable una sola vez.","Renovable por períodos de dos años y medio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Renovable</mark></span>El <span class=\"ref-norma\">art. 302.1 de la TFUE</span> dispone: <span class=\"ref-concepto\">\"El mandato de los miembros del Comité será renovable\"</span> El Consejo adopta la lista de miembros de conformidad con las propuestas presentadas por cada Estado miembro."},{"i":"3-ia-3642","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. El número de miembros del Comité Económico y Social no excederá de trescientos cincuenta, y el Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca:","o":["el reglamento interno del Comité.","el presupuesto del Comité.","el estatuto de los miembros del Comité.","la composición del Comité."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la composición del Comité</mark></span>El <span class=\"ref-norma\">art. 301 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca la composición del Comité\"</span>. Composición del Comité, por unanimidad y a propuesta de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3643","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. Los miembros del Comité Económico y Social serán nombrados para un período de cinco años, el Consejo adoptará la lista de miembros de conformidad con las propuestas presentadas por cada Estado miembro y su mandato será:","o":["no renovable.","renovable una sola vez.","renovable.","de dos años y medio."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">renovable</mark></span>El <span class=\"ref-norma\">art. 302 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El mandato de los miembros del Comité será renovable\"</span>. Cinco años, renovable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3644","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. El Comité Económico y Social designará de entre sus miembros al Presidente y a la Mesa, por un período de:","o":["dos años.","dos años y medio.","tres años.","cinco años, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">dos años y medio</mark></span>El <span class=\"ref-norma\">art. 303 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Comité designará de entre sus miembros al Presidente y a la Mesa, por un período de dos años y medio\"</span>. Dos años y medio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3647","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. Si lo estimaren necesario, el Parlamento Europeo, el Consejo o la Comisión fijarán al Comité un plazo para la presentación de su dictamen, que no podrá ser inferior a un mes a partir de la fecha de la notificación; transcurrido el plazo fijado sin haberse recibido el dictamen:","o":["se solicitará una prórroga al Comité.","se entenderá emitido en sentido favorable.","podrá prescindirse del mismo.","se suspenderá el procedimiento legislativo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrá prescindirse del mismo</mark></span>El <span class=\"ref-norma\">art. 304 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Transcurrido el plazo fijado sin haberse recibido el dictamen, podrá prescindirse del mismo\"</span>. Plazo mínimo de un mes; sin dictamen puede prescindirse de él. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 14 — Parlamento Europeo EXOF","q":[{"i":"3-54","p":"Tratado de la Unión Europea. ¿Quién determinará la organización interna de la Comisión velando por la coherencia, eficacia y colegialidad de su actuación?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Presidente de la Comisión.","Todos sus miembros tienen esta responsabilidad colegiadamente.","El Alto Representante y el Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 17.6 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El PRESIDENTE DE LA COMISIÓN: a) \u0007definirá las orientaciones con arreglo a las cuales la Comisión desempeñará sus funciones; b) \u0007determinará la organización interna de la Comisión velando por la coherencia, eficacia y colegialidad de su actuación\"</span>. El artículo 17.6.b) del TUE atribuye al Presidente de la Comisión la determinación de la organización interna de la Comisión, velando por la coherencia, eficacia y colegialidad de su actuación."}]},{"a":"Artículos 237 a 243 TFUE — El Consejo · R23 EXOF ✱ R23","q":[{"i":"3-59","p":"Tratado de Funcionamiento de la Unión Europea. El Consejo, establecerá los estatutos de los Comités previstos en los Tratados:","o":["Por mayoría absoluta, previa consulta a la Comisión.","Por mayoría simple, previa consulta al Parlamento Europeo.","Por mayoría simple, previa consulta a la Comisión.","Por mayoría absoluta, previa consulta al Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría simple, previa consulta a la Comisión</mark></span>Según el <span class=\"ref-norma\">art. 242 del TFUE</span>: <span class=\"ref-concepto\">\"El Consejo, por mayoría simple, establecerá, previa consulta a la Comisión, los estatutos de los Comités previstos en los Tratados.\"</span> (verificado con el texto del temario)."},{"i":"3-146","p":"Tratado de Funcionamiento de la Unión Europea. El Consejo. El Consejo, ______ establecerá, previa consulta a la Comisión, los estatutos de los Comités previstos en los Tratados.","o":["Por mayoría absoluta.","Por mayoría cualificada.","Por mayoría simple.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría simple</mark></span>Según el <span class=\"ref-norma\">art. 242 del TFUE</span>: <span class=\"ref-concepto\">\"El Consejo, por mayoría simple, establecerá, previa consulta a la Comisión, los estatutos de los Comités previstos en los Tratados.\"</span> (verificado con el texto del temario)."},{"i":"3-231","p":"Tratado de Funcionamiento de la Unión Europea. ¿Cómo decidirá el Consejo la organización de la Secretaría General?","o":["Por consenso.","Por unanimidad.","Por mayoría simple.","Por mayoría cualificada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría simple</mark></span>Según el <span class=\"ref-norma\">art. 240.2 del TFUE</span>: <span class=\"ref-concepto\">\"El Consejo decidirá por mayoría simple la organización de la Secretaría General.\"</span> (verificado con el texto del temario)."},{"i":"3-365","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo. Cuando el Consejo no actúe a propuesta de la Comisión o del Alto Representante, la mayoría cualificada se definirá, a partir del 1 de noviembre de 2014, como un mínimo del:","o":["72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión.","55 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión.","72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 55 % de la población de la Unión.","65 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 72 % de la población de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión</mark></span>El <span class=\"ref-norma\">art. 238 del TFUE</span> dispone: <span class=\"ref-concepto\">\"cuando el Consejo no actúe a propuesta de la Comisión o del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, la mayoría cualificada se definirá como un mínimo del 72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión\"</span>. Sin propuesta de la Comisión o del Alto Representante: 72 % y 65 %."},{"i":"3-367","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo. Fijará los sueldos, dietas y pensiones del Presidente del Consejo Europeo, del Presidente de la Comisión, del Alto Representante, de los miembros de la Comisión y de los miembros del Tribunal de Justicia:","o":["El Parlamento Europeo.","El Consejo Europeo.","El Consejo.","La Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 243 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo fijará los sueldos, dietas y pensiones del Presidente del Consejo Europeo, del Presidente de la Comisión, del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, de los miembros de la Comisión\"</span>. Los fija el Consejo."},{"i":"3-408","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo. El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste:","o":["De uno de sus miembros o de la Comisión.","Del Consejo Europeo o de la Comisión.","Del Parlamento Europeo o de la Comisión.","De la mayoría de sus miembros o del Alto Representante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De uno de sus miembros o de la Comisión</mark></span>El <span class=\"ref-norma\">art. 237 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión\"</span>. Ficha RECUERDA R23. <em style=\"color:var(--texto-gris)\">(ficha RECUERDA R23 del temario)</em>"},{"i":"3-ia-3513","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de:","o":["la Comisión.","el Parlamento Europeo.","el Consejo Europeo.","el Alto Representante."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Comisión</mark></span>El <span class=\"ref-norma\">art. 237 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a iniciativa de éste, de uno de sus miembros o de la Comisión\"</span>. Convoca el Presidente, a iniciativa propia, de un miembro o de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3514","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. Cuando deba adoptar un acuerdo por mayoría simple, el Consejo se pronunciará:","o":["por mayoría de los votos emitidos.","por mayoría de los miembros presentes.","por la mitad más uno de la población representada.","por mayoría de los miembros que lo componen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por mayoría de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 238.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Cuando deba adoptar un acuerdo por mayoría simple, el Consejo se pronunciará por mayoría de los miembros que lo componen\"</span>. Mayoría de los miembros que lo componen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3516","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. En los casos en que no todos los miembros del Consejo participen en la votación, la mayoría cualificada se definirá como un mínimo del 55 % de los miembros del Consejo que represente a Estados miembros participantes que reúnan como mínimo:","o":["el 72 % de la población de dichos Estados, sin perjuicio de lo dispuesto en otras disposiciones.","el 65 % de la población de dichos Estados.","el 55 % de la población de dichos Estados.","el 62 % de la población de la Unión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el 65 % de la población de dichos Estados</mark></span>El <span class=\"ref-norma\">art. 238.3.a de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La mayoría cualificada se definirá como un mínimo del 55 % de los miembros del Consejo que represente a Estados miembros participantes que reúnan como mínimo el 65 % de la población\"</span>. 55 % de los miembros participantes y 65 % de la población de esos Estados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3517","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. En las votaciones en las que no participan todos los miembros del Consejo, una minoría de bloqueo estará compuesta al menos por el número mínimo de miembros del Consejo que represente más del 35 % de la población de los Estados miembros participantes, más un miembro, a falta de lo cual:","o":["la mayoría cualificada se considerará alcanzada.","la decisión no se considerará adoptada.","se requerirá una nueva votación por unanimidad, en los términos que establezca la propia norma.","se remitirá el asunto al Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la mayoría cualificada se considerará alcanzada</mark></span>El <span class=\"ref-norma\">art. 238.3.a de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"más un miembro, a falta de lo cual la mayoría cualificada se considerará alcanzada\"</span>. Sin minoría de bloqueo se considera alcanzada la mayoría cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3520","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. Un Comité compuesto por Representantes Permanentes de los Gobiernos de los Estados miembros se encargará de preparar los trabajos del Consejo y de realizar las tareas que éste le confíe; el Comité podrá adoptar decisiones de procedimiento:","o":["en los casos que decida el Consejo por unanimidad.","en los casos establecidos por el reglamento interno del Consejo.","en los casos que determine la Presidencia del Consejo, sin perjuicio de lo dispuesto en otras disposiciones.","en los casos previstos por el Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los casos establecidos por el reglamento interno del Consejo</mark></span>El <span class=\"ref-norma\">art. 240.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Comité podrá adoptar decisiones de procedimiento en los casos establecidos por el reglamento interno del Consejo\"</span>. Solo en los casos previstos en el reglamento interno del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3521","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Consejo; el Consejo decidirá la organización de la Secretaría General:","o":["por mayoría simple.","por mayoría cualificada.","por unanimidad.","por mayoría de dos tercios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por mayoría simple</mark></span>El <span class=\"ref-norma\">art. 240.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo decidirá por mayoría simple la organización de la Secretaría General\"</span>. La organización se decide por mayoría simple. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3523","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. El Consejo, por mayoría simple, establecerá, previa consulta a la Comisión, los estatutos de:","o":["las agencias previstas en los Tratados.","los tribunales especializados previstos en los Tratados.","los Comités previstos en los Tratados.","los órganos consultivos previstos en los Tratados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Comités previstos en los Tratados</mark></span>El <span class=\"ref-norma\">art. 242 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"establecerá, previa consulta a la Comisión, los estatutos de los Comités previstos en los Tratados\"</span>. Estatutos de los Comités previstos en los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3524","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. El Consejo fijará los sueldos, dietas y pensiones del Presidente del Consejo Europeo, del Presidente de la Comisión, del Alto Representante, de los miembros de la Comisión, de los Presidentes, miembros y secretarios del Tribunal de Justicia de la Unión Europea y:","o":["del Defensor del Pueblo Europeo.","del Secretario General del Consejo.","del Presidente del Parlamento Europeo.","del Gobernador del Banco Central Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">del Secretario General del Consejo</mark></span>El <span class=\"ref-norma\">art. 243 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"del Tribunal de Justicia de la Unión Europea y del Secretario General del Consejo\"</span>. Incluye al Secretario General del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 87 a 89 TFUE — Cooperación policial y Europol · R20 EXOF ✱ R20","q":[{"i":"3-61","p":"Tratado de Funcionamiento de la Unión Europea. La Unión desarrollará una cooperación policial en la que participan todas las autoridades competentes de los Estados miembros, incluidos:","o":["Los servicios de policía.","Los servicios de aduanas.","Otros servicios con funciones coercitivas especializados en la prevención y en la detección e investigación de infracciones penales.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 87.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una cooperación policial en la que participen todas las autoridades competentes de los Estados miembros, incluidos los servicios de policía, los servicios de aduanas y otros servicios con funciones coercitivas especializados en la prevención y en la detección e investigación de infracciones penales\"</span>. El artículo 87.1 del TFUE establece que la cooperación policial de la Unión incluye a todas las autoridades competentes de los Estados miembros, entre ellas los servicios de policía, los servicios de aduanas y otros servicios con funciones coercitivas especializados en la prevención, detección e investigación de infracciones penales."},{"i":"3-113","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. Cualquier actividad operativa de Europol deberá llevarse a cabo en contacto y de acuerdo con:","o":["Interpol.","Las autoridades de los Estados miembros cuyo territorio resulte afectado.","Eurojust.","La Fiscalía Europea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las autoridades de los Estados miembros cuyo territorio resulte afectado</mark></span>El <span class=\"ref-norma\">art. 88.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Cualquier actividad operativa de Europol deberá llevarse a cabo en contacto y de acuerdo con las autoridades de los Estados miembros cuyo territorio resulte afectado. La aplicación de medidas coercitivas corresponderá exclusivamente a las autoridades nacionales competentes\"</span>. El artículo 88.3 del TFUE establece que cualquier actividad operativa de Europol deberá llevarse a cabo en contacto y de acuerdo con las autoridades de los Estados miembros cuyo territorio resulte afectado."},{"i":"3-179","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Cooperación policial. Respecto a la actividad operativa de Europol, ¿a quién corresponderá la aplicación de las medidas coercitivas?","o":["La Ejecutarán por Europol, no realizando conjuntamente con las autoridades nacionales competentes.","A las autoridades nacionales competentes.","Exclusivamente a las autoridades policiales competentes.","A y B son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">A las autoridades nacionales competentes</mark></span>El <span class=\"ref-norma\">art. 88.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Cualquier actividad operativa de Europol deberá llevarse a cabo en contacto y de acuerdo con las autoridades de los Estados miembros cuyo territorio resulte afectado. La aplicación de medidas coercitivas corresponderá exclusivamente a las autoridades nacionales competentes\"</span>. El artículo 88.3 del TFUE establece que la aplicación de medidas coercitivas en las actividades operativas de Europol corresponderá exclusivamente a las autoridades nacionales competentes."},{"i":"3-301","p":"Tratado de Funcionamiento de la Unión Europea. La Unión desarrollará una cooperación policial en la que participan todas las autoridades competentes de los Estados miembros, incluidos:","o":["Los servicios de policía.","Los servicios de aduanas.","Otros servicios con funciones coercitivas especializados en la prevención y en la detección e investigación de infracciones penales.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 87.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una cooperación policial en la que participen todas las autoridades competentes de los Estados miembros, incluidos los servicios de policía, los servicios de aduanas y otros servicios con funciones coercitivas especializados en la prevención y en la detección e investigación de infracciones penales\"</span>. El artículo 87.1 TFUE incluye entre las autoridades competentes a los servicios de policía, de aduanas y otros servicios con funciones coercitivas especializados."},{"i":"3-359","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Cooperación policial. El Consejo fijará, con arreglo a un procedimiento legislativo especial, las condiciones y límites dentro de los cuales las autoridades competentes de los Estados miembros podrán actuar en el territorio de otro Estado miembro en contacto y de acuerdo con las autoridades de dicho Estado. El Consejo se pronunciará:","o":["Por mayoría cualificada, previa aprobación del Parlamento Europeo.","Por unanimidad, previa aprobación del Parlamento Europeo.","Por unanimidad, previa consulta al Parlamento Europeo.","Por mayoría simple, previa consulta a la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por unanimidad, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 89 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad, previa consulta al Parlamento Europeo\"</span>. Unanimidad y consulta al Parlamento Europeo."},{"i":"3-ia-3423","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. La Unión desarrollará una cooperación policial en la que participen todas las autoridades competentes de los Estados miembros, incluidos los servicios de policía, los servicios de aduanas y otros servicios con funciones coercitivas especializados en:","o":["la protección de las fronteras y en la lucha contra la inmigración irregular.","el mantenimiento del orden público y en la seguridad ciudadana.","la prevención y en la detección e investigación de infracciones penales.","la persecución del terrorismo y de la delincuencia organizada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la prevención y en la detección e investigación de infracciones penales</mark></span>El <span class=\"ref-norma\">art. 87.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"servicios con funciones coercitivas especializados en la prevención y en la detección e investigación de infrac\"</span>. Prevención, detección e investigación de infracciones penales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3424","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. El Parlamento Europeo y el Consejo podrán adoptar, con arreglo al procedimiento legislativo ordinario, medidas relativas a la recogida, almacenamiento, tratamiento, análisis e intercambio de información pertinente, al apoyo a la formación de personal y a la cooperación para el intercambio de personal, los equipos y la investigación científica policial, y a:","o":["las técnicas comunes de intervención policial en situaciones de crisis transfronteriza.","las técnicas comunes de investigación relacionadas con la detección de formas graves de delincuencia organizada.","los protocolos comunes de actuación policial en grandes acontecimientos internacionales.","las técnicas comunes de control de las fronteras exteriores en situaciones de emergencia, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las técnicas comunes de investigación relacionadas con la detección de formas graves de delincuencia organizada</mark></span>El <span class=\"ref-norma\">art. 87.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"las técnicas comunes de investigación relacionadas con la detección de formas graves de delin\"</span>. Tercera medida: técnicas comunes de investigación de formas graves de delincuencia organizada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3425","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. El Consejo podrá establecer, con arreglo a un procedimiento legislativo especial, medidas relativas a la cooperación operativa entre las autoridades policiales y similares; se pronunciará:","o":["por unanimidad, previa consulta al Parlamento Europeo.","por mayoría cualificada, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, previa aprobación del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por unanimidad, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 87.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad, previa consulta al Parlamento Europeo\"</span>. Cooperación operativa: procedimiento especial, unanimidad y consulta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3426","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación policial. El procedimiento específico del freno de emergencia y de cooperación reforzada previsto para las medidas de cooperación operativa policial no será de aplicación:","o":["a las medidas que afecten a la cooperación con Europol.","a las medidas relativas a las técnicas comunes de investigación.","a las medidas adoptadas con la participación de los Parlamentos nacionales.","a los actos que constituyan un desarrollo del acervo de Schengen."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a los actos que constituyan un desarrollo del acervo de Schengen</mark></span>El <span class=\"ref-norma\">art. 87.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no será de aplicación a los actos que constituyan un desarrollo del acervo de Schengen\"</span>. Quedan excluidos los actos de desarrollo del acervo de Schengen. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3427","p":"Tratado de Funcionamiento de la Unión Europea. Europol. La función de Europol es apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de:","o":["las formas de delincuencia organizada que operen en el territorio de los Estados miembros, así como en su persecución penal, conforme al procedimiento que se establezca reglamentariamente.","los delitos contra los intereses financieros de la Unión, así como en la lucha en contra de ellos.","las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos.","la delincuencia transfronteriza de carácter económico o informático, así como en su investigación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos</mark></span>El <span class=\"ref-norma\">art. 88.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos\"</span>. Delincuencia grave de dos o más Estados, terrorismo y formas de delincuencia que lesionen un interés común objeto de una política de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3428","p":"Tratado de Funcionamiento de la Unión Europea. Europol. El Parlamento Europeo y el Consejo determinarán, mediante reglamentos adoptados con arreglo al procedimiento legislativo ordinario, la estructura, el funcionamiento, el ámbito de actuación y las competencias de Europol; en dichos reglamentos se fijará asimismo el procedimiento de control de las actividades de Europol por el Parlamento Europeo, control en el que participarán:","o":["los Gobiernos de los Estados miembros.","los Parlamentos nacionales.","las autoridades de protección de datos.","los Ministros de Interior de los Estados miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los Parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 88.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"control de las actividades de Europol por el Parlamento Europeo, control en el que participarán los Parlamentos nacionales\"</span>. El control parlamentario lo hace el Parlamento Europeo con los Parlamentos nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3429","p":"Tratado de Funcionamiento de la Unión Europea. Europol. Cualquier actividad operativa de Europol deberá llevarse a cabo en contacto y de acuerdo con las autoridades de los Estados miembros cuyo territorio resulte afectado; la aplicación de medidas coercitivas corresponderá:","o":["exclusivamente a las autoridades nacionales competentes.","a Europol, de acuerdo con las autoridades nacionales.","a Europol, previa autorización de un juez nacional.","a la Fiscalía Europea, en el ámbito de sus competencias, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">exclusivamente a las autoridades nacionales competentes</mark></span>El <span class=\"ref-norma\">art. 88.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La aplicación de medidas coercitivas corresponderá exclusivamente a las autoridades nacionales competentes\"</span>. Europol carece de poderes coercitivos propios. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3430","p":"Tratado de Funcionamiento de la Unión Europea. Actuación en territorio de otro Estado miembro. El Consejo fijará, con arreglo a un procedimiento legislativo especial, las condiciones y límites dentro de los cuales las autoridades competentes de los Estados miembros podrán actuar en el territorio de otro Estado miembro en contacto y de acuerdo con las autoridades de dicho Estado, pronunciándose:","o":["por mayoría cualificada, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, previa aprobación del Parlamento Europeo.","por unanimidad, previa consulta al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por unanimidad, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 89 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad, previa consulta al Parlamento Europeo\"</span>. Procedimiento legislativo especial: unanimidad y consulta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 223 a 225 TFUE — Elección, estatuto y partidos · R21 ✱ R21","q":[{"i":"3-64","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones Institucionales. El Consejo establecerá las disposiciones necesarias por ___________ con arreglo a un procedimiento legislativo especial, previa aprobación del Parlamento Europeo, que se pronunciará por mayoría de los miembros que lo componen. Dichas disposiciones entrarán en vigor una vez que hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales.","o":["Mayoría simple.","Mayoría de dos tercios.","Unanimidad.","Mayoría absoluta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Unanimidad</mark></span>El <span class=\"ref-norma\">art. 223.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo establecerá las disposiciones necesarias por unanimidad con arreglo a un procedimiento legislativo especial, previa aprobación del Parlamento Europeo, que se pronunciará por mayoría de los miembros que lo componen. Dichas disposiciones entrarán en vigor una vez que hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales\"</span>. El artículo 223.1 del TFUE dispone que el Consejo establecerá por unanimidad, con arreglo a un procedimiento legislativo especial y previa aprobación del Parlamento Europeo, las disposiciones necesarias para la elección de los diputados por sufragio universal directo."},{"i":"3-204","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién podrá crear tribunales especializados adjuntos al Tribunal General, encargados de conocer en primera instancia de determinadas categorías de recursos interpuestos en materias específicas?","o":["El Parlamento Europeo, con arreglo al procedimiento legislativo especial.","El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario.","El Consejo, con arreglo al procedimiento legislativo especial.","La Comisión, con arreglo al procedimiento legislativo ordinario."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario</mark></span>Según el <span class=\"ref-norma\">art. 257 del TFUE</span>: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, podrán crear tribunales especializados adjuntos al Tribunal General...\"</span> (verificado con el texto del temario)."},{"i":"3-304","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones Institucionales. El Consejo establecerá las disposiciones necesarias para la elección de los miembros del Parlamento Europeo por sufragio universal directo, por ___________, con arreglo a un procedimiento legislativo especial, previa aprobación del Parlamento Europeo, que se pronunciará por mayoría de los miembros que lo componen. Dichas disposiciones entrarán en vigor una vez que hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales.","o":["Mayoría simple.","Mayoría de dos tercios.","Unanimidad.","Mayoría absoluta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Unanimidad</mark></span>El <span class=\"ref-norma\">art. 223.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo establecerá las disposiciones necesarias por unanimidad con arreglo a un procedimiento legislativo especial, previa aprobación del Parlamento Europeo, que se pronunciará por mayoría de los miembros que lo componen. Dichas disposiciones entrarán en vigor una vez que hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales\"</span>. El artículo 223.1 TFUE exige que el Consejo se pronuncie por unanimidad en este procedimiento."},{"i":"3-361","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Parlamento Europeo. Por decisión de la mayoría de los miembros que lo componen, el Parlamento Europeo podrá solicitar a la Comisión que presente las propuestas oportunas sobre cualquier asunto que requiera la elaboración de un acto de la Unión. Si la Comisión no presenta propuesta alguna, comunicará las razones:","o":["Al Parlamento Europeo.","Al Consejo.","Al Consejo Europeo.","Al Tribunal de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 225 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Si la Comisión no presenta propuesta alguna, comunicará las razones al Parlamento Europeo\"</span>. Debe comunicar las razones al Parlamento Europeo."},{"i":"3-407","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Parlamento Europeo. El Parlamento Europeo establecerá mediante reglamentos adoptados por propia iniciativa, con arreglo a un procedimiento legislativo especial, el estatuto y las condiciones generales de ejercicio de las funciones de sus miembros:","o":["Previo dictamen del Consejo y con la aprobación de la Comisión.","Previo dictamen de la Comisión y con la aprobación del Consejo.","Previo dictamen de la Comisión y con la aprobación del Consejo Europeo.","Previa consulta al Tribunal de Justicia y con la aprobación del Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Previo dictamen de la Comisión y con la aprobación del Consejo</mark></span>El <span class=\"ref-norma\">art. 223.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el estatuto y las condiciones generales de ejercicio de las funciones de sus miembros, previo dictamen de la Comisión y con la aprobación del Consejo\"</span>. Ficha RECUERDA R21. <em style=\"color:var(--texto-gris)\">(ficha RECUERDA R21 del temario)</em>"},{"i":"3-ia-3431","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo elaborará un proyecto encaminado a establecer las disposiciones necesarias para hacer posible la elección de sus miembros por sufragio universal directo, de acuerdo con un procedimiento uniforme en todos los Estados miembros o de acuerdo con principios comunes; el Consejo establecerá las disposiciones por unanimidad, con arreglo a un procedimiento legislativo especial, previa aprobación del Parlamento Europeo, que se pronunciará:","o":["por mayoría de los votos emitidos.","por mayoría de dos tercios de los votos emitidos.","por mayoría de los miembros que lo componen.","por unanimidad de los miembros presentes."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por mayoría de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 223.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"previa aprobación del Parlamento Europeo, que se pronunciará por mayoría de los miembros que lo componen\"</span>. Aprobación por mayoría de los miembros que lo componen; después, aprobación de los Estados miembros según sus normas constitucionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3432","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo establecerá mediante reglamentos adoptados por propia iniciativa, con arreglo a un procedimiento legislativo especial, el estatuto y las condiciones generales de ejercicio de las funciones de sus miembros, previo dictamen de la Comisión y con la aprobación del Consejo; toda norma o condición relativas al régimen fiscal de los miembros o de los antiguos miembros se decidirán en el Consejo:","o":["por mayoría cualificada.","por unanimidad.","por mayoría simple.","por mayoría de dos tercios."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad</mark></span>El <span class=\"ref-norma\">art. 223.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Toda norma o condición relativas al régimen fiscal de los miembros o de los antiguos miembros se decidirán en el Consejo por unanimidad\"</span>. El régimen fiscal de los eurodiputados exige unanimidad del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3434","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. Por decisión de la mayoría de los miembros que lo componen, el Parlamento Europeo podrá solicitar a la Comisión que presente las propuestas oportunas sobre cualquier asunto que a su juicio requiera la elaboración de un acto de la Unión; si la Comisión no presenta propuesta alguna:","o":["someterá el asunto al Consejo para su decisión.","presentará un informe al Consejo Europeo.","estará obligada a presentar la propuesta en seis meses.","comunicará las razones al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comunicará las razones al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 225 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Si la Comisión no presenta propuesta alguna, comunicará las razones al Parlamento Europeo\"</span>. Es una iniciativa legislativa indirecta: la Comisión no está obligada, pero debe motivar su negativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3436","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. La existencia de la comisión temporal de investigación terminará con la presentación de su informe; el Parlamento Europeo determinará las modalidades de ejercicio del derecho de investigación mediante reglamentos adoptados por propia iniciativa, con arreglo a un procedimiento legislativo especial:","o":["previa consulta al Consejo y a la Comisión, sin perjuicio de lo dispuesto en otras disposiciones.","previa aprobación del Consejo y de la Comisión.","previa aprobación del Consejo Europeo.","previo dictamen del Tribunal de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">previa aprobación del Consejo y de la Comisión</mark></span>El <span class=\"ref-norma\">art. 226 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"previa aprobación del Consejo y de la Comisión\"</span>. Hace falta la aprobación del Consejo y de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3443","p":"Tratado de Funcionamiento de la Unión Europea. Defensor del Pueblo Europeo. El Parlamento Europeo fijará, mediante reglamentos adoptados por propia iniciativa, con arreglo a un procedimiento legislativo especial, el Estatuto y las condiciones generales de ejercicio de las funciones del Defensor del Pueblo, previo dictamen de la Comisión y:","o":["con la consulta del Consejo.","con la aprobación del Consejo Europeo.","con la aprobación del Consejo.","con la consulta del Tribunal de Justicia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">con la aprobación del Consejo</mark></span>El <span class=\"ref-norma\">art. 228.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"previo dictamen de la Comisión y con la aprobación del Consejo\"</span>. Dictamen de la Comisión y aprobación del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3522","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. El Consejo, por mayoría simple, podrá pedir a la Comisión que proceda a efectuar todos los estudios que él considere oportunos para la consecución de los objetivos comunes y que le someta las propuestas pertinentes; si la Comisión no presenta propuesta alguna:","o":["someterá el asunto al Parlamento Europeo.","deberá presentarla en el plazo de seis meses.","dará cuenta al Consejo Europeo.","comunicará las razones al Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comunicará las razones al Consejo</mark></span>El <span class=\"ref-norma\">art. 241 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Si la Comisión no presenta propuesta alguna, comunicará las razones al Consejo\"</span>. Comunica las razones al Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Riesgo y violación de los valores del art. 2 EXOF","q":[{"i":"3-67","p":"Tratado de la Unión Europea. A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de ___________ de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores contemplados en el artículo 2.","o":["Cuatro quintos.","Tres quintos.","Dos tercios.","Un quinto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuatro quintos</mark></span>Según el <span class=\"ref-norma\">art. 7.1 del TUE</span>: <span class=\"ref-concepto\">\"A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar la existencia de un riesgo claro de violación grave...\"</span> (verificado con el texto del temario)."},{"i":"3-95","p":"Tratado de la Unión Europea. El Consejo Europeo, por __________ y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el artículo 2 tras invitar al Estado miembro de que se trate a que presente sus observaciones. Rellene el hueco.","o":["Mayoría absoluta","Mayoría Cualificada","Unanimidad.","Mayoría de tres quintos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Unanimidad</mark></span>El <span class=\"ref-norma\">art. 7.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el artículo 2 tras invitar al Estado miembro de que se trate a que presente sus observaciones\"</span>. El artículo 7.2 del TUE exige que el Consejo Europeo se pronuncie por unanimidad, a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, para constatar la existencia de una violación grave y persistente de los valores del artículo 2."},{"i":"3-169","p":"La constatación de la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores contemplados en el artículo 2 del Tratado de la Unión Europea, se llevará a cabo:","o":["A propuesta motivada de dos tercios de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo.","A propuesta motivada de la mitad de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo.","A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de tres quintos de sus miembros y previa aprobación del Parlamento Europeo.","A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 7.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores contemplados en el artículo 2\"</span>. El artículo 7.1 del TUE dispone que, a propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar el riesgo claro de violación grave de los valores del artículo 2."},{"i":"3-176","p":"Tratado de Funcionamiento de la Unión Europea. Procedimientos para casos de riesgo de violación de valores de la Unión Europea.","o":["El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados Miembros o del Parlamento Europeo y previa aprobación de la Comisión, podrá constatar la existencia de una violación grave y persistente por parte de un Estado Miembro de los valores contemplados.","El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados Miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado Miembro de los valores contemplados.","El Consejo de Europa, por unanimidad y a propuesta de un tercio de los Estados Miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación muy grave y persistente por parte de un Estado Miembro de los valores contemplados.","El Parlamento, por unanimidad y a propuesta de un tercio de los Estados Miembros o de la Comisión Europea y previa aprobación del Consejo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado Miembro de los valores contemplados."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados Miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado Miembro de los valores contemplados</mark></span>El <span class=\"ref-norma\">art. 7.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"EL CONSEJO EUROPEO POR UNANIMIDAD Constatar la existencia de una violación grave y persistente por parte de un estado miembro de los valores contemplados en el artículo 2. A PROPUESTA DE 1/3 DE LOS ESTADOS MIEMBROS O DE LA COMISIÓN PREVIA APROBACIÓN DEL PARLAMENTO EUROPEO\"</span>. El artículo 7.2 del TUE establece que el Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión, y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente de los valores del artículo 2."},{"i":"3-207","p":"Tratado de la Unión Europea. Cuando se haya constatado la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el Tratado de la Unión Europea, ¿cómo se podrá decidir que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro de que se trate?","o":["Por mayoría de cuatro quintos de sus miembros.","Por mayoría cualificada.","Por unanimidad.","Por mayoría de tres cuartas partes de sus miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por mayoría cualificada</mark></span>El <span class=\"ref-norma\">art. 7.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo podrá decidir, por mayoría cualificada, que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro de que se trate\"</span>. El artículo 7.3 del TUE establece que, constatada la violación grave y persistente, el Consejo podrá decidir, por mayoría cualificada, que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro de que se trate, incluidos los derechos de voto de su representante en el Consejo."},{"i":"3-211","p":"Tratado de Funcionamiento de la Unión Europea. El Consejo. Señale la INCORRECTA.","o":["El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión.","El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Parlamento Europeo.","El Consejo, por mayoría simple, podrá pedir a la Comisión que proceda a efectuar todos los estudios que él considere oportunos para la consecución de los objetivos comunes y que le someta las propuestas pertinentes.","Un Comité compuesto por Representantes Permanentes de los Gobiernos de los Estados miembros se encargará de preparar los trabajos del Consejo y de realizar las tareas que éste le confíe."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 240.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Consejo. \u0007El Consejo decidirá por mayoría simple la organización de la Secretaría General\"</span>. (The Secretary-General is appointed by the Council, not the Parliament.)"},{"i":"3-215","p":"Tratado de la Unión Europea. ¿Quién podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el Tratado de la Unión Europea tras invitar al Estado miembro de que se trate a que presente sus observaciones?","o":["La Comisión.","El Parlamento Europeo.","El Consejo Europeo.","El Consejo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 7.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el artículo 2 tras invitar al Estado miembro de que se trate a que presente sus observaciones\"</span>. El artículo 7.2 del TUE atribuye al Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión, previa aprobación del Parlamento Europeo, la constatación de una violación grave y persistente de los valores del artículo 2, tras invitar al Estado miembro a presentar sus observaciones."},{"i":"3-261","p":"(TUE) Tratado de la Unión Europea. ¿Quién podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el Tratado de la Unión Europea tras invitar al Estado miembro de que se trate a que presente sus observaciones?","o":["La Comisión.","El Parlamento Europeo.","El Consejo Europeo.","El Consejo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 7.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el artículo 2 tras invitar al Estado miembro de que se trate a que presente sus observaciones\"</span>. El artículo 7.2 del TUE atribuye al Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión, previa aprobación del Parlamento Europeo, la constatación de una violación grave y persistente de los valores del artículo 2, tras invitar al Estado miembro a presentar sus observaciones."},{"i":"3-307","p":"Tratado de la Unión Europea. A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de ___________ de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores contemplados en el artículo 2.","o":["Cuatro quintos.","Tres quintos.","Dos tercios.","Un quinto."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuatro quintos</mark></span>El <span class=\"ref-norma\">art. 7.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores contemplados en el artículo 2\"</span>. El artículo 7.1 TUE exige una mayoría de cuatro quintos de los miembros del Consejo para constatar el riesgo claro de violación grave."},{"i":"3-322","p":"Tratado de la Unión Europea. Cuando se haya constatado la existencia de una violación grave y persistente por parte de un Estado miembro de los valores contemplados en el Tratado de la Unión Europea, ¿cómo se podrá decidir que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro de que se trate?","o":["Por mayoría de cuatro quintos de sus miembros.","Por mayoría cualificada.","Por unanimidad.","Por mayoría de tres cuartas partes de sus miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por mayoría cualificada</mark></span>El <span class=\"ref-norma\">art. 7.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo podrá decidir, por mayoría cualificada, que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro de que se trate\"</span>. El artículo 7.3 TUE dispone que la suspensión de derechos se decidirá por mayoría cualificada."},{"i":"3-326","p":"Tratado de Funcionamiento de la Unión Europea. El Consejo. Señale la INCORRECTA.","o":["El Consejo se reunirá por convocatoria de su Presidente, a iniciativa de éste, de uno de sus miembros o de la Comisión.","El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Parlamento Europeo.","El Consejo, por mayoría simple, podrá pedir a la Comisión que proceda a efectuar todos los estudios que él considere oportunos para la consecución de los objetivos comunes y que le someta las propuestas pertinentes.","Un Comité compuesto por Representantes Permanentes de los Gobiernos de los Estados miembros se encargará de preparar los trabajos del Consejo y de realizar las tareas que éste le confíe."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 240.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo estará asistido por una Secretaría General, que estará bajo la responsabilidad de un Secretario General nombrado por el Consejo. \u0007El Consejo decidirá por mayoría simple la organización de la Secretaría General\"</span>. El artículo 240.2 TFUE atribuye al propio Consejo el nombramiento del Secretario General de la Secretaría General."},{"i":"3-345","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Servicios. Los Estados miembros se esforzarán por proceder a una liberalización de los servicios más amplia que la exigida en virtud de las directivas, si su situación económica general y la del sector afectado se lo permiten. La Comisión dirigirá, a este fin:","o":["Recomendaciones a los Estados miembros interesados.","Directivas vinculantes a los Estados miembros interesados.","Dictámenes motivados a todos los Estados miembros de la Unión.","Reglamentos de aplicación directa a todos los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Recomendaciones a los Estados miembros interesados</mark></span>El <span class=\"ref-norma\">art. 60 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La Comisión dirigirá, a este fin, recomendaciones a los Estados miembros interesados\"</span>. La Comisión solo dirige recomendaciones."},{"i":"3-ia-3030","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. A propuesta motivada de un tercio de los Estados miembros, del Parlamento Europeo o de la Comisión, el Consejo, por mayoría de cuatro quintos de sus miembros y previa aprobación del Parlamento Europeo, podrá constatar:","o":["la existencia de una violación grave y persistente por parte de un Estado miembro de los valores de la Unión, salvo que se disponga otra cosa en la normativa aplicable.","la existencia de un riesgo de incumplimiento de las obligaciones por parte de un Estado miembro.","la existencia de un riesgo claro de violación persistente de los derechos fundamentales.","la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la existencia de un riesgo claro de violación grave por parte de un Estado miembro de los valores de la Unión</mark></span>El <span class=\"ref-norma\">art. 7.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá constatar la existencia de un riesgo claro de violación grave por parte de un\"</span>. El apartado 1 se refiere al riesgo claro de violación grave; el apartado 2 a la violación grave y persistente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3031","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. Antes de proceder a la constatación del riesgo claro de violación grave de los valores de la Unión, el Consejo oirá al Estado miembro de que se trate y:","o":["por unanimidad podrá imponerle medidas provisionales.","por mayoría cualificada podrá suspender sus derechos de voto.","por el mismo procedimiento podrá dirigirle recomendaciones.","previa aprobación de la Comisión podrá dirigirle advertencias."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por el mismo procedimiento podrá dirigirle recomendaciones</mark></span>El <span class=\"ref-norma\">art. 7.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Consejo oirá al Estado miembro de que se trate y por el mismo procedimiento podrá dirigir\"</span>. Tras oír al Estado, el Consejo puede dirigirle recomendaciones por el mismo procedimiento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3032","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. El Consejo Europeo, por unanimidad y a propuesta de un tercio de los Estados miembros o de la Comisión y previa aprobación del Parlamento Europeo, podrá constatar la existencia de una violación grave y persistente por parte de un Estado miembro de los valores de la Unión tras:","o":["oír al Estado miembro de que se trate y dirigirle recomendaciones.","invitar al Estado miembro de que se trate a que presente sus observaciones.","recabar el dictamen del Tribunal de Justicia de la Unión Europea.","consultar al Consejo y al Parlamento Europeo sobre las medidas oportunas, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">invitar al Estado miembro de que se trate a que presente sus observaciones</mark></span>El <span class=\"ref-norma\">art. 7.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"tras invitar al Estado miembro de que se trate a que presente sus observaciones\"</span>. Debe invitar al Estado a presentar sus observaciones; la propuesta puede venir de un tercio de Estados o de la Comisión, no del Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3033","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. Cuando se haya efectuado la constatación de una violación grave y persistente, el Consejo podrá decidir, por mayoría cualificada, que se suspendan determinados derechos derivados de la aplicación de los Tratados al Estado miembro, incluidos:","o":["los derechos de voto del representante del Gobierno de dicho Estado miembro en el Consejo.","los derechos de participación del Estado miembro en las reuniones del Consejo Europeo, en los términos que establezca la propia norma.","los derechos de acceso del Estado miembro a los fondos de cohesión y estructurales.","los derechos de representación del Estado miembro en el Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">los derechos de voto del representante del Gobierno de dicho Estado miembro en el Consejo</mark></span>El <span class=\"ref-norma\">art. 7.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"incluidos los derechos de voto del representante del Go\"</span>. La suspensión puede alcanzar los derechos de voto del representante del Gobierno en el Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3034","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. Al proceder a la suspensión de derechos de un Estado miembro, el Consejo tendrá en cuenta las posibles consecuencias de la misma para los derechos y obligaciones de las personas físicas y jurídicas; las obligaciones del Estado miembro derivadas de los Tratados:","o":["quedarán suspendidas mientras dure la suspensión de sus derechos, salvo que se disponga otra cosa en la normativa aplicable.","serán revisadas por el Consejo Europeo al término de cada año.","podrán ser suspendidas por decisión unánime del Consejo.","continuarán, en cualquier caso, siendo vinculantes para dicho Estado."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">continuarán, en cualquier caso, siendo vinculantes para dicho Estado</mark></span>El <span class=\"ref-norma\">art. 7.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Las obligaciones del Estado miembro de que se trate derivadas de los Tratados continuarán, en cualquier caso, siendo vinculantes para dicho Estado\"</span>. La suspensión afecta a derechos, no a las obligaciones, que siguen siendo vinculantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3035","p":"Tratado de la Unión Europea. Procedimiento para casos de riesgo de violación de valores. El Consejo podrá decidir posteriormente, por mayoría cualificada, la modificación o revocación de las medidas adoptadas como respuesta a cambios en la situación que motivó su imposición; las modalidades de voto aplicables a estos efectos se establecen:","o":["en el Reglamento interno del Consejo.","en el propio Tratado de la Unión Europea, conforme al procedimiento que se establezca reglamentariamente.","en el Tratado de Funcionamiento de la Unión Europea.","en un Protocolo anexo a los Tratados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el Tratado de Funcionamiento de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 7.4 y 5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se establecen en el artículo 354 del Tratado de Funciona\"</span>. Las modalidades de voto se regulan en el artículo 354 del TFUE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3122","p":"Tratado de la Unión Europea. La Comisión. El Consejo, de común acuerdo con el Presidente electo, adoptará la lista de las demás personalidades que se proponga nombrar miembros de la Comisión, seleccionadas a partir de las propuestas presentadas por:","o":["el Parlamento Europeo.","el Consejo Europeo.","las instituciones de la Unión.","los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 17.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a partir de las propuestas presentadas por los Estados miembros\"</span>. Las propuestas las presentan los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3234","p":"Tratado de la Unión Europea. Agencia Europea de Defensa. Podrán participar en la Agencia Europea de Defensa todos los Estados miembros que lo deseen; el Consejo adoptará por mayoría cualificada una decisión en la que se determinará el estatuto, la sede y la forma de funcionamiento de la Agencia, y ésta desempeñará sus funciones manteniéndose, en caso necesario, en contacto:","o":["con el Parlamento Europeo.","con el Consejo Europeo.","con el Alto Representante.","con la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">con la Comisión</mark></span>El <span class=\"ref-norma\">art. 45.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Agencia desempeñará sus funciones manteniéndose, en caso necesario, en contacto con la Comisión\"</span>. Se mantiene en contacto con la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3250","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. Las instituciones velarán, asimismo, por asegurarse de que las condiciones para el establecimiento no resultan falseadas mediante:","o":["subvenciones concedidas por las instituciones.","prácticas restrictivas de las empresas.","medidas fiscales de los Estados miembros.","ayudas otorgadas por los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">ayudas otorgadas por los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 50.2.h de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"asegurándose de que las condiciones para el establecimiento no resultan falseadas mediante ayudas otorgadas por los Estados miembros\"</span>. No deben falsearse mediante ayudas otorgadas por los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3527","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Los miembros de la Comisión se abstendrán de todo acto incompatible con el carácter de sus funciones y no podrán, mientras dure su mandato, ejercer ninguna otra actividad profesional; en caso de incumplimiento de sus obligaciones, el Tribunal de Justicia, a instancia del Consejo, por mayoría simple, o de la Comisión, podrá declarar su cese o:","o":["la imposición de una multa equivalente a su retribución anual.","la inhabilitación para ejercer cargos públicos en la Unión.","la privación del derecho del interesado a la pensión o de cualquier otro beneficio sustitutivo.","la devolución de las retribuciones percibidas durante el mandato, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la privación del derecho del interesado a la pensión o de cualquier otro beneficio sustitutivo</mark></span>El <span class=\"ref-norma\">art. 245 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"o la privación del derecho del interesado a la pensión o de cualquier otro beneficio sustitutivo\"</span>. El Tribunal puede declarar el cese o la privación de la pensión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 56 a 62 TFUE — Servicios · R16 EXOF ✱ R16","q":[{"i":"3-84","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. Los servicios comprenderán, en particular: Señale la incorrecta.","o":["Actividades de carácter industrial.","Actividades de carácter mercantil.","Actividades propias de los profesores liberales.","Actividades artesanales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Actividades propias de los profesores liberales</mark></span>Son profesiones LIBERALES, no «profesores liberales». Según el <span class=\"ref-norma\">art. 57 del TFUE</span>: <span class=\"ref-concepto\">\"Los servicios comprenderán, en particular: a) actividades de carácter industrial; b) actividades de carácter mercantil; c) actividades artesanales; d) actividades propias de las profesiones liberales.\"</span> (verificado con el texto del temario)."},{"i":"3-122","p":"Tratado de Funcionamiento de la Unión Europea. A efectos de alcanzar la liberalización de un servicio determinado, el Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, decidirán:","o":["Mediante Directivas.","Mediante Reglamentos.","Mediante Recomendaciones.","A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mediante Directivas</mark></span>El <span class=\"ref-norma\">art. 59.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A efectos de alcanzar la liberalización de un servicio determinado, el Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, decidirán mediante directivas\"</span>. El artículo 59.1 del TFUE establece que, a efectos de alcanzar la liberalización de un servicio determinado, el Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social, decidirán mediante directivas."},{"i":"3-142","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. En el marco de las disposiciones siguientes, ______ la libre prestación de servicios dentro de la Unión para los nacionales de los Estados miembros establecidos en un Estado miembro que no sea el del destinatario de la prestación:","o":["Quedarán prohibidas las restricciones a.","Podrá ser sometida a restricciones.","Solo en ciertos ámbitos podrá ser sometida a restricciones.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Quedarán prohibidas las restricciones a</mark></span>El <span class=\"ref-norma\">art. 56 del TFUE</span> dispone: <span class=\"ref-concepto\">\"En el marco de las disposiciones siguientes, quedarán prohibidas las restricciones a la libre prestación de servicios dentro de la Unión para los nacionales de los Estados miembros establecidos en un Estado miembro que no sea el del destinatario de la prestación\"</span>. El artículo 56 del TFUE establece que quedarán prohibidas las restricciones a la libre prestación de servicios dentro de la Unión para los nacionales de los Estados miembros establecidos en un Estado miembro distinto del destinatario de la prestación."},{"i":"3-181","p":"Tratado de Funcionamiento de la Unión Europea. La liberalización de los servicios bancarios y de seguros vinculados a los movimientos de capitales se realizará en armonía:","o":["Con la liberalización del sector bancario.","Con la liberalización de la circulación de capitales.","Con la liberalización de la industria.","Con la liberalización de la energía."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Con la liberalización de la circulación de capitales</mark></span>El <span class=\"ref-norma\">art. 58.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La liberalización de los servicios bancarios y de seguros vinculados a los movimientos de capitales se realizará en armonía con la liberalización de la circulación de capitales\"</span>. El artículo 58.2 del TFUE establece que la liberalización de los servicios bancarios y de seguros vinculados a los movimientos de capitales se realizará en armonía con la liberalización de la circulación de capitales."},{"i":"3-ia-3305","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. Quedarán prohibidas las restricciones a la libre prestación de servicios dentro de la Unión para los nacionales de los Estados miembros establecidos en un Estado miembro que no sea el del destinatario de la prestación; el Parlamento Europeo y el Consejo podrán extender el beneficio de estas disposiciones:","o":["a los prestadores de servicios que sean nacionales de un tercer Estado y se hallen establecidos dentro de la Unión.","a los prestadores de servicios que sean nacionales de un tercer Estado y no se hallen establecidos en la Unión, en los términos que establezca la propia norma.","a los destinatarios de servicios que sean nacionales de un tercer Estado y residan en la Unión.","a los prestadores de servicios establecidos en Estados que hayan celebrado acuerdos con la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a los prestadores de servicios que sean nacionales de un tercer Estado y se hallen establecidos dentro de la Unión</mark></span>El <span class=\"ref-norma\">art. 56 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrán extender el beneficio de las disposiciones del presente capítulo a los prestadores de servicios que sean nacionales de un tercer Estado y se hallen establecidos dentro de la Unión\"</span>. El procedimiento legislativo ordinario permite extenderlo a nacionales de terceros Estados establecidos en la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3306","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. Se considerarán como servicios las prestaciones realizadas normalmente a cambio de una remuneración, en la medida en que no se rijan por las disposiciones relativas a:","o":["la libre circulación de mercancías, capitales y empresas.","la libre circulación de trabajadores, capitales y mercancías.","el derecho de establecimiento, capitales y mercancías.","la libre circulación de mercancías, capitales y personas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la libre circulación de mercancías, capitales y personas</mark></span>El <span class=\"ref-norma\">art. 57 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en la medida en que no se rijan por las disposiciones relativas a la libre circulación de mercancías, capitales y personas\"</span>. Los servicios son una categoría residual frente a mercancías, capitales y personas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3307","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. Los servicios comprenderán, en particular, las actividades de carácter industrial, las de carácter mercantil, las actividades artesanales y:","o":["las actividades de carácter agrícola y pesquero.","las actividades propias de la función pública.","las actividades propias de las profesiones liberales.","las actividades de carácter financiero y de seguros, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las actividades propias de las profesiones liberales</mark></span>El <span class=\"ref-norma\">art. 57 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"c) actividades artesanales; d) actividades propias de las profesiones liberales\"</span>. La lista termina en las profesiones liberales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3308","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. El prestador de un servicio podrá, con objeto de realizar dicha prestación, ejercer temporalmente su actividad en el Estado miembro donde se lleve a cabo la prestación, en las mismas condiciones que:","o":["imponga su Estado de origen a sus nacionales.","imponga ese Estado a sus propios nacionales.","fije la Unión para los prestadores transfronterizos.","establezca la Comisión mediante reglamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">imponga ese Estado a sus propios nacionales</mark></span>El <span class=\"ref-norma\">art. 57 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en las mismas condiciones que imponga ese Estado a sus propios nacionales\"</span>. Mismas condiciones que las impuestas a los nacionales del Estado de prestación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3309","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. La libre prestación de servicios en materia de transportes se regirá por las disposiciones del título relativo a los transportes, y la liberalización de los servicios bancarios y de seguros vinculados a los movimientos de capitales se realizará:","o":["en armonía con la liberalización de la circulación de capitales.","en coordinación con la liberalización de la libre prestación de servicios.","con arreglo a las directivas específicas del Banco Central Europeo.","de forma gradual y con la autorización previa de la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en armonía con la liberalización de la circulación de capitales</mark></span>El <span class=\"ref-norma\">art. 58 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se realizará en armonía con la liberalización de la circulación de capitales\"</span>. Servicios bancarios y de seguros: en armonía con la liberalización de capitales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3311","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. Los Estados miembros se esforzarán por proceder a una liberalización de los servicios más amplia que la exigida en virtud de las directivas, si su situación económica general y la del sector afectado se lo permiten; a este fin, la Comisión:","o":["presentará propuestas legislativas al Consejo.","dictará decisiones vinculantes a los Estados miembros, conforme al procedimiento que se establezca reglamentariamente.","dirigirá recomendaciones a los Estados miembros interesados.","elaborará informes anuales para el Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dirigirá recomendaciones a los Estados miembros interesados</mark></span>El <span class=\"ref-norma\">art. 60 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Comisión dirigirá, a este fin, recomendaciones a los Estados miembros interesados\"</span>. La Comisión dirige recomendaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3312","p":"Tratado de Funcionamiento de la Unión Europea. Servicios. En tanto no se supriman las restricciones a la libre prestación de servicios, cada uno de los Estados miembros aplicará tales restricciones:","o":["con trato preferente a los nacionales y residentes de los demás Estados miembros.","sin distinción de nacionalidad o residencia, a todos los prestadores de servicios.","únicamente a los prestadores de servicios que no tengan la nacionalidad de un Estado miembro.","con arreglo al principio de reciprocidad entre los Estados miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">sin distinción de nacionalidad o residencia, a todos los prestadores de servicios</mark></span>El <span class=\"ref-norma\">art. 61 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"aplicará tales restricciones, sin distinción de nacionalidad o residencia, a todos los prestadores de servicios\"</span>. Sin distinción de nacionalidad o residencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 8 — Relaciones preferentes con los países vecinos ✱","q":[{"i":"3-86","p":"Tratado de la Unión Europea. La Unión desarrollará con los países vecinos:","o":["Relaciones prioritarias.","Relaciones preferentes.","Relaciones bilaterales.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Relaciones preferentes</mark></span>Son relaciones PREFERENTES (no prioritarias). Según el <span class=\"ref-norma\">art. 8.1 del TUE</span>: <span class=\"ref-concepto\">\"La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad...\"</span> (verificado con el texto del temario)."},{"i":"3-108","p":"Tratado de la Unión Europea. Relaciones preferentes con los países vecinos. Señale la CORRECTA.","o":["La Unión desarrollará con los países europeos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación.","La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación.","La Unión desarrollará con los países europeos relaciones prioritarias, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación.","La Unión desarrollará con los países vecinos relaciones prioritarias, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación</mark></span>Países VECINOS y relaciones PREFERENTES. Según el <span class=\"ref-norma\">art. 8.1 del TUE</span>: <span class=\"ref-concepto\">\"La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación.\"</span> (verificado con el texto del temario)."},{"i":"3-198","p":"Tratado de la Unión Europea. La Unión desarrollará con los países vecinos:","o":["Acuerdos bilaterales.","Acuerdos profundos.","Relaciones preferentes.","Relaciones subjetivas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Relaciones preferentes</mark></span>El <span class=\"ref-norma\">art. 8.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación\"</span>. La respuesta que recoge el Tratado es 'relaciones preferentes'. El artículo 8.1 del TUE establece que la Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión."},{"i":"3-241","p":"Tratado de la Unión Europea. Señale la INCORRECTA sobre las relaciones preferentes de la Unión con países vecinos.","o":["La Unión desarrollará con los países vecinos relaciones preferentes.","La Unión podrá celebrar acuerdos específicos con los países vecinos.","El objeto de las relaciones preferentes es establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por unas relaciones estrechas y pacíficas fundadas en la cooperación.","La aplicación de los acuerdos específicos de la Unión con países vecinos será objeto de una concertación permanente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La aplicación de los acuerdos específicos de la Unión con países vecinos será objeto de una concertación permanente</mark></span>El <span class=\"ref-norma\">art. 8.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"A efectos del apartado 1, la Unión podrá celebrar acuerdos específicos con dichos países. Estos acuerdos podrán incluir derechos y obligaciones recíprocos, así como la posibilidad de realizar acciones en común. Su aplicación será objeto de una concertación periódica\"</span>. (The INCORRECT statement is that the application of specific agreements will be subject to permanent consultation; this statement is not found in the Treaty in the context of preferred relationships with neighboring countries, whose application is simply defined by them.)"},{"i":"3-ia-3036","p":"Tratado de la Unión Europea. Relaciones preferentes con los países vecinos. La Unión desarrollará con los países vecinos relaciones preferentes, con el objetivo de establecer un espacio de prosperidad y de buena vecindad basado en los valores de la Unión y caracterizado por:","o":["unas relaciones comerciales y políticas fundadas en la reciprocidad.","unas relaciones estrechas y pacíficas fundadas en la cooperación.","unas relaciones estables y duraderas fundadas en la solidaridad.","unas relaciones económicas y sociales fundadas en el desarrollo mutuo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">unas relaciones estrechas y pacíficas fundadas en la cooperación</mark></span>El <span class=\"ref-norma\">art. 8.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"unas relaciones estrechas y pacíficas fundadas en la cooperación\"</span>. Las relaciones son estrechas y pacíficas, fundadas en la cooperación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3037","p":"Tratado de la Unión Europea. Relaciones preferentes con los países vecinos. La Unión podrá celebrar acuerdos específicos con los países vecinos; estos acuerdos podrán incluir derechos y obligaciones recíprocos, así como la posibilidad de realizar acciones en común, y su aplicación será objeto de:","o":["una concertación periódica.","un control parlamentario periódico.","una evaluación periódica por la Comisión.","una revisión periódica por el Consejo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">una concertación periódica</mark></span>El <span class=\"ref-norma\">art. 8.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Su aplicación será objeto de una concertación periódica\"</span>. Su aplicación se somete a una concertación periódica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 26 — Consejo Europeo, Consejo y Alto Representante en la PESC ✱","q":[{"i":"3-88","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. ¿Quién expresará la posición de la Unión en las organizaciones internacionales y en las conferencias internacionales?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","La Comisión.","El Parlamento Europeo.","El Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 27.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, que presidirá el Consejo de Asuntos Exteriores, contribuirá con sus propuestas a elaborar la política exterior y de seguridad común y se encargará de ejecutar las decisiones adoptadas por el Consejo Europeo y el Consejo\"</span>. El artículo 27.2 del TUE dispone que el Alto Representante representará a la Unión en las materias de política exterior y de seguridad común, dirigirá el diálogo político con terceros y expresará la posición de la Unión en las organizaciones y conferencias internacionales."},{"i":"3-120","p":"Tratado de la Unión Europea. Determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa:","o":["El Presidente del Consejo Europeo.","El Consejo Europeo.","El Consejo.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 26.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa\"</span>. El artículo 26.1 del TUE atribuye al Consejo Europeo determinar los intereses estratégicos de la Unión, fijar los objetivos y definir las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos con repercusiones en el ámbito de la defensa."},{"i":"3-180","p":"Tratado de la Unión Europea. Disposiciones específicas sobre la política exterior y de seguridad común. ¿Quién determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa?","o":["El Consejo Europeo.","La Comisión Europea.","El Consejo.","El Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 26.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa\"</span>. El artículo 26.1 del TUE atribuye al Consejo Europeo determinar los intereses estratégicos de la Unión, fijar los objetivos y definir las orientaciones generales de la política exterior y de seguridad común."},{"i":"3-187","p":"Tratado de la Unión Europea. ¿Quién velará por la unidad, la coherencia y la eficacia de la acción de la Unión?","o":["El Consejo Europeo.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad y los Estados miembros.","El Consejo y los Estados Miembros.","El Consejo y el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo y el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 26.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Basándose en las orientaciones generales y en las líneas estratégicas definidas por el Consejo Europeo, el Consejo elaborará la política exterior y de seguridad común y adoptará las decisiones necesarias para definir y aplicar dicha política. \u0007El Consejo y el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad velarán por la unidad, la coherencia y la eficacia de la acción de la Unión\"</span>. El artículo 26.2 del TUE establece que el Consejo y el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad velarán por la unidad, la coherencia y la eficacia de la acción de la Unión."},{"i":"3-195","p":"Tratado de la Unión Europea. ¿Quién dirigirá el diálogo político con terceros en nombre de la Unión?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","La Comisión.","El Parlamento Europeo.","El Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 27.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, que presidirá el Consejo de Asuntos Exteriores, contribuirá con sus propuestas a elaborar la política exterior y de seguridad común y se encargará de ejecutar las decisiones adoptadas por el Consejo Europeo y el Consejo\"</span>. El artículo 27.2 del TUE establece que el Alto Representante dirigirá el diálogo político con terceros en nombre de la Unión y expresará la posición de la Unión en las organizaciones internacionales y en las conferencias internacionales."},{"i":"3-197","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. ¿Quién se encargará de ejecutar las decisiones adoptadas por el Consejo Europeo y el Consejo?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","La Comisión.","El Parlamento Europeo.","El Tribunal de Justicia de la Unión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 27.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, que presidirá el Consejo de Asuntos Exteriores, contribuirá con sus propuestas a elaborar la política exterior y de seguridad común y se encargará de ejecutar las decisiones adoptadas por el Consejo Europeo y el Consejo\"</span>. El artículo 27.1 del TUE establece que el Alto Representante se encargará de ejecutar las decisiones adoptadas por el Consejo Europeo y el Consejo en materia de política exterior y de seguridad común."},{"i":"3-222","p":"Tratado de la Unión Europea. ¿Quién elaborará la política exterior y de seguridad común y adoptará las decisiones necesarias para definir y aplicar dicha política?","o":["El Consejo.","El Parlamento Europeo.","La Comisión.","Una comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 26.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Basándose en las orientaciones generales y en las líneas estratégicas definidas por el Consejo Europeo, el Consejo elaborará la política exterior y de seguridad común y adoptará las decisiones necesarias para definir y aplicar dicha política. \u0007El Consejo y el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad velarán por la unidad, la coherencia y la eficacia de la acción de la Unión\"</span>. El artículo 26.2 del TUE establece que, basándose en las orientaciones generales y líneas estratégicas definidas por el Consejo Europeo, el Consejo elaborará la política exterior y de seguridad común y adoptará las decisiones necesarias para definirla y aplicarla."},{"i":"3-273","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. Los Estados miembros coordinarán su acción en las organizaciones internacionales y con ocasión de las conferencias internacionales. ¿Quién organizará dicha coordinación?","o":["El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Consejo Europeo.","El Consejo.","La Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 34.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los Estados miembros coordinarán su acción en las organizaciones internacionales y con ocasión de las conferencias internacionales. Los Estados miembros defenderán en esos foros las posiciones de la Unión. El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad organizará dicha coordinación\"</span>. El artículo 34.1 del TUE establece que el Alto Representante organizará la coordinación de los Estados miembros en las organizaciones internacionales y en las conferencias internacionales."},{"i":"3-ia-3148","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. El Consejo Europeo determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa; si un acontecimiento internacional así lo exige:","o":["el Alto Representante convocará una reunión extraordinaria del Consejo de Asuntos Exteriores.","el Presidente del Consejo Europeo convocará una reunión extraordinaria del Consejo Europeo.","el Presidente de la Comisión convocará una reunión extraordinaria del Consejo Europeo.","el Consejo convocará una reunión extraordinaria del Comité de Representantes Permanentes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Presidente del Consejo Europeo convocará una reunión extraordinaria del Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 26.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Presidente del Consejo Europeo convocará una\"</span>. La convocatoria extraordinaria la hace el Presidente del Consejo Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3149","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Basándose en las orientaciones generales y en las líneas estratégicas definidas por el Consejo Europeo, el Consejo elaborará la política exterior y de seguridad común; ésta será ejecutada por:","o":["el Alto Representante y por los Estados miembros, utilizando los medios nacionales y los de la Unión.","el Alto Representante y por la Comisión, utilizando los medios de la Unión exclusivamente, en los términos que establezca la propia norma.","el Consejo y por los Estados miembros, utilizando los medios nacionales de éstos.","el Presidente del Consejo Europeo y por el Alto Representante, con los medios de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Alto Representante y por los Estados miembros, utilizando los medios nacionales y los de la Unión</mark></span>El <span class=\"ref-norma\">art. 26.2 y 3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"será ejecutada por el Alto Representante y por los Estados\"</span>. Ejecutan el Alto Representante y los Estados miembros, con medios nacionales y de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3232","p":"Tratado de la Unión Europea. Realización de misiones por un grupo de Estados. Los Estados miembros que participen en la realización de la misión comunicarán de inmediato al Consejo si ésta acarrea consecuencias importantes o exige una modificación del objetivo, alcance o condiciones de la misión; en tales casos, el Consejo:","o":["convocará una reunión extraordinaria del Consejo Europeo.","adoptará las decisiones necesarias.","suspenderá la misión hasta nueva decisión.","consultará al Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">adoptará las decisiones necesarias</mark></span>El <span class=\"ref-norma\">art. 44.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"En tales casos, el Consejo adoptará las decisiones necesarias\"</span>. El Consejo adopta las decisiones necesarias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3502","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. La Comisión podrá asistir a todas las sesiones del Parlamento Europeo y comparecerá ante éste si así lo solicita; además, contestará oralmente o por escrito a todas las preguntas que le sean formuladas por el Parlamento Europeo o por sus miembros, y el Consejo Europeo y el Consejo comparecerán ante el Parlamento Europeo:","o":["en las condiciones fijadas por el reglamento interno del Parlamento Europeo.","cuando lo decida el Parlamento Europeo por mayoría de los miembros que lo componen.","en las condiciones fijadas por acuerdo interinstitucional entre las tres instituciones, salvo que se disponga otra cosa en la normativa aplicable.","en las condiciones fijadas por el reglamento interno del Consejo Europeo y por el del Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">en las condiciones fijadas por el reglamento interno del Consejo Europeo y por el del Consejo</mark></span>El <span class=\"ref-norma\">art. 230 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo y el Consejo comparecerán ante el Parlamento Europeo en las condiciones fijadas por el reglamento interno del Consejo Europeo y por el del Consejo\"</span>. Comparecen según sus propios reglamentos internos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 33 — Representante especial · R13 R13","q":[{"i":"3-89","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. A propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, el Consejo podrá designar ______ provisto de un mandato en relación con cuestiones políticas concretas.","o":["Un servicio europeo de acción exterior.","Un representante de exteriores.","Un representante especial.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un representante especial</mark></span>El <span class=\"ref-norma\">art. 33 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, el Consejo podrá designar un representante especial provisto de un mandato en relación con cuestiones políticas concretas. El representante especial ejercerá su mandato bajo la autoridad del Alto Representante\"</span>. El artículo 33 del TUE establece que, a propuesta del Alto Representante, el Consejo podrá designar un representante especial provisto de un mandato en relación con cuestiones políticas concretas, que ejercerá su mandato bajo la autoridad del Alto Representante."},{"i":"3-ia-3162","p":"Tratado de la Unión Europea. Votaciones en PESC. Como excepción a la unanimidad, el Consejo adoptará por mayoría cualificada, entre otras, una decisión que establezca una acción o una posición de la Unión a partir de una decisión del Consejo Europeo relativa a los intereses y objetivos estratégicos de la Unión y:","o":["la aprobación del presupuesto de la PESC, salvo que se disponga otra cosa en la normativa aplicable.","la declaración de una acción operativa.","la designación del Alto Representante.","la designación de un representante especial."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la designación de un representante especial</mark></span>El <span class=\"ref-norma\">art. 31.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la designación de un representante especial de conformidad con el artículo 33\"</span>. Entre los supuestos de mayoría cualificada está la designación de un representante especial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3168","p":"Tratado de la Unión Europea. Representantes especiales. A propuesta del Alto Representante, el Consejo podrá designar un representante especial provisto de un mandato en relación con cuestiones políticas concretas, que ejercerá su mandato:","o":["bajo la autoridad del Consejo Europeo.","bajo la autoridad del Alto Representante.","bajo la autoridad de la Comisión.","bajo la autoridad del Presidente del Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">bajo la autoridad del Alto Representante</mark></span>El <span class=\"ref-norma\">art. 33 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El representante especial ejercerá su mandato bajo la autoridad del Alto Representante\"</span>. El representante especial actúa bajo la autoridad del Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3218","p":"Tratado de la Unión Europea. Financiación de la PESC. Los preparativos de las misiones que no se imputen al presupuesto de la Unión se financiarán mediante un fondo inicial constituido por contribuciones de los Estados miembros; las decisiones sobre su constitución, gestión y control financiero las adoptará el Consejo por mayoría cualificada:","o":["a propuesta de la Comisión.","a iniciativa del Consejo Europeo.","previa aprobación del Parlamento Europeo.","a propuesta del Alto Representante."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a propuesta del Alto Representante</mark></span>El <span class=\"ref-norma\">art. 41.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones\"</span>. Mayoría cualificada a propuesta del Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3531","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Las responsabilidades que incumben a la Comisión serán estructuradas y repartidas entre sus miembros por el Presidente, que podrá reorganizar el reparto a lo largo de su mandato; los miembros de la Comisión ejercerán las funciones que les atribuya el Presidente:","o":["bajo la autoridad del Colegio.","con plena autonomía.","bajo la autoridad de éste.","bajo la autoridad del Alto Representante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">bajo la autoridad de éste</mark></span>El <span class=\"ref-norma\">art. 248 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los miembros de la Comisión ejercerán las funciones que les atribuya el Presidente bajo la autoridad de éste\"</span>. Actúan bajo la autoridad del Presidente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 24 — Competencia en PESC ✱","q":[{"i":"3-91","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. Disposiciones específicas sobre la Política Exterior y de Seguridad Común. Señale la incorrecta.","o":["La competencia de la Unión en materia de política exterior y de seguridad común abarcará todos los ámbitos de la política exterior y todas las cuestiones relativas a la seguridad de la Unión, incluida la definición progresiva de una política común de defensa que conducirá en todo caso a una defensa común.","En el ejercicio de su mandato, el Alto Representante se apoyará en un servicio europeo de acción exterior.","Los Estados miembros se consultarán en el seno del Consejo Europeo y del Consejo sobre cualquier cuestión de política exterior y de seguridad que revista un interés general, a fin de definir un enfoque común.","Los Estados miembros apoyarán activamente y sin reservas la política exterior y de seguridad de la Unión, con espíritu de lealtad y solidaridad mutuas y respetarán la acción de la Unión en este ámbito."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La competencia de la Unión en materia de política exterior y de seguridad común abarcará todos los ámbitos de la política exterior y todas las cuestiones relativas a la seguridad de la Unión, incluida la definición progresiva de una política común de defensa que conducirá en todo caso a una defensa común</mark></span>Es incorrecta porque el texto dice «podrá conducir», no «conducirá en todo caso» (la defensa común exige decisión unánime del Consejo Europeo, art. 42.2). B (art. 27.3), C (art. 32) y D (art. 24.3) reproducen el Tratado. Según el <span class=\"ref-norma\">art. 24.1 del TUE</span>: <span class=\"ref-concepto\">\"...incluida la definición progresiva de una política común de defensa que podrá conducir a una defensa común.\"</span> (verificado con el texto del temario)."},{"i":"3-116","p":"Tratado de la Unión Europea. Disposiciones comunes. La política exterior y de seguridad común será ejecutada por __________ de conformidad con los Tratados.","o":["El Consejo Europeo.","El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad y por los Estados miembros.","El Consejo y por los Estados Miembros.","La Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad y por los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 22.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, en el ámbito de la política exterior y de seguridad común, y la Comisión, en los demás ámbitos de la acción exterior, podrán presentar propuestas conjuntas al Consejo. CAPÍTULO II. DISPOSICIONES ESPECÍFICAS SOBRE LA POLÍTICA EXTERIOR Y DE SEGURIDAD COMÚN SECCIÓN 1.ª Disposiciones comunes\"</span>. Nota: Esta pregunta se repite con la pregunta 2."},{"i":"3-186","p":"Tratado de la Unión Europea. En el marco de los principios y de los objetivos de su acción exterior, la Unión dirigirá, definirá y ejecutará una política exterior y de seguridad común basada:","o":["En el desarrollo de la solidaridad política mutua de los Estados miembros.","En la identificación de los asuntos que presenten un interés general.","En la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 24.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007En el marco de los principios y de los objetivos de su acción exterior, la Unión dirigirá, definirá y ejecutará una política exterior y de seguridad común basada en el desarrollo de la solidaridad política mutua de los Estados miembros, en la identificación de los asuntos que presenten un interés general y en la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros\"</span>. El artículo 24.2 del TUE establece que la Unión dirigirá, definirá y ejecutará una política exterior y de seguridad común basada en el desarrollo de la solidaridad política mutua, en la identificación de asuntos de interés general y en la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros."},{"i":"3-ia-3141","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. La competencia de la Unión en materia de política exterior y de seguridad común abarcará todos los ámbitos de la política exterior y todas las cuestiones relativas a la seguridad de la Unión, incluida la definición progresiva de una política común de defensa que:","o":["podrá conducir a una defensa común.","conducirá a una defensa común.","sustituirá a las defensas nacionales.","complementará a la OTAN."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">podrá conducir a una defensa común</mark></span>El <span class=\"ref-norma\">art. 24.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"incluida la de-finición progresiva de una política común de defensa que podrá conducir a una defensa común\"</span>. La política común de defensa podrá conducir a una defensa común. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3142","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. La política exterior y de seguridad común se regirá por reglas y procedimientos específicos; la definirán y aplicarán el Consejo Europeo y el Consejo, que deberán pronunciarse por unanimidad salvo cuando los Tratados dispongan otra cosa, y queda excluida:","o":["la adopción de actos no legislativos.","la adopción de decisiones por mayoría.","la intervención del Parlamento Europeo.","la adopción de actos legislativos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la adopción de actos legislativos</mark></span>El <span class=\"ref-norma\">art. 24.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Queda excluida la adopción de actos legislativos\"</span>. En la PESC no se adoptan actos legislativos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3143","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. La política exterior y de seguridad común será ejecutada por el Alto Representante y por los Estados miembros; el Tribunal de Justicia de la Unión Europea:","o":["tendrá competencia plena respecto de estas disposiciones.","tendrá competencia únicamente para resolver conflictos entre Estados.","no tendrá competencia respecto de estas disposiciones, con determinadas salvedades.","tendrá competencia para controlar la legalidad de todas las decisiones, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">no tendrá competencia respecto de estas disposiciones, con determinadas salvedades</mark></span>El <span class=\"ref-norma\">art. 24.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia de la Unión Europea no tendrá competencia respecto de estas disposiciones\"</span>. No tiene competencia salvo para el control del respeto del artículo 40 y de determinadas decisiones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3144","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. La Unión dirigirá, definirá y ejecutará una política exterior y de seguridad común basada en el desarrollo de la solidaridad política mutua de los Estados miembros, en la identificación de los asuntos que presenten un interés general y en:","o":["la coordinación de las políticas exteriores de los Estados miembros en el seno del Consejo.","la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros.","la definición de una posición común sobre los asuntos que afecten a la seguridad de la Unión.","la adopción de decisiones vinculantes para todos los Estados miembros por mayoría cualificada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 24.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"y en la consecución de una convergencia cada vez mayor de la actuación de los Estados miembros\"</span>. La PESC se basa en solidaridad política, interés general y convergencia creciente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3145","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Los Estados miembros apoyarán activamente y sin reservas la política exterior y de seguridad de la Unión, con espíritu de lealtad y solidaridad mutua, y se abstendrán de:","o":["toda acción contraria a los intereses de la Unión o que pueda perjudicar su eficacia como fuerza de cohesión.","toda posición nacional contraria a las decisiones adoptadas por el Consejo Europeo.","toda actuación unilateral en la escena internacional sin autorización del Alto Representante, en los términos que establezca la propia norma.","toda iniciativa que pueda alterar el equilibrio de las relaciones con los terceros países."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">toda acción contraria a los intereses de la Unión o que pueda perjudicar su eficacia como fuerza de cohesión</mark></span>El <span class=\"ref-norma\">art. 24.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se abstendrán de toda acción contraria a los intereses de la Unión o que pueda perjudicar su eficacia como fuerza de cohesión en las relaciones internacionales\"</span>. No deben actuar contra los intereses de la Unión ni perjudicar su eficacia como fuerza de cohesión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3146","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Los Estados miembros trabajarán conjuntamente para intensificar y desarrollar su solidaridad política mutua; velarán por que se respeten estos principios:","o":["el Consejo Europeo y la Comisión.","el Alto Representante y la Comisión.","el Parlamento Europeo y el Consejo.","el Consejo y el Alto Representante."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Consejo y el Alto Representante</mark></span>El <span class=\"ref-norma\">art. 24.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo y el Alto Representante velarán por que se respeten estos principios\"</span>. Velan por el respeto de estos principios el Consejo y el Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3404","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. La cooperación judicial en materia penal en la Unión se basará en el principio de reconocimiento mutuo de las sentencias y resoluciones judiciales e incluye:","o":["la armonización plena de las legislaciones penales de los Estados miembros.","la aproximación de las disposiciones legales y reglamentarias de los Estados miembros en determinados ámbitos.","la creación de un espacio judicial penal único bajo la jurisdicción del Tribunal de Justicia, sin perjuicio de lo dispuesto en otras disposiciones.","la unificación de los procedimientos penales de los Estados miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la aproximación de las disposiciones legales y reglamentarias de los Estados miembros en determinados ámbitos</mark></span>El <span class=\"ref-norma\">art. 82.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se basará en el principio de reconocimiento mutuo de las sentencias y resoluciones judiciales e incluye la aproximación de las disposiciones legales y reglamentarias de los Estados miembros\"</span>. Reconocimiento mutuo y aproximación de legislaciones en ámbitos determinados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 263 a 267 TFUE — Anulación, omisión y prejudicial · R26 EXOF ✱ R26","q":[{"i":"3-101","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea controlará la legalidad de: Señale la INCORRECTA.","o":["De los actos legislativos.","De los actos del Consejo, de la Comisión y del Banco Central Europeo que no sean recomendaciones o dictámenes.","De los actos del Parlamento Europeo y del Consejo Europeo destinados a producir efectos jurídicos frente a terceros.","De los actos de los órganos y organismos de la Unión destinados a no producir efectos jurídicos frente a terceros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De los actos de los órganos y organismos de la Unión destinados a no producir efectos jurídicos frente a terceros</mark></span>El <span class=\"ref-norma\">art. 263 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia de la Unión Europea controlará la legalidad de los actos legislativos, de los actos del Consejo, de la Comisión y del Banco Central Europeo que no sean recomendaciones o dictámenes, y de los actos del Parlamento Europeo y del Consejo Europeo destinados a producir efectos jurídicos frente a terceros. Controlará también la legalidad de los actos de los órganos u organismos de la Unión destinados a producir efectos jurídicos frente a terceros\"</span>. La opción correcta es la D, por ser la incorrecta. El artículo 263 del TFUE establece que el Tribunal de Justicia controlará la legalidad de los actos de los órganos y organismos de la Unión destinados a producir efectos jurídicos frente a terceros, justo lo contrario de lo que indica la opción D."},{"i":"3-375","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. Si el recurso de anulación fuere fundado, el Tribunal de Justicia de la Unión Europea declarará:","o":["Nulo el acto impugnado con efectos retroactivos en todo caso.","Anulable el acto impugnado, previa decisión del Consejo.","Nulo y sin valor ni efecto alguno el acto impugnado.","Suspendido el acto impugnado hasta nueva decisión de la institución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Nulo y sin valor ni efecto alguno el acto impugnado</mark></span>El <span class=\"ref-norma\">art. 264 del TFUE</span> dispone: <span class=\"ref-concepto\">\"declarará nulo y sin valor ni efecto alguno el acto impugnado\"</span>. El acto se declara nulo y sin valor ni efecto alguno."},{"i":"3-376","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El recurso por omisión solamente será admisible si la institución, órgano u organismo de que se trate hubieren sido requeridos previamente para que actúen. Si transcurrido un plazo de dos meses, a partir de dicho requerimiento, no hubiere definido su posición, el recurso podrá ser interpuesto:","o":["Dentro de un nuevo plazo de un mes y medio.","Dentro de un nuevo plazo de dos meses.","Dentro de un nuevo plazo de tres meses.","Sin sujeción a plazo alguno, tras el requerimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dentro de un nuevo plazo de dos meses</mark></span>El <span class=\"ref-norma\">art. 265 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el recurso podrá ser interpuesto dentro de un nuevo plazo de dos meses\"</span>. Dos meses para definir posición y otros dos para recurrir."},{"i":"3-409","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea será competente para pronunciarse, con carácter prejudicial:","o":["Sobre la interpretación de los Tratados y sobre la validez de los actos adoptados por las instituciones de los Estados miembros.","Sobre la interpretación de los Tratados, exclusivamente, y no sobre los actos de los organismos de la Unión.","Sobre la validez e interpretación del Derecho nacional y de los actos de las instituciones de la Unión.","Sobre la interpretación de los Tratados y sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Sobre la interpretación de los Tratados y sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión</mark></span>El <span class=\"ref-norma\">art. 267 del TFUE</span> dispone: <span class=\"ref-concepto\">\"con carácter prejudicial: a) sobre la interpretación de los Tratados; b) sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión\"</span>. Ficha RECUERDA R26 (y círculo EXOF del temario). <em style=\"color:var(--texto-gris)\">(ficha RECUERDA R26 del temario)</em>"},{"i":"3-ia-3049","p":"Tratado de la Unión Europea. Marco institucional. Las instituciones de la Unión son el Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión Europea, el Tribunal de Justicia de la Unión Europea, el Banco Central Europeo y:","o":["el Tribunal de Cuentas.","el Comité de las Regiones.","el Comité Económico y Social.","el Banco Europeo de Inversiones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Tribunal de Cuentas</mark></span>El <span class=\"ref-norma\">art. 13.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El BANCO CENTRAL EUROPEO, El TRIBUNAL DE CUENTAS\"</span>. Son siete: la última es el Tribunal de Cuentas. Los Comités son órganos consultivos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3608","p":"Tratado de Funcionamiento de la Unión Europea. Recurso de anulación. El Tribunal de Justicia de la Unión Europea controlará la legalidad de los actos legislativos, de los actos del Consejo, de la Comisión y del Banco Central Europeo que no sean recomendaciones o dictámenes, y de los actos del Parlamento Europeo y del Consejo Europeo:","o":["destinados a producir efectos jurídicos entre las instituciones.","destinados a producir efectos jurídicos frente a terceros.","de alcance general adoptados en el ejercicio de sus competencias.","adoptados en el ejercicio de funciones legislativas o presupuestarias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">destinados a producir efectos jurídicos frente a terceros</mark></span>El <span class=\"ref-norma\">art. 263 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de los actos del Parlamento Europeo y del Consejo Europeo destinados a producir efectos jurídicos frente a terceros\"</span>. Control de actos del Parlamento y del Consejo Europeo destinados a producir efectos frente a terceros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3610","p":"Tratado de Funcionamiento de la Unión Europea. Recurso de anulación. El Tribunal de Justicia será competente, en las mismas condiciones, para pronunciarse sobre los recursos interpuestos por el Tribunal de Cuentas, por el Banco Central Europeo y por el Comité de las Regiones con el fin de:","o":["proteger sus competencias exclusivas.","garantizar su independencia funcional.","defender su autonomía presupuestaria.","salvaguardar prerrogativas de éstos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">salvaguardar prerrogativas de éstos</mark></span>El <span class=\"ref-norma\">art. 263 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con el fin de salvaguardar prerrogativas de éstos\"</span>. Son legitimados semiprivilegiados: solo para salvaguardar sus prerrogativas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3612","p":"Tratado de Funcionamiento de la Unión Europea. Recurso de anulación. Los recursos de anulación deberán interponerse en el plazo de dos meses a partir, según los casos, de la publicación del acto, de su notificación al recurrente o, a falta de ello:","o":["desde el día en que el acto haya entrado en vigor.","desde el día en que éste haya tenido conocimiento del mismo.","desde el día en que se haya agotado la vía administrativa.","desde el día en que el acto haya surtido efectos frente a terceros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">desde el día en que éste haya tenido conocimiento del mismo</mark></span>El <span class=\"ref-norma\">art. 263 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"o, a falta de ello, desde el día en que éste haya tenido conocimiento del mismo\"</span>. Dos meses desde la publicación, la notificación o el conocimiento del acto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3613","p":"Tratado de Funcionamiento de la Unión Europea. Efectos de la anulación. Si el recurso de anulación fuere fundado, el Tribunal de Justicia declarará nulo y sin valor ni efecto alguno el acto impugnado; sin embargo, el Tribunal indicará, si lo estima necesario:","o":["aquellos efectos del acto declarado nulo que deban ser considerados como definitivos.","los plazos para que la institución adopte un nuevo acto sustitutivo.","las indemnizaciones que correspondan a los afectados por el acto anulado.","las medidas que deban adoptar los Estados miembros para ejecutar la sentencia, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">aquellos efectos del acto declarado nulo que deban ser considerados como definitivos</mark></span>El <span class=\"ref-norma\">art. 264 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Tribunal indicará, si lo estima necesario, aquellos efectos del acto declarado nulo que deban ser considerados como definitivos\"</span>. Puede mantener efectos del acto anulado por razones de seguridad jurídica. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3615","p":"Tratado de Funcionamiento de la Unión Europea. Recurso por omisión. El recurso por omisión solamente será admisible si la institución, órgano u organismo de que se trate hubieren sido requeridos previamente para que actúen; si transcurrido un plazo de dos meses, a partir de dicho requerimiento, no hubiere definido su posición, el recurso podrá ser interpuesto:","o":["dentro de un nuevo plazo de un mes.","dentro de un nuevo plazo de tres meses.","dentro de un nuevo plazo de dos meses.","sin sujeción a plazo alguno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dentro de un nuevo plazo de dos meses</mark></span>El <span class=\"ref-norma\">art. 265 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el recurso podrá ser interpuesto dentro de un nuevo plazo de dos meses\"</span>. Requerimiento previo, dos meses para definir posición y nuevo plazo de dos meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3616","p":"Tratado de Funcionamiento de la Unión Europea. Recurso por omisión. Toda persona física o jurídica podrá recurrir en queja al Tribunal, en las condiciones señaladas, por no haberle dirigido una de las instituciones, o uno de los órganos u organismos de la Unión:","o":["una resolución motivada sobre su solicitud.","un acto distinto de una recomendación o de un dictamen.","un acto de alcance individual favorable.","una notificación de las decisiones que le afecten, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un acto distinto de una recomendación o de un dictamen</mark></span>El <span class=\"ref-norma\">art. 265 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por no haberle dirigido una de las instituciones, o uno de los órganos u organismos de la Unión un acto distinto de una recomendación o de un dictamen\"</span>. La omisión se refiere a actos distintos de recomendaciones o dictámenes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3618","p":"Tratado de Funcionamiento de la Unión Europea. Cuestión prejudicial. El Tribunal de Justicia de la Unión Europea será competente para pronunciarse, con carácter prejudicial, sobre la interpretación de los Tratados y sobre:","o":["la validez de los actos adoptados por las instituciones y la conformidad de las normas nacionales con los Tratados.","la interpretación de los actos adoptados por las instituciones y la aplicación de los Tratados por los Estados.","la validez de los actos de las instituciones y la responsabilidad de los Estados por su aplicación.","la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión</mark></span>El <span class=\"ref-norma\">art. 267 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u orga-nismos de la Unión\"</span>. Interpretación de los Tratados y validez e interpretación de los actos de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3620","p":"Tratado de Funcionamiento de la Unión Europea. Cuestión prejudicial. Cuando se plantee una cuestión prejudicial en un asunto pendiente ante un órgano jurisdiccional nacional cuyas decisiones no sean susceptibles de ulterior recurso judicial de Derecho interno, dicho órgano:","o":["podrá someter la cuestión al Tribunal.","estará obligado a someter la cuestión al Tribunal.","estará obligado a remitir la cuestión al Tribunal Constitucional.","podrá consultar a la Comisión antes de decidir."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">estará obligado a someter la cuestión al Tribunal</mark></span>El <span class=\"ref-norma\">art. 267 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"dicho órgano estará obligado a someter la cuestión al Tribunal\"</span>. Los órganos de última instancia están obligados a plantearla. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3621","p":"Tratado de Funcionamiento de la Unión Europea. Cuestión prejudicial. Cuando se plantee una cuestión prejudicial en un asunto pendiente ante un órgano jurisdiccional nacional en relación con una persona privada de libertad, el Tribunal de Justicia de la Unión Europea se pronunciará:","o":["con la mayor brevedad.","en el plazo máximo de tres meses.","mediante procedimiento acelerado en Sala.","con carácter prioritario en Gran Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con la mayor brevedad</mark></span>El <span class=\"ref-norma\">art. 267 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Tribunal de Justicia de la Unión Europea se pronunciará con la mayor brevedad\"</span>. Con la mayor brevedad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 41 — Financiación de la PESC ✱","q":[{"i":"3-102","p":"Tratado de la Unión Europea. Disposiciones específicas sobre la política exterior y de seguridad común. El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones que establezcan:","o":["Las modalidades de constitución y de financiación del fondo inicial, en particular los importes financieros asignados al mismo.","Las modalidades de gestión del fondo inicial.","Las modalidades de control financiero.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 41.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"las modalidades de constitución y de financiación del fondo inicial, en particular los importes financieros asignados al mismo; b) las modalidades de gestión del fondo inicial; c) las modalidades de control financiero\"</span>. El artículo 41.3 del TUE establece que el Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante, las decisiones que establezcan las modalidades de constitución y financiación del fondo inicial, las modalidades de su gestión y las modalidades de control financiero."},{"i":"3-145","p":"Tratado de la Unión Europea. Disposiciones específicas sobre la política exterior y de seguridad común. El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones que establezcan:","o":["Las modalidades de constitución y de financiación de fondo inicial, en particular los importes financieros asignados al mismo.","Las modalidades de gestión del fondo social.","Las modalidades de control financiero.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las modalidades de constitución y de financiación de fondo inicial, en particular los importes financieros asignados al mismo</mark></span>El <span class=\"ref-norma\">art. 41.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones que establezcan: a) las modalidades de constitución y de financiación del fondo inicial, en particular los importes financieros asignados al mismo\"</span>. El artículo 41.3 del TUE establece que el Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante, las decisiones que establezcan las modalidades de constitución y financiación del fondo inicial, entre otros importes financieros asignados al mismo."},{"i":"3-296","p":"Tratado de la Unión Europea. El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones que establezcan:","o":["Las modalidades de constitución y de financiación del fondo inicial, en particular los importes financieros asignados al mismo.","Las modalidades de gestión del fondo inicial.","Las modalidades de control financiero.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 41.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, las decisiones que establezcan: a) las modalidades de constitución y de financiación del fondo inicial, en particular los importes financieros asignados al mismo; b) las modalidades de gestión del fondo inicial\"</span>. El artículo 41.3 del TUE establece que el Consejo adoptará por mayoría cualificada, a propuesta del Alto Representante, las decisiones que establezcan las modalidades de constitución y financiación del fondo inicial, las modalidades de su gestión y las modalidades de control financiero."},{"i":"3-ia-3164","p":"Tratado de la Unión Europea. Votaciones en PESC. El Consejo Europeo podrá adoptar por unanimidad una decisión que establezca que el Consejo se pronuncie por mayoría cualificada en casos distintos de los previstos; esta posibilidad:","o":["se aplicará también a las decisiones que tengan repercusiones en el ámbito de la defensa, sin perjuicio de lo dispuesto en otras disposiciones.","no se aplicará a las decisiones que tengan repercusiones en el ámbito militar o de la defensa.","no se aplicará a las decisiones que afecten a las relaciones con países vecinos.","se aplicará únicamente a las decisiones que adopte el Consejo de Asuntos Exteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no se aplicará a las decisiones que tengan repercusiones en el ámbito militar o de la defensa</mark></span>El <span class=\"ref-norma\">art. 31.3 a 5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los apartados 2 y 3 no se aplicarán a las decisiones que tengan repercusiones en el ámbito militar o de la defensa\"</span>. Quedan excluidas las decisiones con repercusiones militares o de defensa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3213","p":"Tratado de la Unión Europea. Financiación de la PESC. Los gastos administrativos que la aplicación del capítulo de la PESC ocasione a las instituciones correrán a cargo:","o":["del presupuesto de la Unión.","de los Estados miembros según el producto nacional bruto.","del presupuesto del Consejo exclusivamente.","de un fondo inicial constituido por los Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del presupuesto de la Unión</mark></span>El <span class=\"ref-norma\">art. 41.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los gastos administrativos que la aplicación del presente capítulo ocasione a las instituciones correrán a cargo del presupuesto de la Unión\"</span>. Los gastos administrativos van al presupuesto de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3214","p":"Tratado de la Unión Europea. Financiación de la PESC. Los gastos operativos derivados de la aplicación del capítulo de la PESC también correrán a cargo del presupuesto de la Unión, excepto los relativos a las operaciones que tengan repercusiones en el ámbito militar o de la defensa y los casos en que el Consejo decida:","o":["por mayoría cualificada, otra cosa.","a propuesta del Alto Representante, otra cosa.","previa consulta al Parlamento, otra cosa.","por unanimidad, otra cosa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por unanimidad, otra cosa</mark></span>El <span class=\"ref-norma\">art. 41.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"y los casos en que el Consejo decida, por unanimidad, otra cosa\"</span>. Excepciones: operaciones militares o de defensa y decisión unánime del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3215","p":"Tratado de la Unión Europea. Financiación de la PESC. Cuando los gastos operativos no corran a cargo del presupuesto de la Unión, correrán a cargo de los Estados miembros con arreglo a una clave de reparto basada:","o":["en la población de cada Estado, a menos que el Consejo decida otra cosa por mayoría cualificada.","en la contribución al presupuesto de la Unión, a menos que el Consejo decida otra cosa por unanimidad.","en el producto nacional bruto, a menos que el Consejo decida otra cosa por unanimidad.","en el producto interior bruto, a menos que el Consejo Europeo decida otra cosa por unanimidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el producto nacional bruto, a menos que el Consejo decida otra cosa por unanimidad</mark></span>El <span class=\"ref-norma\">art. 41.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con arreglo a una clave de reparto basada en el producto nacional bruto, a menos que el\"</span>. La clave es el producto nacional bruto. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3216","p":"Tratado de la Unión Europea. Financiación de la PESC. En cuanto a los gastos derivados de las operaciones que tengan repercusiones en el ámbito militar o de la defensa, los Estados miembros cuyos representantes en el Consejo hayan efectuado una declaración formal de abstención constructiva:","o":["estarán obligados a contribuir con una cuota reducida.","no estarán obligados a contribuir a su financiación.","contribuirán únicamente a los gastos administrativos.","quedarán excluidos de la votación sobre el presupuesto."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no estarán obligados a contribuir a su financiación</mark></span>El <span class=\"ref-norma\">art. 41.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no estarán obligados a contribuir a su financiación\"</span>. Los Estados con abstención constructiva no contribuyen a la financiación militar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3433","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, establecerán mediante reglamentos el estatuto de los partidos políticos a escala europea y, en particular:","o":["las normas relativas a su financiación.","las normas relativas a su inscripción en un registro.","las normas relativas a su control por el Tribunal de Cuentas.","las normas relativas a su programa electoral común."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las normas relativas a su financiación</mark></span>El <span class=\"ref-norma\">art. 224 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"y en particular las normas relativas a su financiación\"</span>. Estatuto de los partidos europeos y normas de financiación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 63 a 66 TFUE — Capitales y pagos ✱","q":[{"i":"3-110","p":"Tratado de Funcionamiento de la Unión Europea. Política monetaria y económica. Cuando los movimientos excepcionales de capitales con destino a terceros países o procedentes de ellos causen, o amenacen causar, dificultades graves para el funcionamiento de la unión económica y monetaria:","o":["La Comisión, a propuesta del Consejo y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias.","El Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias.","El Banco Central Europeo, a propuesta de la Comisión y previa consulta al Consejo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias.","La Comisión, previa consulta al Banco Nacional, podrá adoptar respecto a terceros países, por un plazo que no sea superior a siete meses, cualquier medida de salvaguardia necesaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias</mark></span>El <span class=\"ref-norma\">art. 66 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cuando en circunstancias excepcionales los movimientos de capitales con destino a terceros países o procedentes de ellos causen, o amenacen causar, dificultades graves para el funcionamiento de la unión económica y monetaria, el Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias\"</span>. El artículo 66 del TFUE establece que, ante dificultades graves para el funcionamiento de la unión económica y monetaria derivadas de movimientos de capitales con terceros países, el Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar medidas de salvaguardia por un plazo no superior a seis meses."},{"i":"3-155","p":"Tratado de la Unión Europea. La Unión dispone de un marco institucional que tiene como finalidad promover sus valores, perseguir sus objetivos, defender sus intereses, los de sus ciudadanos y los de los Estados miembros, así como garantizar la coherencia, eficacia y continuidad de sus políticas y acciones. Las instituciones de la Unión son, entre otros: señale la CORRECTA.","o":["El Comité Económico y Social.","El Comité de las Regiones.","El Banco Central Europeo.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Banco Central Europeo</mark></span>El <span class=\"ref-norma\">art. 13.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"Las instituciones de la Unión son: El PARLAMENTO EUROPEO, El CONSEJO EUROPEO, El CONSEJO, La COMISIÓN EUROPEA (denominada en lo sucesivo “Comisión”), El TRIBUNAL DE JUSTICIA DE LA UNIÓN EUROPEA, El BANCO CENTRAL EUROPEO, El TRIBUNAL DE CUENTAS\"</span>. Solo el Banco Central Europeo es institución de la Unión; el Comité Económico y Social y el Comité de las Regiones son órganos consultivos que asisten al Parlamento Europeo, al Consejo y a la Comisión (art. 13.4). Por tanto «Todas son correctas» es falsa."},{"i":"3-240","p":"Tratado de Funcionamiento de la Unión Europea. Cuando en circunstancias excepcionales los movimientos de capitales con destino a terceros países o procedentes de ellos causen, o amenacen causar, dificultades graves para el funcionamiento de la unión económica y monetaria, el Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a _____ las medidas de salvaguarda estrictamente necesarias.","o":["6 meses.","2 meses.","3 meses.","1 año."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">6 meses</mark></span>El <span class=\"ref-norma\">art. 66 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Cuando en circunstancias excepcionales los movimientos de capitales con destino a terceros países o procedentes de ellos causen, o amenacen causar, dificultades graves para el funcionamiento de la unión económica y monetaria, el Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar respecto a terceros países, por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias\"</span>. El artículo 66 del TFUE establece que, ante dificultades graves para el funcionamiento de la unión económica y monetaria, el Consejo podrá adoptar respecto a terceros países, por un plazo no superior a seis meses, las medidas de salvaguardia estrictamente necesarias."},{"i":"3-348","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Capital y pagos. Sólo el Consejo, con arreglo a un procedimiento legislativo especial, podrá establecer medidas que supongan un retroceso en el Derecho de la Unión respecto de la liberalización de los movimientos de capitales con destino a terceros países o procedentes de ellos. Se pronunciará:","o":["Por mayoría cualificada y previa consulta al Parlamento Europeo.","Por unanimidad y previa consulta al Parlamento Europeo.","Por unanimidad y previa aprobación del Parlamento Europeo.","Por mayoría simple y previa consulta a la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por unanimidad y previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 64 del TFUE</span> dispone: <span class=\"ref-concepto\">\"sólo el Consejo, con arreglo a un procedimiento legislativo especial, por unanimidad y previa consulta al Parlamento Europeo\"</span>. Unanimidad y consulta al Parlamento Europeo."},{"i":"3-ia-3002","p":"Tratado de la Unión Europea. Entrada en vigor. El Tratado de la Unión Europea entró en vigor el:","o":["1 de enero de 1993.","1 de diciembre de 2009, salvo que se disponga otra cosa en la normativa aplicable.","1 de enero de 1986.","1 de noviembre de 1993."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">1 de noviembre de 1993</mark></span>El <span class=\"ref-norma\">ficha del TUE de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Entrada en vigor: 1 de noviembre de 1993\"</span>. Entró en vigor el 1 de noviembre de 1993; el Tratado de Lisboa lo hizo el 1 de diciembre de 2009. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3313","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. En el marco de las disposiciones del capítulo sobre capital y pagos, quedan prohibidas todas las restricciones a los movimientos de capitales y a los pagos:","o":["entre Estados miembros y entre Estados miembros y terceros países.","entre Estados miembros y entre los residentes de la zona del euro, en los términos que establezca la propia norma.","entre Estados miembros, con excepción de las inversiones directas.","entre los Estados miembros que hayan adoptado el euro como moneda."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre Estados miembros y entre Estados miembros y terceros países</mark></span>El <span class=\"ref-norma\">art. 63 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"quedan prohibidas todas las restricciones a los movimientos de capitales entre Estados miembros y entre Estados miembros y terceros países\"</span>. La prohibición alcanza también a los movimientos con terceros países. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3314","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. La prohibición de restricciones se entenderá sin perjuicio de la aplicación a terceros países de las restricciones que existan el 31 de diciembre de 1993; respecto de las restricciones existentes en virtud de la legislación nacional en Bulgaria, Estonia y Hungría, la fecha aplicable será:","o":["el 31 de diciembre de 2002, salvo que se disponga otra cosa en la normativa aplicable.","el 31 de diciembre de 1995.","el 31 de diciembre de 2004.","el 31 de diciembre de 1999."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el 31 de diciembre de 1999</mark></span>El <span class=\"ref-norma\">art. 64.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la fecha aplicable será el 31 de diciembre de 1999\"</span>. 1993 con carácter general; 1999 para Bulgaria, Estonia y Hungría; 2002 para Croacia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3315","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. Respecto de las restricciones existentes en Croacia en virtud de la legislación nacional, la fecha aplicable para los movimientos de capitales con destino a terceros países o procedentes de ellos será:","o":["el 31 de diciembre de 1999, conforme al procedimiento que se establezca reglamentariamente.","el 31 de diciembre de 1993.","el 31 de diciembre de 2002.","el 31 de diciembre de 2004."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el 31 de diciembre de 2002</mark></span>El <span class=\"ref-norma\">art. 64.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la fecha aplicable será el 31 de diciembre de 2002\"</span>. Para Croacia, el 31 de diciembre de 2002. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3316","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. Sólo el Consejo, con arreglo a un procedimiento legislativo especial, podrá establecer medidas que supongan un retroceso en el Derecho de la Unión respecto de la liberalización de los movimientos de capitales con destino a terceros países o procedentes de ellos, y lo hará:","o":["por mayoría cualificada y previa aprobación del Parlamento Europeo.","por unanimidad y previa consulta al Parlamento Europeo.","por unanimidad y previa aprobación del Parlamento Europeo.","por mayoría cualificada y previa consulta al Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad y previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 64.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por unanimidad y previa consulta al Parlamento Europeo, podrá establecer medidas que supongan un retroceso\"</span>. Procedimiento legislativo especial: unanimidad y consulta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3318","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. Las medidas y procedimientos que los Estados miembros pueden aplicar en materia de capitales no deberán constituir ni un medio de discriminación arbitraria ni:","o":["una limitación desproporcionada de la libre prestación de servicios financieros.","un obstáculo al ejercicio del derecho de establecimiento de las sociedades.","una carga excesiva para la supervisión prudencial de las entidades financieras.","una restricción encubierta de la libre circulación de capitales y pagos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una restricción encubierta de la libre circulación de capitales y pagos</mark></span>El <span class=\"ref-norma\">art. 65.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"ni un medio de discriminación arbitraria ni una restricción encubierta de la libre circulación de capitales y pagos\"</span>. No pueden ser discriminación arbitraria ni restricción encubierta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3320","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. Cuando en circunstancias excepcionales los movimientos de capitales con destino a terceros países o procedentes de ellos causen, o amenacen causar, dificultades graves para el funcionamiento de la unión económica y monetaria, el Consejo, a propuesta de la Comisión y previa consulta al Banco Central Europeo, podrá adoptar medidas de salvaguardia por un plazo que no sea superior a:","o":["tres meses.","seis meses.","un año.","dieciocho meses."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">seis meses</mark></span>El <span class=\"ref-norma\">art. 66 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por un plazo que no sea superior a seis meses, las medidas de salvaguardia estrictamente necesarias\"</span>. Medidas de salvaguardia por un máximo de seis meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3505","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo procederá a la discusión, en sesión pública, del informe general anual que le presentará:","o":["la Comisión.","el Consejo.","el Consejo Europeo.","el Defensor del Pueblo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Comisión</mark></span>El <span class=\"ref-norma\">art. 233 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"del informe general anual que le pre-sentará la Comisión\"</span>. El informe anual lo presenta la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3627","p":"Tratado de Funcionamiento de la Unión Europea. Banco Europeo de Inversiones y SEBC. El Tribunal de Justicia será competente para conocer de los litigios relativos al cumplimiento por parte de los bancos centrales nacionales de las obligaciones que se derivan de los Tratados y de los Estatutos del SEBC y del BCE; frente a los bancos centrales nacionales, dispondrá de los poderes que se reconocen a la Comisión respecto de los Estados miembros:","o":["el Comité Ejecutivo del Banco Central Europeo.","el Consejo General del Banco Central Europeo.","el Consejo de Gobierno del Banco Central Europeo.","la Comisión Europea junto con el Banco Central Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el Consejo de Gobierno del Banco Central Europeo</mark></span>El <span class=\"ref-norma\">art. 271 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo de Gobierno del Banco Central Europeo dispondrá a este respecto, frente a los bancos centrales nacionales, de los poderes que\"</span>. Es el Consejo de Gobierno del BCE. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3641","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos. Las normas relativas a la naturaleza de la composición de estos Comités serán revisadas periódicamente por el Consejo para tener en cuenta la evolución económica, social y demográfica en la Unión; el Consejo adoptará decisiones a tal efecto:","o":["a propuesta de la Comisión.","a iniciativa del Parlamento Europeo.","a propuesta de los Comités.","a iniciativa de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a propuesta de la Comisión</mark></span>El <span class=\"ref-norma\">art. 300.5 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo, a propuesta de la Comisión, adoptará decisiones a tal efecto\"</span>. A propuesta de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — Competencias, funciones del Estado y cooperación leal ✱","q":[{"i":"3-112","p":"Tratado de la Unión Europea. ¿Conforme a qué principio la Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados?","o":["Al principio de ayuda recíproca.","Al principio de cooperación leal.","Al principio de colaboración necesaria.","Al principio de colaboración."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al principio de cooperación leal</mark></span>El <span class=\"ref-norma\">art. 4.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Conforme al principio de cooperación leal, la Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados\"</span>. El artículo 4.3 del TUE recoge el principio de cooperación leal, conforme al cual la Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados."},{"i":"3-137","p":"Tratados de la Unión Europea. La Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados, conforme al principio de:","o":["Cooperación leal.","Subsidiariedad.","Proporcionalidad.","Todas son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cooperación leal</mark></span>El <span class=\"ref-norma\">art. 4.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Conforme al principio de cooperación leal, la Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados\"</span>. El artículo 4.3 del TUE recoge el principio de cooperación leal, conforme al cual la Unión y los Estados miembros se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados."},{"i":"3-ia-3017","p":"Tratado de la Unión Europea. Principios que establecen y regulan el ejercicio de las competencias. Toda competencia no atribuida a la Unión en los Tratados corresponde:","o":["a los Estados miembros.","a las regiones de los Estados miembros.","al Consejo, por decisión unánime.","a los Parlamentos nacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 4.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"toda competencia no atribuida a la Unión en los Tra-tados corresponde a los Estados miembros\"</span>. Las competencias no atribuidas permanecen en los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3018","p":"Tratado de la Unión Europea. Principios que establecen y regulan el ejercicio de las competencias. La Unión respetará la igualdad de los Estados miembros ante los Tratados, así como su identidad nacional, inherente a las estructuras fundamentales políticas y constitucionales de éstos, también en lo referente a:","o":["la organización territorial del Estado.","la distribución de competencias internas.","la forma política del Estado.","la autonomía local y regional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la autonomía local y regional</mark></span>El <span class=\"ref-norma\">art. 4.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"también en lo referente a la autonomía local y regional\"</span>. Se respeta también la autonomía local y regional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3019","p":"Tratado de la Unión Europea. Principios que establecen y regulan el ejercicio de las competencias. La Unión respetará las funciones esenciales del Estado, especialmente las que tienen por objeto garantizar su integridad territorial, mantener el orden público y salvaguardar la seguridad nacional; en particular, la seguridad nacional:","o":["seguirá siendo responsabilidad compartida entre la Unión y los Estados miembros.","será coordinada por la Unión a través de sus instituciones competentes.","seguirá siendo responsabilidad exclusiva de cada Estado miembro.","será garantizada por la Unión en las situaciones de especial gravedad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">seguirá siendo responsabilidad exclusiva de cada Estado miembro</mark></span>El <span class=\"ref-norma\">art. 4.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la seguridad nacional seguirá siendo responsabilidad exclusiva de cada Estado miembro\"</span>. La seguridad nacional es responsabilidad exclusiva de cada Estado miembro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3020","p":"Tratado de la Unión Europea. Principios que establecen y regulan el ejercicio de las competencias. Conforme al principio de cooperación leal, la Unión y los Estados miembros:","o":["se informarán y consultarán mutuamente antes de adoptar medidas que afecten a los Tratados.","se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados.","se coordinarán y apoyarán mutuamente en el ejercicio de sus competencias respectivas.","se respetarán y complementarán mutuamente en el cumplimiento de sus obligaciones internacionales, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se respetarán y asistirán mutuamente en el cumplimiento de las misiones derivadas de los Tratados</mark></span>El <span class=\"ref-norma\">art. 4.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Conforme al principio de cooperación leal, la Unión y los Estados miembros se respetarán y asistirán\"</span>. La cooperación leal implica respeto y asistencia mutuos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3050","p":"Tratado de la Unión Europea. Marco institucional. Cada institución actuará dentro de los límites de las atribuciones que le confieren los Tratados, con arreglo a los procedimientos, condiciones y fines establecidos en los mismos; las instituciones mantendrán entre sí:","o":["una cooperación activa.","una coordinación permanente.","un diálogo institucional regular.","una cooperación leal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una cooperación leal</mark></span>El <span class=\"ref-norma\">art. 13.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Las instituciones mantendrán entre sí una cooperación leal\"</span>. La cooperación entre instituciones es leal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 82 y 83 TFUE — Cooperación judicial penal ✱","q":[{"i":"3-119","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas tendentes a: Señale la incorrecta.","o":["Reforzar e Intensificar solo los conflictos de jurisdicción entre los Estados miembros.","Establecer normas y procedimientos para garantizar el reconocimiento en toda la Unión de las sentencias y resoluciones judiciales en todas sus formas.","Apoyar la formación de magistrados y del personal al servicio de la administración de justicia.","Facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento penal y de la ejecución de resoluciones."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reforzar e Intensificar solo los conflictos de jurisdicción entre los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 82.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas tendentes a: a) \u0007establecer normas y procedimientos para garantizar el reconocimiento en toda la Unión de las sentencias y resoluciones judiciales en todas sus formas; b) \u0007prevenir y resolver los conflictos de jurisdicción entre los Estados miembros\"</span>. La opción correcta es la A, por ser la incorrecta. El artículo 82.1 del TFUE atribuye al Parlamento Europeo y al Consejo la facultad de prevenir y resolver los conflictos de jurisdicción entre los Estados miembros, no de 'reforzar e intensificar solo' dichos conflictos como afirma erróneamente la opción A."},{"i":"3-271","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas tendentes a: señale la INCORRECTA.","o":["Establecer normas y procedimientos para garantizar el reconocimiento en toda la Unión de las sentencias y resoluciones judiciales en todas sus formas.","Prevenir y resolver los conflictos de jurisdicción entre los Estados miembros.","Apoyar la formación de magistrados y del personal al servicio de la administración de justicia.","Facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento civil y de la ejecución de resoluciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento civil y de la ejecución de resoluciones</mark></span>El <span class=\"ref-norma\">art. 82.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento penal y de la ejecución de resoluciones\"</span>. El artículo 82.1.d) del TFUE se refiere a facilitar esa cooperación en el marco del procedimiento penal, no civil, por lo que esa formulación resulta incorrecta."},{"i":"3-298","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo y el Consejo podrán establecer, mediante directivas adoptadas con arreglo al procedimiento legislativo ordinario, normas mínimas relativas a la definición de las infracciones penales y de las sanciones en ámbitos delictivos que sean de especial gravedad y tengan una dimensión transfronteriza derivada del carácter o de las repercusiones de dichas infracciones o de una necesidad particular de combatirlas según criterios comunes. Estos ámbitos delictivos son los siguientes: señale la INCORRECTA.","o":["La trata de seres humanos y la explotación sexual de mujeres y niños.","Delitos contra la vida de las personas.","El tráfico ilícito de drogas.","Delincuencia organizada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Delitos contra la vida de las personas</mark></span>El <span class=\"ref-norma\">art. 83.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el terrorismo, la trata de seres humanos y la explotación sexual de mujeres y niños, el tráfico ilícito de drogas, el tráfico ilícito de armas, el blanqueo de capitales, la corrupción, la falsificación de medios de pago, la delincuencia informática y la delincuencia organizada\"</span>. Los «delitos contra la vida de las personas» no figuran entre los ámbitos delictivos del art. 83.1; la trata de seres humanos y la explotación sexual de mujeres y niños sí. La INCORRECTA es, por tanto, la B."},{"i":"3-ia-3405","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas tendentes a establecer normas y procedimientos para garantizar el reconocimiento en toda la Unión de las sentencias y resoluciones judiciales, prevenir y resolver los conflictos de jurisdicción entre los Estados miembros, apoyar la formación de magistrados y:","o":["facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento penal y de la ejecución de resoluciones.","establecer un registro europeo de antecedentes penales de los condenados en los Estados miembros, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","crear equipos conjuntos de investigación con participación de Europol y de Eurojust.","fijar reglas comunes sobre la ejecución de las penas privativas de libertad en la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento penal y de la ejecución de resoluciones</mark></span>El <span class=\"ref-norma\">art. 82.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"facilitar la cooperación entre las autoridades judiciales o equivalentes de los Estados miembros en el marco del procedimiento penal y de la ejecución de resoluciones\"</span>. La cuarta medida es facilitar la cooperación entre autoridades judiciales en el procedimiento penal y la ejecución de resoluciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3406","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Las normas mínimas que el Parlamento Europeo y el Consejo pueden establecer mediante directivas para facilitar el reconocimiento mutuo de las resoluciones judiciales y la cooperación en asuntos penales con dimensión transfronteriza se referirán a la admisibilidad mutua de pruebas entre los Estados miembros, los derechos de las personas durante el procedimiento penal, los derechos de las víctimas de los delitos y:","o":["las condiciones de la detención provisional y de la prisión preventiva en los Estados miembros, salvo que se disponga otra cosa en la normativa aplicable.","las reglas de competencia judicial para el enjuiciamiento de las infracciones transfronterizas.","los plazos de prescripción de las infracciones penales con repercusión transfronteriza.","otros elementos específicos del procedimiento penal que el Consejo habrá determinado previamente mediante una decisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">otros elementos específicos del procedimiento penal que el Consejo habrá determinado previamente mediante una decisión</mark></span>El <span class=\"ref-norma\">art. 82.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"otros elementos específicos del procedimiento penal, que el Consejo habrá determinado pre\"</span>. Cuarta materia: otros elementos específicos del procedimiento penal, determinados previamente por el Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3407","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Para adoptar la decisión que determine otros elementos específicos del procedimiento penal sobre los que establecer normas mínimas, el Consejo se pronunciará:","o":["por mayoría cualificada, previa aprobación del Parlamento Europeo.","por unanimidad, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, previa consulta al Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por unanimidad, previa aprobación del Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 82.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Para la adopción de esta decisión, el Consejo se pronunciará por unanimidad, previa aprobación del Parlamento Europeo\"</span>. Unanimidad y aprobación del Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3410","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Si no hay acuerdo dentro del plazo del freno de emergencia y al menos nueve Estados miembros quieren establecer una cooperación reforzada con arreglo al proyecto de directiva de que se trate, lo comunicarán al Parlamento Europeo, al Consejo y a la Comisión; en tal caso:","o":["el Consejo deberá autorizar la cooperación reforzada por mayoría cualificada.","el Parlamento Europeo deberá aprobar la cooperación reforzada por mayoría absoluta.","la Comisión deberá presentar una nueva propuesta para su examen por el Consejo.","la autorización para iniciar la cooperación reforzada se considerará concedida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la autorización para iniciar la cooperación reforzada se considerará concedida</mark></span>El <span class=\"ref-norma\">art. 82.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"En tal caso, la autorización para iniciar la cooperación\"</span>. La autorización de cooperación reforzada se considera concedida automáticamente. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3411","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo podrán establecer, mediante directivas adoptadas con arreglo al procedimiento legislativo ordinario, normas mínimas relativas a la definición de las infracciones penales y de las sanciones en ámbitos delictivos que sean de especial gravedad y tengan una dimensión transfronteriza; entre ellos figuran el terrorismo, la trata de seres humanos y la explotación sexual de mujeres y niños, el tráfico ilícito de drogas y de armas y:","o":["el blanqueo de capitales, el fraude fiscal, la falsificación de medios de pago, la ciberdelincuencia y el crimen organizado, conforme al procedimiento que se establezca reglamentariamente.","la piratería, la corrupción, la falsificación de medios de pago, la delincuencia informática y la delincuencia organizada.","el blanqueo de capitales, la corrupción, la falsificación de medios de pago, la delincuencia informática y la delincuencia organizada.","el blanqueo de capitales, la corrupción, el tráfico de órganos, la delincuencia informática y la delincuencia ambiental."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el blanqueo de capitales, la corrupción, la falsificación de medios de pago, la delincuencia informática y la delincuencia organizada</mark></span>El <span class=\"ref-norma\">art. 83.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el blanqueo de capitales, la corrupción, la falsificación de medios de pago, la delincuencia informática y la delincuencia organizada\"</span>. Son diez ámbitos: terrorismo, trata y explotación sexual, drogas, armas, blanqueo, corrupción, falsificación de medios de pago, delincuencia informática y organizada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3412","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Teniendo en cuenta la evolución de la delincuencia, el Consejo podrá adoptar una decisión que determine otros ámbitos delictivos que respondan a los criterios previstos; se pronunciará:","o":["por mayoría cualificada, previa aprobación del Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por unanimidad, previa consulta al Parlamento Europeo.","por mayoría cualificada, a propuesta de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por unanimidad, previa aprobación del Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 83.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se pronunciará por unanimidad, previa aprobación del Parlamento Europeo\"</span>. Unanimidad y aprobación del Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3414","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Cuando un miembro del Consejo considere que un proyecto de directiva sobre infracciones y sanciones penales afecta a aspectos fundamentales de su sistema de justicia penal, podrá solicitar que el asunto se remita al Consejo Europeo; si no hay acuerdo en el mismo plazo y al menos nueve Estados miembros quieren establecer una cooperación reforzada:","o":["lo comunicarán al Consejo Europeo y esperarán su autorización por unanimidad.","lo comunicarán a la Comisión y esperarán su propuesta de cooperación reforzada.","lo comunicarán al Parlamento Europeo y esperarán su aprobación por mayoría absoluta, salvo que se disponga otra cosa en la normativa aplicable.","lo comunicarán al Parlamento Europeo, al Consejo y a la Comisión y la autorización se considerará concedida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">lo comunicarán al Parlamento Europeo, al Consejo y a la Comisión y la autorización se considerará concedida</mark></span>El <span class=\"ref-norma\">art. 83.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"lo comunicarán al Par-lamento Europeo, al Consejo y a la Comisión. En tal caso, la autorización para iniciar la cooperación\"</span>. Se comunica a las tres instituciones y la autorización se considera concedida. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 50 TFUE — Medidas de establecimiento","q":[{"i":"3-125","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. A efectos de alcanzar la libertad de establecimiento en una determinada actividad:","o":["El Parlamento Europeo decidirá, mediante directivas, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social.","El Parlamento Europeo y el Consejo decidirán, mediante reglamentos, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social.","El Parlamento Europeo y el Consejo decidirán, mediante directivas, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social.","El Consejo decidirá, mediante directivas o Reglamentos, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo decidirán, mediante directivas, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social</mark></span>El <span class=\"ref-norma\">art. 50.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A efectos de alcanzar la libertad de establecimiento en una determinada actividad, el Parlamento Europeo y el Consejo decidirán, mediante directivas, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social\"</span>. El artículo 50.1 del TFUE establece que, para alcanzar la libertad de establecimiento en una determinada actividad, el Parlamento Europeo y el Consejo decidirán, mediante directivas, con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social."},{"i":"3-154","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión ejercerán las funciones que les atribuyen las disposiciones precedentes, en particular: Señale la correcta.","o":["Dispondrán, con prioridad, de las actividades en los que la libertad de establecimiento contribuirá de manera especialmente útil al desarrollo de la producción y los intercambios.","Asegurando una estrecha colaboración entre las administraciones nacionales competentes a fin de conocer las situaciones particulares, dentro de la Unión, de los diferentes estupefacientes.","Eliminarán aquellos procedimientos y prácticas administrativas que resulten de la legislación nacional o de acuerdos celebrados con anterioridad entre los Estados miembros, cuyo mantenimiento suponga un obstáculo para la libertad de establecimiento.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Eliminarán aquellos procedimientos y prácticas administrativas que resulten de la legislación nacional o de acuerdos celebrados con anterioridad entre los Estados miembros, cuyo mantenimiento suponga un obstáculo para la libertad de establecimiento</mark></span>A está deformada y B habla de «estupefacientes» (el texto dice «distintas actividades afectadas»), por lo que no todas son correctas. Según el <span class=\"ref-norma\">art. 50.2.c) del TFUE</span>: <span class=\"ref-concepto\">\"c) eliminando aquellos procedimientos y prácticas administrativos que resulten de la legislación nacional o de acuerdos celebrados con anterioridad entre los Estados miembros, cuyo mantenimiento suponga un obstáculo para la libertad de establecimiento;\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3248","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. A efectos de alcanzar la libertad de establecimiento en una determinada actividad, el Parlamento Europeo y el Consejo decidirán, mediante directivas, con arreglo al procedimiento legislativo ordinario y:","o":["previa consulta al Comité de las Regiones, sin perjuicio de lo dispuesto en otras disposiciones.","previa consulta al Comité Económico y Social.","previa aprobación del Consejo Europeo.","a propuesta del Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">previa consulta al Comité Económico y Social</mark></span>El <span class=\"ref-norma\">art. 50.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con arreglo al procedimiento legislativo ordinario y previa consulta al Comité Económico y Social\"</span>. Mediante directivas y previa consulta al Comité Económico y Social. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 27 — El Alto Representante en la PESC ✱","q":[{"i":"3-130","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. En el ejercicio de su mandato, el Alto Representante se apoyará en un servicio europeo de acción exterior. La organización y el funcionamiento del servicio europeo de acción exterior se establecerán mediante:","o":["Decisión del Parlamento Europeo.","Directiva del Consejo Europeo.","Decisión del Consejo.","Directiva de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Decisión del Consejo</mark></span>El <span class=\"ref-norma\">art. 27.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"La organización y el funcionamiento del servicio europeo de acción exterior se establecerán mediante decisión del Consejo, que se pronunciará a propuesta del Alto Representante, previa consulta al Parlamento Europeo y previa aprobación de la Comisión\"</span>. El artículo 27.3 del TUE establece que la organización y el funcionamiento del servicio europeo de acción exterior se establecerán mediante decisión del Consejo, a propuesta del Alto Representante, previa consulta al Parlamento Europeo y previa aprobación de la Comisión."},{"i":"3-237","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. En el ejercicio de su mandato, ¿en quién se apoyará el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad?","o":["En un servicio europeo de acción exterior.","En el Consejo de Asuntos Exteriores.","En Europol.","En el Tribunal de Justicia de la Unión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En un servicio europeo de acción exterior</mark></span>El <span class=\"ref-norma\">art. 27.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007En el ejercicio de su mandato, el Alto Representante se apoyará en un servicio europeo de acción exterior\"</span>. El artículo 27.3 del TUE establece que, en el ejercicio de su mandato, el Alto Representante se apoyará en un servicio europeo de acción exterior."},{"i":"3-ia-3150","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. El Alto Representante representará a la Unión en las materias concernientes a la política exterior y de seguridad común, dirigirá el diálogo político con terceros en nombre de la Unión y expresará:","o":["la posición del Consejo Europeo en las organizaciones internacionales y en las conferencias regionales.","la posición de la Comisión en las organizaciones internacionales y en los foros multilaterales.","la posición de los Estados miembros en las organizaciones internacionales y en las conferencias.","la posición de la Unión en las organizaciones internacionales y en las conferencias internacionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la posición de la Unión en las organizaciones internacionales y en las conferencias internacionales</mark></span>El <span class=\"ref-norma\">art. 27.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"expresará la posición de la Unión en las organizaciones internacionales y en las conferencias internacionales\"</span>. Expresa la posición de la Unión en organizaciones y conferencias internacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3151","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. En el ejercicio de su mandato, el Alto Representante se apoyará en un servicio europeo de acción exterior, cuya organización y funcionamiento se establecerán mediante decisión del Consejo, que se pronunciará:","o":["a propuesta de la Comisión, previa aprobación del Parlamento Europeo y previa consulta al Alto Representante, conforme al procedimiento que se establezca reglamentariamente.","a propuesta del Alto Representante, previa aprobación del Parlamento Europeo y previa consulta a la Comisión.","a propuesta del Alto Representante, previa consulta al Parlamento Europeo y previa aprobación de la Comisión.","a propuesta del Consejo Europeo, previa consulta al Parlamento Europeo y previa aprobación de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a propuesta del Alto Representante, previa consulta al Parlamento Europeo y previa aprobación de la Comisión</mark></span>El <span class=\"ref-norma\">art. 27.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"mediante decisión del Consejo, que se pronunciará a propuesta del Alto Representante, previa consulta al\"</span>. Propuesta del Alto Representante, consulta al Parlamento y aprobación de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3403","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia civil. El Consejo, a propuesta de la Comisión, podrá adoptar una decisión que determine los aspectos del Derecho de familia con repercusión transfronteriza que puedan ser objeto de actos adoptados mediante el procedimiento legislativo ordinario; si un Parlamento nacional notifica su oposición en los seis meses posteriores a la comunicación de la propuesta:","o":["la decisión se adoptará por mayoría cualificada.","la propuesta se remitirá al Consejo Europeo.","la decisión no será adoptada.","la decisión quedará suspendida durante seis meses."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la decisión no será adoptada</mark></span>El <span class=\"ref-norma\">art. 81.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"En caso de que un Parlamento nacional notifique su oposición en los seis meses posteriores a la comunicación, la decisión no será adoptada\"</span>. Una sola oposición de un Parlamento nacional en seis meses impide la decisión (cláusula pasarela). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3638","p":"Tratado de Funcionamiento de la Unión Europea. Estatuto del Tribunal de Justicia. Para modificar el Estatuto del Tribunal de Justicia, el Parlamento Europeo y el Consejo se pronunciarán bien a petición del Tribunal de Justicia y previa consulta a la Comisión, bien:","o":["a propuesta del Consejo y previa aprobación del Tribunal de Justicia.","a iniciativa de los Estados miembros y previa consulta al Tribunal de Justicia.","a propuesta de la Comisión y previa aprobación del Tribunal de Justicia.","a propuesta de la Comisión y previa consulta al Tribunal de Justicia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a propuesta de la Comisión y previa consulta al Tribunal de Justicia</mark></span>El <span class=\"ref-norma\">art. 281 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"bien a petición del Tribunal de Justicia y previa consulta a la Comisión, bien a propuesta de la Comisión y previa consulta al Tribunal de Justicia\"</span>. Dos vías simétricas: petición del Tribunal con consulta a la Comisión, o propuesta de la Comisión con consulta al Tribunal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 235 y 236 TFUE — Consejo Europeo EXOF ✱","q":[{"i":"3-143","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. Disposiciones Institucionales. Instituciones. El Consejo Europeo. En caso de votación, cada miembro del Consejo Europeo podrá:","o":["Actuar en representación de uno solo de los demás miembros.","Actuar en representación de dos de los demás miembros.","Actuar en representación de tres de los demás miembros.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Actuar en representación de uno solo de los demás miembros</mark></span>El <span class=\"ref-norma\">art. 239 del TFUE</span> dispone: <span class=\"ref-concepto\">\"En caso de votación, cada miembro del Consejo podrá actuar en representación de uno solo de los demás miembros\"</span>. El artículo 235.1 del TFUE establece que, en caso de votación, cada miembro del Consejo Europeo podrá actuar en representación de uno solo de los demás miembros."},{"i":"3-227","p":"Tratado de Funcionamiento de la Unión Europea. Señale la incorrecta sobre el Consejo Europeo.","o":["En caso de votación, cada miembro del Consejo Europeo podrá actuar en representación de uno solo de los demás miembros.","El Presidente del Consejo Europeo y el Presidente de la Comisión participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación.","El Consejo Europeo estará asistido por la Secretaría General del Consejo.","El Consejo Europeo se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente del Consejo Europeo y el Presidente de la Comisión participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación</mark></span>El <span class=\"ref-norma\">art. 235.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Consejo Europeo y el Presidente de la Comisión no participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación\"</span>. (The Presidents of the Council and the Commission do not take part in the vote when the European Council votes.)"},{"i":"3-248","p":"Tratado de Funcionamiento de la Unión Europea. En Consejo Europeo. ¿Cómo se pronunciará el Consejo en las cuestiones de procedimiento y para la aprobación de su reglamento interno?","o":["Por consenso.","Por unanimidad.","Por mayoría simple.","Por mayoría cualificada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría simple</mark></span>El <span class=\"ref-norma\">art. 235.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno\"</span>. El artículo 240.3 del TFUE establece que el Consejo se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno."},{"i":"3-277","p":"Tratado de Funcionamiento de la Unión Europea. ¿Cómo se pronunciará el Consejo Europeo en las cuestiones de procedimiento y para la aprobación de su reglamento interno?","o":["Por consenso.","Por unanimidad.","Por mayoría simple.","Por mayoría cualificada."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría simple</mark></span>El <span class=\"ref-norma\">art. 235.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno\"</span>. El artículo 235.3 del TFUE establece que el Consejo Europeo se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno."},{"i":"3-ia-3509","p":"Tratado de Funcionamiento de la Unión Europea. Consejo Europeo. En caso de votación, cada miembro del Consejo Europeo podrá actuar en representación de uno solo de los demás miembros; el Presidente del Consejo Europeo y el Presidente de la Comisión:","o":["no participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación.","participarán en las votaciones del Consejo Europeo con voz pero sin voto.","participarán en las votaciones del Consejo Europeo con voto de calidad.","participarán solo en las votaciones por mayoría cualificada del Consejo Europeo, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación</mark></span>El <span class=\"ref-norma\">art. 235.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Consejo Europeo y el Presidente de la Comisión no participarán en las votaciones del Consejo Europeo cuando éste se pronuncie por votación\"</span>. Presidente del Consejo Europeo y Presidente de la Comisión no votan. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3510","p":"Tratado de Funcionamiento de la Unión Europea. Consejo Europeo. La abstención de los miembros presentes o representados del Consejo Europeo:","o":["impedirá la adopción de los acuerdos que requieran unanimidad.","se computará como voto favorable en los acuerdos por mayoría cualificada.","se computará como voto en contra en los acuerdos por consenso.","no obstará a la adopción de los acuerdos que requieran unanimidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no obstará a la adopción de los acuerdos que requieran unanimidad</mark></span>El <span class=\"ref-norma\">art. 235.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La abstención de los miembros presentes o representados no obstará a la adopción de los acuerdos del Consejo Europeo que requieran unanimidad\"</span>. La abstención no impide la unanimidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3512","p":"Tratado de Funcionamiento de la Unión Europea. Consejo Europeo. El Consejo Europeo adoptará por mayoría cualificada una decisión por la que se establezca la lista de las formaciones del Consejo, distintas de la de Asuntos Generales y la de Asuntos Exteriores, y una decisión relativa:","o":["a la composición de las formaciones del Consejo, con excepción de la de Asuntos Exteriores.","a la presidencia de las formaciones del Consejo, con excepción de la de Asuntos Exteriores.","a las competencias de las formaciones del Consejo, con excepción de la de Asuntos Generales.","al calendario de reuniones de las formaciones del Consejo, con excepción de la de Asuntos Exteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la presidencia de las formaciones del Consejo, con excepción de la de Asuntos Exteriores</mark></span>El <span class=\"ref-norma\">art. 236 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"una decisión relativa a la presidencia de las formaciones del Consejo, con excepción de la de Asun-tos Exteriores\"</span>. La presidencia de las formaciones del Consejo, salvo Asuntos Exteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3519","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. En caso de votación, cada miembro del Consejo podrá actuar en representación de:","o":["dos de los demás miembros.","cualquiera de los demás miembros.","uno solo de los demás miembros.","los miembros de su mismo grupo político."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">uno solo de los demás miembros</mark></span>El <span class=\"ref-norma\">art. 239 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"cada miembro del Consejo podrá actuar en representación de uno solo de los de-más miembros\"</span>. Solo puede representar a uno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 21 — Principios y objetivos de la acción exterior EXOF","q":[{"i":"3-158","p":"Tratado de la Unión Europea. Disposiciones generales relativas a la acción exterior de la Unión. La Unión definirá y ejecutará políticas comunes y acciones y se esforzará por lograr un alto grado de cooperación en todos los ámbitos de las relaciones internacionales con el fin de: Señale la INCORRECTA.","o":["Salvaguardar sus valores, intereses fundamentales, seguridad, independencia e integridad.","Consolidar y respaldar la democracia, el Estado de Derecho, los derechos humanos y los principios del Derecho internacional.","Incluir la integración de todos los países en la economía mundial, entre otras cosas mediante la supresión progresiva de los obstáculos al comercio nacional.","Contribuir a elaborar medidas internacionales de protección y mejora de la calidad del medio ambiente y de la gestión sostenible de los recursos naturales mundiales, para lograr el desarrollo sostenible2."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Incluir la integración de todos los países en la economía mundial, entre otras cosas mediante la supresión progresiva de los obstáculos al comercio nacional</mark></span>El <span class=\"ref-norma\">art. 21.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007fomentar la integración de todos los países en la economía mundial, entre otras cosas mediante la supresión progresiva de los obstáculos al comercio internacional; f) \u0007contribuir a elaborar medidas internacionales de protección y mejora de la calidad del medio ambiente y de la gestión sostenible de los recursos naturales mundiales, para lograr el desarrollo sostenible\"</span>. La opción correcta es la C, por ser la incorrecta. El artículo 21.2.e) del TUE se refiere a fomentar la integración de todos los países en la economía mundial mediante la supresión progresiva de los obstáculos al comercio internacional, y no al 'comercio nacional' como indica erróneamente la opción C."},{"i":"3-188","p":"Tratado de la Unión Europea. La acción de la Unión en la escena internacional se basará en los principios que han inspirado su creación, desarrollo y ampliación y que pretende fomentar en el resto del mundo: señale la INCORRECTA.","o":["La universalidad e indivisibilidad de los derechos humanos y de las libertades fundamentales.","El Estado de Derecho.","El respeto de la dignidad humana.","Los principios de proporcionalidad y subsidiariedad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los principios de proporcionalidad y subsidiariedad</mark></span>El <span class=\"ref-norma\">art. 21.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"La acción de la Unión en la escena internacional se basará en los principios que han inspirado su creación, desarrollo y ampliación y que pretende fomentar en el resto del mundo: la democracia, el Estado de Derecho, la universalidad e indivisibilidad de los derechos humanos y de las libertades fundamentales, el respeto de la dignidad humana, los principios de igualdad y solidaridad y el respeto de los principios de la Carta de las Naciones Unidas y del Derecho internacional\"</span>. La opción correcta es la D, por ser la incorrecta. El artículo 21.1 del TUE menciona como principios inspiradores de la acción exterior la democracia, el Estado de Derecho, la universalidad e indivisibilidad de los derechos humanos, el respeto de la dignidad humana, la igualdad y la solidaridad, pero no los principios de proporcionalidad y subsidiariedad, propios del ejercicio de competencias internas conforme al artículo 5."},{"i":"3-398","p":"Tratado de la Unión Europea. Principios y objetivos de la acción exterior. La Unión definirá y ejecutará políticas comunes y acciones y se esforzará por lograr un alto grado de cooperación en todos los ámbitos de las relaciones internacionales con el fin de apoyar el desarrollo sostenible en los planos económico, social y medioambiental de los países en desarrollo, con el objetivo fundamental de:","o":["Reducir la deuda exterior.","Garantizar la ayuda humanitaria.","Erradicar la pobreza.","Fomentar su integración en la economía mundial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Erradicar la pobreza</mark></span>El <span class=\"ref-norma\">art. 21.2.d del TUE</span> dispone: <span class=\"ref-concepto\">\"con el objetivo fundamental de erradicar la pobreza\"</span>. Objetivo fundamental del apoyo al desarrollo sostenible: erradicar la pobreza. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-399","p":"Tratado de la Unión Europea. Principios y objetivos de la acción exterior. La Unión definirá y ejecutará políticas comunes y acciones con el fin de fomentar la integración de todos los países en la economía mundial, entre otras cosas mediante:","o":["La supresión inmediata de los obstáculos al comercio internacional.","La supresión progresiva de los obstáculos al comercio internacional.","La creación de zonas de libre comercio con terceros países.","La armonización de las políticas arancelarias de los Estados miembros."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La supresión progresiva de los obstáculos al comercio internacional</mark></span>El <span class=\"ref-norma\">art. 21.2.e del TUE</span> dispone: <span class=\"ref-concepto\">\"fomentar la integración de todos los países en la economía mundial, entre otras cosas mediante la supresión progresiva de los obstáculos al comercio internacional\"</span>. Integración en la economía mundial mediante la supresión progresiva de obstáculos al comercio. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3015","p":"Tratado de la Unión Europea. Finalidad de la Unión Europea. En sus relaciones con el resto del mundo, la Unión afirmará y promoverá sus valores e intereses y contribuirá a la protección de sus ciudadanos; asimismo contribuirá al estricto respeto y al desarrollo del Derecho internacional, en particular el respeto de:","o":["los principios del Convenio Europeo de Derechos Humanos.","los principios del Estatuto de la Corte Penal Internacional.","los principios de la Carta de las Naciones Unidas.","los principios de la Declaración Universal de Derechos Humanos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los principios de la Carta de las Naciones Unidas</mark></span>El <span class=\"ref-norma\">art. 3.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en particular el respeto de los principios de la Carta de las Naciones Unidas\"</span>. Se alude a los principios de la Carta de las Naciones Unidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3133","p":"Tratado de la Unión Europea. Principios de la acción exterior. La acción de la Unión en la escena internacional se basará en los principios que han inspirado su creación, desarrollo y ampliación: la democracia, el Estado de Derecho, la universalidad e indivisibilidad de los derechos humanos y de las libertades fundamentales, el respeto de la dignidad humana, los principios de igualdad y solidaridad y:","o":["el respeto de los principios de la Carta de las Naciones Unidas y del Derecho internacional.","el respeto de los principios del Convenio Europeo y de la Declaración Universal, en los términos que establezca la propia norma.","la defensa de los principios de la paz y de la seguridad internacionales.","el respeto de los principios del Acta Final de Helsinki y de la Carta de París."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el respeto de los principios de la Carta de las Naciones Unidas y del Derecho internacional</mark></span>El <span class=\"ref-norma\">art. 21.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"los principios de igualdad y solidaridad y el respeto de los principios de la Carta de las Naciones Unidas y del Derecho internacional\"</span>. Cierra con el respeto de los principios de la Carta de la ONU y del Derecho internacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3134","p":"Tratado de la Unión Europea. Principios de la acción exterior. La Unión procurará desarrollar relaciones y crear asociaciones con los terceros países y con las organizaciones internacionales que compartan sus principios y propiciará:","o":["soluciones bilaterales a los problemas comunes, en particular con los países vecinos.","acuerdos regionales sobre los problemas comunes, en particular en el marco de la OSCE, salvo que se disponga otra cosa en la normativa aplicable.","soluciones consensuadas a los problemas comunes, en particular en el marco de la OTAN.","soluciones multilaterales a los problemas comunes, en particular en el marco de las Naciones Unidas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">soluciones multilaterales a los problemas comunes, en particular en el marco de las Naciones Unidas</mark></span>El <span class=\"ref-norma\">art. 21.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Propiciará soluciones multilaterales a los problemas comunes, en particular en el marco\"</span>. Soluciones multilaterales, en particular en el marco de las Naciones Unidas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3135","p":"Tratado de la Unión Europea. Principios de la acción exterior. Entre los objetivos de la acción exterior figura mantener la paz, prevenir los conflictos y fortalecer la seguridad internacional, conforme a los propósitos y principios de la Carta de las Naciones Unidas, así como a los principios del Acta Final de Helsinki y a:","o":["los principios de la Declaración de Barcelona, incluidos los relativos a la política de vecindad.","los objetivos del Tratado de Maastricht, incluidos los relacionados con la defensa común.","los objetivos de la Carta de París, incluidos los relacionados con las fronteras exteriores.","los principios del Convenio de Roma, incluidos los relativos a la seguridad colectiva."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los objetivos de la Carta de París, incluidos los relacionados con las fronteras exteriores</mark></span>El <span class=\"ref-norma\">art. 21.2.c de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"así como a los principios del Acta Final de Helsinki y a los objetivos de la Carta de París, incluidos los relacionados con las fronteras exteriores\"</span>. Acta Final de Helsinki y Carta de París. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3136","p":"Tratado de la Unión Europea. Principios de la acción exterior. Entre los objetivos de la acción exterior figura apoyar el desarrollo sostenible en los planos económico, social y medioambiental de los países en desarrollo, con el objetivo fundamental de:","o":["reducir la desigualdad.","erradicar la pobreza.","fomentar el comercio justo.","garantizar la seguridad alimentaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">erradicar la pobreza</mark></span>El <span class=\"ref-norma\">art. 21.2.d de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con el objetivo fundamental de erradicar la pobreza\"</span>. El objetivo fundamental es erradicar la pobreza. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3137","p":"Tratado de la Unión Europea. Principios de la acción exterior. Entre los objetivos de la acción exterior figuran fomentar la integración de todos los países en la economía mundial, contribuir a elaborar medidas internacionales de protección del medio ambiente, ayudar a las poblaciones que se enfrenten a catástrofes naturales o de origen humano y:","o":["promover un sistema internacional basado en una cooperación multilateral sólida y en una buena gobernanza mundial.","promover un sistema internacional basado en el comercio libre y en una competencia leal mundial.","consolidar un sistema internacional basado en la seguridad colectiva y en una gobernanza regional, en los términos que establezca la propia norma.","impulsar un sistema internacional basado en la solidaridad y en una cooperación bilateral sólida."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">promover un sistema internacional basado en una cooperación multilateral sólida y en una buena gobernanza mundial</mark></span>El <span class=\"ref-norma\">art. 21.2.e a h de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"promover un sistema internacional basado en una cooperación multilateral sólida y en una\"</span>. El último objetivo es la cooperación multilateral sólida y la buena gobernanza mundial. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3338","p":"Tratado de Funcionamiento de la Unión Europea. Controles en las fronteras. El presente artículo no afectará a la competencia de los Estados miembros respecto de la delimitación geográfica de sus fronteras, de conformidad con:","o":["el Derecho de la Unión.","sus normas constitucionales.","los tratados bilaterales.","el Derecho internacional."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Derecho internacional</mark></span>El <span class=\"ref-norma\">art. 77.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"respecto de la delimitación geográfica de sus fronteras, de conformidad con el Derecho internacional\"</span>. La delimitación de fronteras sigue el Derecho internacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 81 TFUE — Cooperación judicial civil ✱","q":[{"i":"3-162","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia civil. La Unión desarrollará una cooperación judicial en asuntos civiles con repercusión transfronteriza, basada en el principio de reconocimiento mutuo de:","o":["Las resoluciones judiciales.","Las resoluciones extrajudiciales.","Las resoluciones administrativas y locales.","Las resoluciones judiciales y extrajudiciales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las resoluciones judiciales y extrajudiciales</mark></span>El <span class=\"ref-norma\">art. 81.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una cooperación judicial en asuntos civiles con repercusión transfronteriza, basada en el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales. Esta cooperación podrá incluir la adopción de medidas de aproximación de las disposiciones legales y reglamentarias de los Estados miembros\"</span>. El artículo 81.1 del TFUE establece que la Unión desarrollará una cooperación judicial en asuntos civiles con repercusión transfronteriza, basada en el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales."},{"i":"3-ia-3217","p":"Tratado de la Unión Europea. Financiación de la PESC. El Consejo adoptará una decisión por la que se establezcan los procedimientos específicos para garantizar el acceso rápido a los créditos del presupuesto de la Unión destinados a la financiación urgente de iniciativas en el marco de la PESC, y se pronunciará:","o":["previa consulta al Parlamento Europeo.","previa aprobación del Parlamento Europeo.","a propuesta de la Comisión Europea.","previo dictamen del Tribunal de Cuentas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 41.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará previa consulta al Parlamento Europeo\"</span>. Consulta previa al Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3402","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia civil. Las medidas relativas al Derecho de familia con repercusión transfronteriza se establecerán por el Consejo, con arreglo a un procedimiento legislativo especial, en el que el Consejo se pronunciará:","o":["por mayoría cualificada, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, previa aprobación del Parlamento Europeo.","por unanimidad, previa consulta al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por unanimidad, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 81.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"las medidas relativas al Derecho de familia con repercusión transfronteriza se establecerán por el Consejo, con arreglo a un procedimiento legislativo especial. El Consejo se pronunciará por unanimidad, previa consulta al Parlamento Europeo\"</span>. Derecho de familia: procedimiento legislativo especial, unanimidad y consulta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 49 TFUE — Derecho de establecimiento","q":[{"i":"3-163","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. La libertad de establecimiento comprenderá el acceso a las actividades: Señale la correcta.","o":["Asalariadas.","No asalariadas.","Por cuenta ajena.","Tanto las asalariadas como las no asalariadas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No asalariadas</mark></span>El <span class=\"ref-norma\">art. 49 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La libertad de establecimiento comprenderá el acceso a las actividades no asalariadas y su ejercicio, así como la constitución y gestión de empresas y, especialmente, de sociedades\"</span>. Las opciones A y C se refieren a actividades asalariadas (por cuenta ajena), que no son objeto de la libertad de establecimiento, y D mezcla ambas."},{"i":"3-ia-3246","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. En el marco de las disposiciones sobre el derecho de establecimiento, quedarán prohibidas las restricciones a la libertad de establecimiento de los nacionales de un Estado miembro en el territorio de otro Estado miembro; dicha prohibición se extenderá igualmente a las restricciones relativas a:","o":["la constitución de sociedades por los nacionales de un Estado miembro en el territorio de su propio Estado.","la adquisición de propiedades inmuebles por los nacionales de otro Estado miembro en el territorio del Estado, salvo que se disponga otra cosa en la normativa aplicable.","la contratación de personal por las empresas establecidas en el territorio de otro Estado miembro.","la apertura de agencias, sucursales o filiales por los nacionales de un Estado miembro establecidos en el territorio de otro Estado miembro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la apertura de agencias, sucursales o filiales por los nacionales de un Estado miembro establecidos en el territorio de otro Estado miembro</mark></span>El <span class=\"ref-norma\">art. 49 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"las restricciones relativas a la apertura de agencias, sucursales o filiales por los\"</span>. La prohibición incluye agencias, sucursales y filiales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3247","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. La libertad de establecimiento comprenderá el acceso a las actividades no asalariadas y su ejercicio, así como la constitución y gestión de empresas y, especialmente, de sociedades, en las condiciones fijadas por:","o":["la legislación del país de origen del nacional de otro Estado miembro.","la normativa de la Unión mediante reglamentos de aplicación directa.","la legislación del país de establecimiento para sus propios nacionales.","los acuerdos bilaterales entre el Estado de origen y el Estado de acogida."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la legislación del país de establecimiento para sus propios nacionales</mark></span>El <span class=\"ref-norma\">art. 49 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en las condiciones fijadas por la legislación del país de establecimiento para sus propios\"</span>. Se rige por la legislación del país de establecimiento aplicable a sus propios nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 48 TFUE — Seguridad social de los trabajadores migrantes ✱","q":[{"i":"3-208","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién adoptará, en materia de seguridad social, las medidas necesarias para el establecimiento de la libre circulación de los trabajadores, creando, en especial, un sistema que permita garantizar a los trabajadores migrantes por cuenta ajena y por cuenta propia, así como a sus derechohabientes, la acumulación de todos los periodos tomados en consideración por las distintas legislaciones nacionales para adquirir y conservar el derecho a las prestaciones sociales, así como para el cálculo de éstas?","o":["El Parlamento Europeo y el Consejo.","La Comisión.","El Consejo a propuesta del Parlamento Europeo.","El Parlamento Europeo a propuesta del Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo</mark></span>El <span class=\"ref-norma\">art. 48 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, adoptarán, en materia de seguridad social, las medidas necesarias para el establecimiento de la libre circulación de los trabajadores, creando, en especial, un sistema que permita garantizar a los trabajadores migrantes por cuenta ajena y por cuenta propia, así como a sus derechohabientes\"</span>. El artículo 48 del TFUE atribuye al Parlamento Europeo y al Consejo, con arreglo al procedimiento legislativo ordinario, la adopción de las medidas necesarias en materia de seguridad social para el establecimiento de la libre circulación de los trabajadores."},{"i":"3-323","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién adoptará, en materia de seguridad social, las medidas necesarias para el establecimiento de la libre circulación de los trabajadores, creando, en especial, un sistema que permita garantizar a los trabajadores migrantes por cuenta ajena y por cuenta propia, así como a sus derechohabientes, la acumulación de todos los periodos tomados en consideración por las distintas legislaciones nacionales para adquirir y conservar el derecho a las prestaciones sociales, así como para el cálculo de éstas?","o":["El Parlamento Europeo y el Consejo.","La Comisión.","El Consejo a propuesta del Parlamento Europeo.","El Parlamento Europeo a propuesta del Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo</mark></span>El <span class=\"ref-norma\">art. 48 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, adoptarán, en materia de seguridad social, las medidas necesarias para el establecimiento de la libre circulación de los trabajadores, creando, en especial, un sistema que permita garantizar a los trabajadores migrantes por cuenta ajena y por cuenta propia, así como a sus derechohabientes\"</span>. El artículo 48 TFUE atribuye esta competencia al Parlamento Europeo y al Consejo."},{"i":"3-ia-3244","p":"Tratado de Funcionamiento de la Unión Europea. Seguridad social de los trabajadores migrantes. El Parlamento Europeo y el Consejo adoptarán, en materia de seguridad social, las medidas necesarias para el establecimiento de la libre circulación de los trabajadores, creando un sistema que permita garantizar a los trabajadores migrantes la acumulación de todos los períodos tomados en consideración por las distintas legislaciones nacionales y:","o":["la equiparación de las prestaciones con las del Estado de origen del trabajador migrante.","el pago de las prestaciones a las personas que residan en los territorios de los Estados miembros.","la transferencia de las cotizaciones al Estado de origen del trabajador migrante.","el reconocimiento mutuo de las cualificaciones profesionales de los trabajadores migrantes, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el pago de las prestaciones a las personas que residan en los territorios de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 48 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el pago de las prestaciones a las personas que residan en los territorios de los Estados miembros\"</span>. Acumulación de períodos y pago de prestaciones a residentes en los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3245","p":"Tratado de Funcionamiento de la Unión Europea. Seguridad social de los trabajadores migrantes. Cuando un miembro del Consejo declare que un proyecto de acto legislativo en materia de seguridad social perjudica a aspectos importantes de su sistema o afecta a su equilibrio financiero, podrá solicitar que el asunto se remita al Consejo Europeo, en cuyo caso quedará suspendido el procedimiento legislativo ordinario; previa deliberación y en un plazo de cuatro meses a partir de dicha suspensión, el Consejo Europeo:","o":["devolverá el proyecto al Consejo, o no se pronunciará o pedirá a la Comisión que presente una nueva propuesta.","aprobará el proyecto por unanimidad, o lo rechazará y pondrá fin al procedimiento legislativo.","devolverá el proyecto al Parlamento Europeo, o pedirá al Consejo que lo modifique.","adoptará una decisión definitiva por mayoría cualificada, o pedirá un dictamen al Tribunal de Justicia, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">devolverá el proyecto al Consejo, o no se pronunciará o pedirá a la Comisión que presente una nueva propuesta</mark></span>El <span class=\"ref-norma\">art. 48 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Previa deliberación y en un plazo de cuatro meses a partir de dicha suspensión, el Consejo Europeo\"</span>. Es el freno de emergencia en seguridad social: cuatro meses; devolver, o no pronunciarse / nueva propuesta (el acto se considera no adoptado). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3409","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Cuando un miembro del Consejo considere que un proyecto de directiva sobre normas mínimas de procedimiento penal afecta a aspectos fundamentales de su sistema de justicia penal, podrá solicitar que el asunto se remita al Consejo Europeo, en cuyo caso quedará suspendido el procedimiento legislativo ordinario; el Consejo Europeo, en caso de que se alcance un consenso, devolverá el proyecto al Consejo en el plazo de:","o":["cuatro meses a partir de dicha suspensión.","tres meses a partir de dicha suspensión, en los términos que establezca la propia norma.","seis meses a partir de dicha suspensión.","dos meses a partir de dicha suspensión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuatro meses a partir de dicha suspensión</mark></span>El <span class=\"ref-norma\">art. 82.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Consejo Europeo, en el plazo de cuatro me\"</span>. Es el freno de emergencia: cuatro meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 16 — El Consejo · R7 EXOF ✱ R7","q":[{"i":"3-233","p":"Tratado de la Unión Europea. Instituciones de la Unión. Señale la INCORRECTA.","o":["El Consejo Europeo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa.","La Comisión velará por que se apliquen los Tratados y las medidas adoptadas por las instituciones en virtud de éstos.","El Consejo se reunirá en diferentes formaciones.","El número de miembros del Parlamento Europeo no excederá de setecientos cincuenta, más el Presidente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa</mark></span>El <span class=\"ref-norma\">art. 15.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo se pronunciará por consenso, excepto cuando los Tratados dispongan otra cosa\"</span>. (The European Council shall, as a rule, decide by consensus, except where the Treaties provide otherwise. The Council (of the European Union) decides by majority qualified as a rule.)"},{"i":"3-ia-3113","p":"Tratado de la Unión Europea. La Comisión. Los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto:","o":["cuando los Tratados dispongan otra cosa.","cuando lo decida el Consejo por unanimidad.","cuando lo solicite el Parlamento Europeo.","cuando lo proponga un tercio de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuando los Tratados dispongan otra cosa</mark></span>El <span class=\"ref-norma\">art. 17.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los Tratados dispongan otra cosa\"</span>. La Comisión tiene el monopolio de la iniciativa legislativa salvo disposición en contrario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3511","p":"Tratado de Funcionamiento de la Unión Europea. Consejo Europeo. El Consejo Europeo podrá invitar al Presidente del Parlamento Europeo a comparecer ante él, se pronunciará por mayoría simple en las cuestiones de procedimiento y para la aprobación de su reglamento interno, y estará asistido por:","o":["la Secretaría General de la Comisión.","una Secretaría propia dirigida por su Presidente.","la Secretaría General del Consejo.","la Secretaría General del Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Secretaría General del Consejo</mark></span>El <span class=\"ref-norma\">art. 235.2 a 4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo estará asistido por la Secretaría General del Consejo\"</span>. Lo asiste la Secretaría General del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3515","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. A partir del 1 de noviembre de 2014, cuando el Consejo no actúe a propuesta de la Comisión o del Alto Representante, la mayoría cualificada se definirá como un mínimo del 72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo:","o":["el 55 % de la población de la Unión, conforme al procedimiento que se establezca reglamentariamente.","el 62 % de la población de la Unión.","el 65 % de la población de la Unión.","el 72 % de la población de la Unión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el 65 % de la población de la Unión</mark></span>El <span class=\"ref-norma\">art. 238.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la mayoría cualificada se definirá como un mínimo del 72 % de los miembros del Consejo que represente a Estados miembros que reúnan como mínimo el 65 % de la población de la Unión\"</span>. Sin propuesta de la Comisión o del Alto Representante: 72 % de los miembros y 65 % de la población. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 244 a 250 TFUE — La Comisión · R24 EXOF ✱ R24","q":[{"i":"3-234","p":"Tratado de Funcionamiento de la Unión Europea. La Comisión. Señale la INCORRECTA.","o":["La Comisión establecerá su reglamento interno con objeto de asegurar su funcionamiento y el de sus servicios.","Los acuerdos de la Comisión se adoptarán por mayoría de sus miembros.","Aparte de los casos de renovación periódica y fallecimiento, el mandato de los miembros de la Comisión concluirá individualmente por dimisión voluntaria o cese.","Todo miembro de la Comisión que deje de reunir las condiciones necesarias para el ejercicio de sus funciones o haya cometido una falta podrá ser cesado por el Tribunal de Justicia, a instancia del Consejo, por mayoría simple, o de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todo miembro de la Comisión que deje de reunir las condiciones necesarias para el ejercicio de sus funciones o haya cometido una falta podrá ser cesado por el Tribunal de Justicia, a instancia del Consejo, por mayoría simple, o de la Comisión</mark></span>El <span class=\"ref-norma\">art. 247 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Todo miembro de la Comisión que deje de reunir las condiciones necesarias para el ejercicio de sus funciones o haya cometido una falta grave podrá ser cesado por el Tribunal de Justicia, a instancia del Consejo, por mayoría simple, o de la Comisión\"</span>. (The request for compulsory retirement or removal must be made by the Council or the Commission, but it is always the Court of Justice that makes the final decision.)"},{"i":"3-267","p":"Tratado de Funcionamiento de la Unión Europea. Aparte de los casos de renovación periódica y fallecimiento, el mandato de los miembros de la Comisión concluirá individualmente por:","o":["Enfermedad grave o cese.","Dimisión voluntaria o cese.","Dimisión voluntaria, cese o enfermedad grave.","Dimisión voluntaria o enfermedad grave."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dimisión voluntaria o cese</mark></span>El <span class=\"ref-norma\">art. 246 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Aparte de los casos de renovación periódica y fallecimiento, el mandato de los miembros de la Comisión concluirá individualmente por dimisión voluntaria o cese\"</span>. El artículo 246 del TFUE establece que, aparte de los casos de renovación periódica y fallecimiento, el mandato de los miembros de la Comisión concluirá individualmente por dimisión voluntaria o cese."},{"i":"3-370","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. La Comisión. La Comisión publicará todos los años, al menos un mes antes de la apertura del período de sesiones del Parlamento Europeo:","o":["Su reglamento interno, junto con el programa de trabajo anual.","Un informe de gestión presupuestaria de los servicios de la Comisión.","Un programa legislativo anual para el siguiente período de sesiones.","Un informe general sobre las actividades de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un informe general sobre las actividades de la Unión</mark></span>El <span class=\"ref-norma\">art. 249 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La Comisión publicará todos los años, al menos un mes antes de la apertura del período de sesiones del Parlamento Europeo, un informe general sobre las actividades de la Unión\"</span>. Informe general anual, al menos un mes antes."},{"i":"3-371","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. La Comisión. Los acuerdos de la Comisión se adoptarán:","o":["Por mayoría cualificada de sus miembros.","Por unanimidad de sus miembros.","Por mayoría de sus miembros.","Por mayoría de dos tercios de sus miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría de sus miembros</mark></span>El <span class=\"ref-norma\">art. 250 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los acuerdos de la Comisión se adoptarán por mayoría de sus miembros\"</span>. Mayoría de sus miembros; el reglamento interno fija el quórum."},{"i":"3-ia-3115","p":"Tratado de la Unión Europea. La Comisión. Los miembros de la Comisión no solicitarán ni aceptarán instrucciones de ningún gobierno, institución, órgano u organismo, y se abstendrán de:","o":["toda actividad profesional o política durante el ejercicio de su mandato, conforme al procedimiento que se establezca reglamentariamente.","toda declaración pública sobre las actividades de la Comisión.","todo acto incompatible con sus obligaciones o con el desempeño de sus funciones.","toda relación con los gobiernos de los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todo acto incompatible con sus obligaciones o con el desempeño de sus funciones</mark></span>El <span class=\"ref-norma\">art. 17.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se abstendrán de todo acto incompatible con sus obligaciones o con el desempeño de sus funciones\"</span>. Se abstienen de todo acto incompatible con sus obligaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3518","p":"Tratado de Funcionamiento de la Unión Europea. Consejo. Las abstenciones de los miembros presentes o representados del Consejo:","o":["impedirán la adopción de los acuerdos del Consejo que requieran unanimidad.","se computarán como votos en contra en las decisiones por mayoría cualificada, salvo que se disponga otra cosa en la normativa aplicable.","obligarán a repetir la votación en las decisiones por mayoría simple.","no impedirán la adopción de los acuerdos del Consejo que requieran unanimidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no impedirán la adopción de los acuerdos del Consejo que requieran unanimidad</mark></span>El <span class=\"ref-norma\">art. 238.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Las abstenciones de los miembros presentes o representados no impedirán la adopción de los acuerdos del Consejo que requieran unanimidad\"</span>. No impiden la unanimidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3525","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Los miembros de la Comisión serán elegidos mediante un sistema de rotación establecido por unanimidad por el Consejo Europeo, con la regla de que la diferencia entre el número total de los mandatos que ejerzan nacionales de dos determinados Estados miembros:","o":["nunca podrá ser superior a uno.","nunca podrá ser superior a dos.","podrá ser superior a uno por razones demográficas.","se fijará por el Consejo cada cinco años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">nunca podrá ser superior a uno</mark></span>El <span class=\"ref-norma\">art. 244 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la diferencia entre el número total de los mandatos que ejerzan nacionales de dos determinados Estados miembros nunca podrá ser superior a uno\"</span>. Rotación en rigurosa igualdad: diferencia máxima de un mandato. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3528","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Aparte de los casos de renovación periódica y fallecimiento, el mandato de los miembros de la Comisión concluirá individualmente por dimisión voluntaria o cese; el miembro dimisionario, cesado o fallecido será sustituido por el resto de su mandato por un nuevo miembro de la misma nacionalidad, nombrado por el Consejo:","o":["por unanimidad, previa aprobación del Parlamento Europeo.","de común acuerdo con el Presidente de la Comisión, previa consulta al Parlamento Europeo.","a propuesta del Consejo Europeo, previa consulta al Presidente de la Comisión, sin perjuicio de lo dispuesto en otras disposiciones.","por mayoría cualificada, de común acuerdo con el Alto Representante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">de común acuerdo con el Presidente de la Comisión, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 246 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"nombrado por el Consejo, de común acuerdo con el Presidente de la Comisión, previa consulta al Parlamento Europeo\"</span>. Nombra el Consejo de común acuerdo con el Presidente de la Comisión y previa consulta al Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3530","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Todo miembro de la Comisión que deje de reunir las condiciones necesarias para el ejercicio de sus funciones o haya cometido una falta grave podrá ser cesado por el Tribunal de Justicia, a instancia:","o":["del Parlamento Europeo, por mayoría absoluta, o de la Comisión.","del Consejo Europeo, por unanimidad, o del Presidente de la Comisión.","del Consejo, por mayoría cualificada, o del Parlamento Europeo.","del Consejo, por mayoría simple, o de la Comisión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">del Consejo, por mayoría simple, o de la Comisión</mark></span>El <span class=\"ref-norma\">art. 247 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá ser cesado por el Tribunal de Justicia, a instancia del Consejo, por mayoría simple, o de la Comisión\"</span>. A instancia del Consejo (mayoría simple) o de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3533","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. Los acuerdos de la Comisión se adoptarán:","o":["por mayoría de sus miembros.","por mayoría cualificada de sus miembros.","por unanimidad de sus miembros.","por mayoría de dos tercios de sus miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por mayoría de sus miembros</mark></span>El <span class=\"ref-norma\">art. 250 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los acuerdos de la Comisión se adoptarán por mayoría de sus miembros\"</span>. Mayoría de sus miembros; el quórum lo fija su reglamento interno. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 36 — Parlamento Europeo y PESC ✱","q":[{"i":"3-279","p":"Tratado de la Unión Europea. El Parlamento Europeo podrá dirigir preguntas o formular recomendaciones al Consejo y al Alto Representante. ¿Con qué periodicidad procederá a un debate sobre los progresos realizados en el desarrollo de la política exterior y de seguridad común, incluida la política común de seguridad y defensa?","o":["Dos veces al semestre.","Una vez al año.","Dos veces al año.","Una vez al semestre."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos veces al año</mark></span>El <span class=\"ref-norma\">art. 36 del TUE</span> dispone: <span class=\"ref-concepto\">\"Dos veces al año procederá a un debate sobre los progresos realizados en el desarrollo de la política exterior y de seguridad común, incluida la política común de seguridad y defensa\"</span>. El artículo 36 del TUE establece que el Parlamento Europeo procederá dos veces al año a un debate sobre los progresos realizados en el desarrollo de la política exterior y de seguridad común, incluida la política común de seguridad y defensa."},{"i":"3-ia-3207","p":"Tratado de la Unión Europea. Alto Representante y Parlamento Europeo. El Alto Representante consultará periódicamente al Parlamento Europeo sobre los aspectos principales y las opciones fundamentales de la política exterior y de seguridad común y de la política común de seguridad y defensa; el Parlamento Europeo podrá dirigir preguntas o formular recomendaciones al Consejo y al Alto Representante y procederá a un debate sobre los progresos realizados:","o":["una vez al año.","cada seis meses con la Presidencia.","dos veces al año.","cada vez que lo solicite el Consejo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">dos veces al año</mark></span>El <span class=\"ref-norma\">art. 36 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Dos veces al año procederá a un debate sobre los progresos realizados en el desarrollo de la política exterior y de seguridad común\"</span>. El Parlamento debate dos veces al año. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 32 — Consulta entre Estados miembros ✱","q":[{"i":"3-283","p":"Tratado de la Unión Europea. Política Exterior y de Seguridad Común. Antes de emprender cualquier actuación en la escena internacional o de asumir cualquier compromiso que pueda afectar a los intereses de la Unión, cada Estado miembro consultará a los demás en el seno:","o":["Del Parlamento Europeo y de la Comisión.","Del Consejo Europeo o del Consejo.","Del Consejo y del Parlamento Europeo.","De la Comisión y del Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del Consejo Europeo o del Consejo</mark></span>Según el <span class=\"ref-norma\">art. 32 del TUE</span>: <span class=\"ref-concepto\">\"Antes de emprender cualquier actuación en la escena internacional o de asumir cualquier compromiso que pueda afectar a los intereses de la Unión, cada Estado miembro consultará a los demás en el seno del Consejo Europeo o del Consejo.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3166","p":"Tratado de la Unión Europea. Consulta entre Estados miembros. Los Estados miembros se consultarán en el seno del Consejo Europeo y del Consejo sobre cualquier cuestión de política exterior y de seguridad que revista un interés general, a fin de definir un enfoque común; antes de emprender cualquier actuación en la escena internacional o asumir un compromiso que pueda afectar a los intereses de la Unión, cada Estado miembro:","o":["informará al Alto Representante en el seno del Consejo de Asuntos Exteriores.","solicitará la autorización del Consejo por mayoría cualificada.","comunicará la actuación a la Comisión para su coordinación.","consultará a los demás en el seno del Consejo Europeo o del Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">consultará a los demás en el seno del Consejo Europeo o del Consejo</mark></span>El <span class=\"ref-norma\">art. 32 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"cada Estado miembro consultará a los demás en el seno del Con\"</span>. Debe consultar a los demás en el Consejo Europeo o en el Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12 — Parlamentos nacionales ✱","q":[{"i":"3-287","p":"Tratado de la Unión Europea. Los Parlamentos nacionales contribuirán activamente al buen funcionamiento de la Unión, para lo cual: señale la INCORRECTA.","o":["Participarán en los procedimientos de revisión de los Tratados.","Serán informados de las solicitudes de adhesión a la Unión.","Participarán en la cooperación interparlamentaria entre los Parlamentos nacionales y con el Parlamento Europeo, de conformidad con el Protocolo sobre el cometido de los Parlamentos nacionales en la Unión Europea.","Velarán por que se respete el principio de proporcionalidad de conformidad con los procedimientos establecidos en el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Velarán por que se respete el principio de proporcionalidad de conformidad con los procedimientos establecidos en el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 12 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007velarán por que se respete el principio de subsidiariedad de conformidad con los procedimientos establecidos en el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad\"</span>. (Los Parlamentos nacionales velan por el respeto del principio de subsidiariedad, no de proporcionalidad, aunque ambos se rigen por el mismo protocolo)."},{"i":"3-ia-3045","p":"Tratado de la Unión Europea. Parlamentos nacionales. Los Parlamentos nacionales contribuirán activamente al buen funcionamiento de la Unión; para ello serán informados por las instituciones y recibirán notificación de los proyectos de actos legislativos de la Unión, y velarán por que se respete:","o":["el principio de subsidiariedad, de conformidad con los procedimientos establecidos en el Protocolo correspondiente.","el principio de proporcionalidad, de conformidad con los procedimientos establecidos en el Reglamento del Parlamento.","el principio de atribución, de conformidad con los procedimientos establecidos en los Tratados.","el principio de subsidiariedad y de proporcionalidad, de conformidad con el Protocolo sobre el control."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el principio de subsidiariedad, de conformidad con los procedimientos establecidos en el Protocolo correspondiente</mark></span>El <span class=\"ref-norma\">art. 12.a y b de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"velarán por que se respete el principio de subsidiariedad de conformidad con los procedi\"</span>. Velan por el principio de subsidiariedad, conforme al Protocolo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3046","p":"Tratado de la Unión Europea. Parlamentos nacionales. Los Parlamentos nacionales participarán en los procedimientos de revisión de los Tratados y serán informados de:","o":["las solicitudes de retirada de la Unión.","las decisiones de suspensión de derechos de un Estado.","los acuerdos celebrados con países terceros.","las solicitudes de adhesión a la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las solicitudes de adhesión a la Unión</mark></span>El <span class=\"ref-norma\">art. 12.d y e de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"serán informados de las solicitudes de adhesión a la Unión\"</span>. Son informados de las solicitudes de adhesión; participan en la revisión de los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3326","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. En relación con las propuestas e iniciativas legislativas presentadas en el marco de la cooperación judicial en materia penal y de la cooperación policial, los Parlamentos nacionales velarán por que se respete:","o":["el principio de proporcionalidad, de conformidad con el Protocolo sobre el cometido de los Parlamentos nacionales.","el principio de atribución, de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad.","el principio de cooperación leal, de conformidad con el Protocolo sobre el espacio de libertad, seguridad y justicia, salvo que se disponga otra cosa en la normativa aplicable.","el principio de subsidiariedad, de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el principio de subsidiariedad, de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 69 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"los Parlamentos nacionales velarán por que se respete el principio de subsidiariedad, de conformidad con el\"</span>. Control de subsidiariedad de los Parlamentos nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 25 — Cómo dirige la Unión la PESC ✱","q":[{"i":"3-333","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. La Unión dirigirá la política exterior y de seguridad común:","o":["Definiendo sus orientaciones generales, adoptando decisiones y fortaleciendo la cooperación sistemática entre los Estados miembros.","Adoptando actos legislativos y fortaleciendo la cooperación sistemática entre los Estados miembros, previa decisión del Parlamento Europeo.","Definiendo sus orientaciones generales, adoptando reglamentos y fortaleciendo la cooperación entre las instituciones.","Adoptando decisiones y directivas vinculantes y fortaleciendo la cooperación sistemática con terceros Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Definiendo sus orientaciones generales, adoptando decisiones y fortaleciendo la cooperación sistemática entre los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 25 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión dirigirá la política exterior y de seguridad común: a) definiendo sus orientaciones generales; b) adoptando decisiones por las que se establezcan\"</span>. La PESC se dirige mediante orientaciones generales, decisiones y cooperación sistemática; están excluidos los actos legislativos."},{"i":"3-ia-3147","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. La Unión dirigirá la política exterior y de seguridad común definiendo sus orientaciones generales, adoptando decisiones por las que se establezcan las acciones y las posiciones que va a adoptar la Unión y las modalidades de ejecución de las decisiones, y:","o":["fomentando la convergencia progresiva de las políticas nacionales mediante acuerdos bilaterales.","coordinando la actuación diplomática de los Estados miembros en las organizaciones internacionales, conforme al procedimiento que se establezca reglamentariamente.","fortaleciendo la cooperación sistemática entre los Estados miembros para llevar a cabo sus políticas.","armonizando las legislaciones nacionales en materia de política exterior y de seguridad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">fortaleciendo la cooperación sistemática entre los Estados miembros para llevar a cabo sus políticas</mark></span>El <span class=\"ref-norma\">art. 25 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"fortaleciendo la cooperación sistemática entre los Estados miembros para llevar a cabo sus\"</span>. La tercera vía es fortalecer la cooperación sistemática entre los Estados miembros. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3161","p":"Tratado de la Unión Europea. Votaciones en PESC. En caso de que el número de miembros del Consejo que acompañara su abstención de una declaración formal representara al menos un tercio de los Estados miembros que reúnen como mínimo un tercio de la población de la Unión:","o":["no se adoptará la decisión.","se adoptará la decisión por mayoría cualificada.","la decisión se remitirá al Consejo Europeo.","se aplazará la decisión durante seis meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no se adoptará la decisión</mark></span>El <span class=\"ref-norma\">art. 31.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no se adoptará la decisión\"</span>. Si esas abstenciones alcanzan un tercio de los Estados y de la población, no se adopta la decisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 28 — Acción operativa","q":[{"i":"3-334","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. Cuando una situación internacional exija una acción operativa de la Unión, adoptará las decisiones necesarias:","o":["El Consejo Europeo.","El Alto Representante.","La Comisión.","El Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 28 del TUE</span> dispone: <span class=\"ref-concepto\">\"Cuando una situación internacional exija una acción operativa de la Unión, el Consejo adoptará las decisiones necesarias\"</span>. La acción operativa se decide por el Consejo."},{"i":"3-ia-3153","p":"Tratado de la Unión Europea. Acción operativa. Las decisiones de acción operativa serán vinculantes para los Estados miembros en las posiciones que adopten y en el desarrollo de su acción; cuando exista cualquier plan para adoptar una posición nacional o emprender una acción nacional, el Estado miembro:","o":["proporcionará información en un plazo que permita, en caso necesario, una concertación previa en el seno del Consejo.","solicitará autorización previa del Consejo antes de adoptar la posición nacional o emprender la acción, en los términos que establezca la propia norma.","informará al Alto Representante una vez adoptada la posición nacional o iniciada la acción.","consultará al Parlamento Europeo antes de adoptar la posición nacional o emprender la acción."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">proporcionará información en un plazo que permita, en caso necesario, una concertación previa en el seno del Consejo</mark></span>El <span class=\"ref-norma\">art. 28.2 y 3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Estado miembro de que se trate proporcionará información en un plazo que permita, en caso necesario, una concertación previa en el\"</span>. Debe informar con tiempo para una concertación previa en el Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3154","p":"Tratado de la Unión Europea. Acción operativa. La obligación de información previa de los Estados miembros en la acción operativa no se aplicará:","o":["a las medidas que adopten los Estados miembros en situaciones de especial urgencia, salvo que se disponga otra cosa en la normativa aplicable.","a las medidas que afecten a la seguridad nacional de los Estados miembros.","a las medidas que tengan carácter provisional o experimental en el ámbito nacional.","a las medidas que constituyan una mera transposición al ámbito nacional de las decisiones del Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a las medidas que constituyan una mera transposición al ámbito nacional de las decisiones del Consejo</mark></span>El <span class=\"ref-norma\">art. 28.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La obligación de información previa no se aplicará a las medidas que constituyan una mera transposición al ámbito nacional de las decisiones del Consejo\"</span>. Se exceptúa la mera transposición al ámbito nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3155","p":"Tratado de la Unión Europea. Acción operativa. En caso de imperiosa necesidad derivada de la evolución de la situación y a falta de revisión de una decisión del Consejo, los Estados miembros podrán adoptar con carácter de urgencia las medidas necesarias, y el Estado miembro de que se trate:","o":["informará al Consejo Europeo en la siguiente reunión.","solicitará la ratificación posterior del Consejo.","informará al Consejo inmediatamente de tales medidas.","comunicará las medidas al Alto Representante en el plazo de una semana."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">informará al Consejo inmediatamente de tales medidas</mark></span>El <span class=\"ref-norma\">art. 28.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Estado miembro de que se trate informará al Consejo inmediatamente de tales medidas\"</span>. Informa inmediatamente al Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3156","p":"Tratado de la Unión Europea. Acción operativa. En caso de que un Estado miembro tenga dificultades importantes para aplicar una decisión de acción operativa, solicitará al Consejo que delibere al respecto y busque las soluciones adecuadas, que no podrán ser contrarias:","o":["a los intereses del Estado miembro ni mermar su soberanía.","a los objetivos de la decisión ni mermar su eficacia.","a las posiciones de la Unión ni mermar su coherencia.","a los principios del Tratado ni mermar su legitimidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a los objetivos de la decisión ni mermar su eficacia</mark></span>El <span class=\"ref-norma\">art. 28.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Estas soluciones no podrán ser contrarias a los objetivos de la decisión contemplada en el apartado 1 ni mermar su eficacia\"</span>. Las soluciones no pueden ir contra los objetivos de la decisión ni mermar su eficacia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 30 — Iniciativa y decisiones rápidas ✱","q":[{"i":"3-335","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. En los casos que requieran una decisión rápida, el Alto Representante convocará, de oficio o a petición de un Estado miembro, una reunión extraordinaria del Consejo, en un plazo de:","o":["Veinticuatro horas o, en caso de necesidad absoluta, en un plazo todavía más breve.","Setenta y dos horas o, en caso de necesidad absoluta, en un plazo todavía más breve.","Cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve.","Cuarenta y ocho horas, sin que quepa reducirlo ni siquiera en caso de necesidad absoluta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve</mark></span>El <span class=\"ref-norma\">art. 30 del TUE</span> dispone: <span class=\"ref-concepto\">\"en un plazo de cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve\"</span>. El plazo es de cuarenta y ocho horas."},{"i":"3-ia-3159","p":"Tratado de la Unión Europea. Iniciativas en materia de PESC. En los casos que requieran una decisión rápida, el Alto Representante convocará, de oficio o a petición de un Estado miembro, una reunión extraordinaria del Consejo, en un plazo de:","o":["setenta y dos horas o, en caso de necesidad absoluta, en un plazo más breve, conforme al procedimiento que se establezca reglamentariamente.","veinticuatro horas o, en caso de necesidad absoluta, en un plazo más breve.","cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve.","cinco días o, en caso de necesidad absoluta, en un plazo más breve."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve</mark></span>El <span class=\"ref-norma\">art. 30.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en un plazo de cuarenta y ocho horas o, en caso de necesidad absoluta, en un plazo más breve\"</span>. Cuarenta y ocho horas, o menos si es absolutamente necesario. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 31 — Votaciones en la PESC EXOF","q":[{"i":"3-336","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. El Consejo Europeo y el Consejo adoptarán por unanimidad las decisiones de la política exterior y de seguridad común, salvo en los casos en que el capítulo disponga otra cosa. En todo caso, queda excluida:","o":["La adopción de decisiones por mayoría cualificada.","La adopción de actos legislativos.","La adopción de decisiones operativas.","La adopción de posiciones comunes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La adopción de actos legislativos</mark></span>El <span class=\"ref-norma\">art. 31 del TUE</span> dispone: <span class=\"ref-concepto\">\"adoptarán por unanimidad las decisiones de que trata el presente capítulo, salvo en los casos en que el presente capítulo disponga otra cosa. Se excluye la adopción de actos legislativos\"</span>. Regla general: unanimidad y exclusión de actos legislativos."},{"i":"3-337","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. Si un miembro del Consejo declarase que, por motivos vitales y explícitos de política nacional, tiene la intención de oponerse a la adopción de una decisión que se deba adoptar por mayoría cualificada:","o":["No se procederá a la votación.","Se votará igualmente, sin su participación.","La decisión se adoptará por unanimidad.","El asunto pasará automáticamente al Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">No se procederá a la votación</mark></span>El <span class=\"ref-norma\">art. 31 del TUE</span> dispone: <span class=\"ref-concepto\">\"tiene la intención de oponerse a la adopción de una decisión que se deba adoptar por mayoría cualificada, no se procederá a la votación\"</span>. No hay votación; el Alto Representante buscará una solución y, si no la hay, el asunto puede remitirse al Consejo Europeo, que decide por unanimidad."},{"i":"3-349","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Capital y pagos. A falta de medidas de aplicación, la Comisión o, a falta de una decisión de la Comisión dentro de un período de tres meses a partir de la solicitud del Estado miembro interesado, el Consejo, podrá declarar compatibles con los Tratados determinadas medidas fiscales restrictivas respecto de terceros países. El Consejo se pronunciará:","o":["Por unanimidad a instancia de un Estado miembro.","Por mayoría cualificada a propuesta de la Comisión.","Por mayoría simple a instancia de la Comisión.","Por unanimidad a propuesta del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por unanimidad a instancia de un Estado miembro</mark></span>El <span class=\"ref-norma\">art. 65 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad a instancia de un Estado miembro\"</span>. Unanimidad a instancia de un Estado miembro."},{"i":"3-400","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Disposiciones comunes. Como excepción a la regla general de la unanimidad en la política exterior y de seguridad común, el Consejo adoptará por mayoría cualificada la designación de:","o":["Un representante especial.","Un Alto Representante adjunto.","Un Vicepresidente de la Comisión.","Un representante permanente ante el Comité Político y de Seguridad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Un representante especial</mark></span>El <span class=\"ref-norma\">art. 31.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"la designación de un representante especial de conformidad con el artículo\"</span>. El representante especial se designa por mayoría cualificada. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3160","p":"Tratado de la Unión Europea. Votaciones en PESC. El Consejo Europeo y el Consejo adoptarán por unanimidad las decisiones en materia de política exterior y de seguridad común, salvo en los casos en que se disponga otra cosa; si un miembro del Consejo se abstuviera en una votación, podrá acompañar su abstención de una declaración formal y, en ese caso:","o":["estará obligado a aplicar la decisión, aunque podrá formular reservas sobre su alcance.","no estará obligado a aplicar la decisión, pero admitirá que ésta sea vinculante para la Unión.","no estará obligado a aplicar la decisión ni a respetar las acciones de los demás Estados, sin perjuicio de lo dispuesto en otras disposiciones.","podrá aplicar la decisión de forma parcial, previa notificación al Alto Representante."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no estará obligado a aplicar la decisión, pero admitirá que ésta sea vinculante para la Unión</mark></span>El <span class=\"ref-norma\">art. 31.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"En ese caso, no estará obligado a aplicar la decisión, pero admitirá que ésta sea vinculante para la Unión\"</span>. Es la abstención constructiva: no aplica la decisión pero admite que vincule a la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3163","p":"Tratado de la Unión Europea. Votaciones en PESC. Si un miembro del Consejo declarase que, por motivos vitales y explícitos de política nacional, tiene la intención de oponerse a la adopción de una decisión que se deba adoptar por mayoría cualificada, no se procederá a la votación y, de no hallarse una solución aceptable, el Consejo, por mayoría cualificada, podrá pedir que el asunto se remita:","o":["al Consejo Europeo para que adopte al respecto una decisión por mayoría cualificada.","al Alto Representante para que busque una solución con la Comisión.","al Consejo Europeo para que adopte al respecto una decisión por unanimidad.","al Parlamento Europeo para que emita un dictamen vinculante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Consejo Europeo para que adopte al respecto una decisión por unanimidad</mark></span>El <span class=\"ref-norma\">art. 31.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá pedir que el asunto se remita al Consejo Europeo para que adopte al respecto una decisión por unanimidad\"</span>. Se remite al Consejo Europeo, que decide por unanimidad (freno de emergencia). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3165","p":"Tratado de la Unión Europea. Votaciones en PESC. En lo que se refiere a cuestiones de procedimiento, el Consejo se pronunciará:","o":["por mayoría de los miembros que lo componen.","por mayoría cualificada.","por unanimidad de sus miembros.","por mayoría de dos tercios de sus miembros, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por mayoría de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 31.5 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Consejo se pronunciará por mayoría de los\"</span>. Las cuestiones de procedimiento se resuelven por mayoría de los miembros del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3319","p":"Tratado de Funcionamiento de la Unión Europea. Capital y pagos. A falta de medidas de aplicación, la Comisión o, a falta de una decisión de la Comisión dentro de un período de tres meses a partir de la solicitud del Estado miembro interesado, el Consejo, podrá adoptar una decisión que declare que las medidas fiscales restrictivas adoptadas por un Estado miembro con respecto a terceros países deben considerarse compatibles con los Tratados; el Consejo se pronunciará:","o":["por mayoría cualificada a propuesta de la Comisión.","por unanimidad a propuesta de la Comisión.","por unanimidad a instancia de un Estado miembro.","por mayoría cualificada a instancia de un Estado miembro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por unanimidad a instancia de un Estado miembro</mark></span>El <span class=\"ref-norma\">art. 65.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad a instancia de un Estado miembro\"</span>. Unanimidad, a instancia de un Estado miembro; la Comisión tiene prioridad durante tres meses. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3614","p":"Tratado de Funcionamiento de la Unión Europea. Recurso por omisión. En caso de que, en violación de los Tratados, el Parlamento Europeo, el Consejo Europeo, el Consejo, la Comisión o el Banco Central Europeo se abstuvieren de pronunciarse, los Estados miembros y las demás instituciones de la Unión podrán recurrir al Tribunal con objeto de:","o":["que ordene la adopción del acto omitido.","que anule la decisión de abstenerse.","que imponga una sanción a la institución.","que declare dicha violación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">que declare dicha violación</mark></span>El <span class=\"ref-norma\">art. 265 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrán recurrir al Tribunal de Justicia de la Unión Europea con objeto de que declare dicha violación\"</span>. El Tribunal declara la violación por omisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 44 — Misión a un grupo de Estados ✱","q":[{"i":"3-338","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Política común de seguridad y defensa. En el marco de las decisiones sobre misiones adoptadas por el Consejo, éste podrá encomendar la realización de una misión a un grupo de Estados miembros:","o":["Que designe el Alto Representante por iniciativa propia o a petición de un Estado miembro.","Que decida el Parlamento Europeo previa consulta al Alto Representante y a la Comisión.","Que hayan suscrito previamente la cooperación estructurada permanente en el marco de la Unión.","Que lo deseen y que dispongan de las capacidades necesarias para tal misión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Que lo deseen y que dispongan de las capacidades necesarias para tal misión</mark></span>El <span class=\"ref-norma\">art. 44 del TUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo podrá encomendar la realización de una misión a un grupo de Estados miembros que lo deseen y que dispongan de las capacidades necesarias para tal misión\"</span>. Participan los Estados que lo deseen y dispongan de capacidades."},{"i":"3-ia-3231","p":"Tratado de la Unión Europea. Realización de misiones por un grupo de Estados. En el marco de las decisiones adoptadas, el Consejo podrá encomendar la realización de una misión a un grupo de Estados miembros que lo deseen y que dispongan de las capacidades necesarias; la gestión de la misión se acordará entre dichos Estados miembros:","o":["bajo la autoridad del Consejo Europeo, conforme al procedimiento que se establezca reglamentariamente.","previa consulta al Parlamento Europeo.","en asociación con el Alto Representante.","a propuesta de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en asociación con el Alto Representante</mark></span>El <span class=\"ref-norma\">art. 44.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La gestión de la misión se acordará entre dichos Esta-dos miembros, en asociación con el Alto Representante\"</span>. Los Estados acuerdan la gestión en asociación con el Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 51 a 55 TFUE — Excepciones, títulos y sociedades ✱","q":[{"i":"3-341","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Derecho de establecimiento. Las disposiciones sobre el derecho de establecimiento no se aplicarán, en lo que respecta al Estado miembro interesado, a las actividades relacionadas, aunque sólo sea de manera ocasional, con:","o":["El ejercicio del poder público.","La prestación de servicios sanitarios.","El ejercicio de profesiones liberales.","La gestión de empresas públicas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El ejercicio del poder público</mark></span>El <span class=\"ref-norma\">art. 51 del TFUE</span> dispone: <span class=\"ref-concepto\">\"estén relacionadas, aunque sólo sea de manera ocasional, con el ejercicio del poder público\"</span>. La excepción es el ejercicio del poder público."},{"i":"3-342","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Derecho de establecimiento. Las disposiciones sobre el derecho de establecimiento no prejuzgarán la aplicabilidad de las disposiciones que prevean un régimen especial para los extranjeros justificadas por razones de:","o":["Orden público, seguridad nacional y defensa.","Seguridad pública y política económica.","Salud pública y protección de los consumidores.","Orden público, seguridad y salud públicas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Orden público, seguridad y salud públicas</mark></span>El <span class=\"ref-norma\">art. 52 del TFUE</span> dispone: <span class=\"ref-concepto\">\"que prevean un régimen especial para los extranjeros y que estén justificadas por razones de orden público, seguridad y salud públicas\"</span>. Orden público, seguridad y salud públicas."},{"i":"3-343","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Derecho de establecimiento. En cuanto a las profesiones médicas, paramédicas y farmacéuticas, la progresiva supresión de las restricciones quedará subordinada a:","o":["La armonización de los planes de estudio y de los programas de formación de cada Estado miembro.","La aprobación de un reglamento por el Consejo por mayoría cualificada y previa consulta.","La coordinación de las condiciones exigidas para su ejercicio en los diferentes Estados miembros.","La autorización de cada Estado miembro de destino con arreglo a su Derecho nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La coordinación de las condiciones exigidas para su ejercicio en los diferentes Estados miembros</mark></span>El <span class=\"ref-norma\">art. 53 del TFUE</span> dispone: <span class=\"ref-concepto\">\"la progresiva supresión de las restricciones quedará subordinada a la coordinación de las condiciones exigidas para su ejercicio en los diferentes Estados miembros\"</span>. Se subordina a la coordinación de las condiciones de ejercicio."},{"i":"3-344","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Derecho de establecimiento. Los Estados miembros aplicarán a los nacionales de los demás Estados miembros, en lo que respecta a su participación financiera en el capital de las sociedades:","o":["El trato de nación más favorecida.","El trato de nacional.","Un trato preferente.","Un trato diferenciado por reciprocidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El trato de nacional</mark></span>El <span class=\"ref-norma\">art. 55 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros aplicarán a los nacionales de los demás Estados miembros el trato de nacional en lo que respecta a su participación financiera en el capital de las sociedades\"</span>. Se aplica el trato de nacional."},{"i":"3-ia-3251","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. Las disposiciones sobre el derecho de establecimiento no se aplicarán, en lo que respecta al Estado miembro interesado, a las actividades que, en dicho Estado, estén relacionadas, aunque sólo sea de manera ocasional, con:","o":["la seguridad nacional, conforme al procedimiento que se establezca reglamentariamente.","el orden público.","el ejercicio del poder público.","la defensa nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el ejercicio del poder público</mark></span>El <span class=\"ref-norma\">art. 51 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"estén relacionadas, aunque sólo sea de manera ocasional, con el ejercicio del poder público\"</span>. Quedan excluidas las actividades relacionadas con el ejercicio del poder público. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3252","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, podrán excluir de la aplicación de las disposiciones sobre el derecho de establecimiento:","o":["determinados Estados miembros.","determinadas actividades.","determinadas profesiones reguladas.","determinadas formas societarias."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">determinadas actividades</mark></span>El <span class=\"ref-norma\">art. 51 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrán excluir determinadas actividades de la aplicación de las disposiciones del presente capítulo\"</span>. Pueden excluir determinadas actividades. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3253","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. Las disposiciones sobre el derecho de establecimiento no prejuzgarán la aplicabilidad de las disposiciones legales, reglamentarias y administrativas que prevean un régimen especial para los extranjeros y que estén justificadas por razones de:","o":["orden público, seguridad y salud públicas.","seguridad nacional y orden público.","interés general y salud pública.","seguridad pública y protección de los consumidores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">orden público, seguridad y salud públicas</mark></span>El <span class=\"ref-norma\">art. 52.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"justificadas por razones de orden público, seguridad y salud públicas\"</span>. Orden público, seguridad y salud públicas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3302","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. En cuanto a las profesiones médicas, paramédicas y farmacéuticas, la progresiva supresión de las restricciones quedará subordinada:","o":["al reconocimiento mutuo automático de los títulos expedidos en los diferentes Estados miembros, salvo que se disponga otra cosa en la normativa aplicable.","a la armonización de las normas deontológicas aplicables en los diferentes Estados miembros.","a la adopción de un código europeo de buenas prácticas por las organizaciones profesionales.","a la coordinación de las condiciones exigidas para su ejercicio en los diferentes Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a la coordinación de las condiciones exigidas para su ejercicio en los diferentes Estados miembros</mark></span>El <span class=\"ref-norma\">art. 53.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"quedará subordinada a la coordinación de las condiciones exigidas para su ejercicio en los\"</span>. Está subordinada a la coordinación de las condiciones de ejercicio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3303","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. Las sociedades constituidas de conformidad con la legislación de un Estado miembro y cuya sede social, administración central o centro de actividad principal se encuentre dentro de la Unión quedarán equiparadas a las personas físicas nacionales de los Estados miembros; por sociedades se entiende las sociedades de Derecho civil o mercantil, incluso las cooperativas, y las demás personas jurídicas de Derecho público o privado, con excepción de:","o":["las que no tengan personalidad jurídica propia.","las que ejerzan el poder público.","las que no persigan un fin lucrativo.","las que no estén constituidas en la Unión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las que no persigan un fin lucrativo</mark></span>El <span class=\"ref-norma\">art. 54 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con excepción de las que no persigan un fin lucrativo\"</span>. Se excluyen las que no persigan un fin lucrativo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3304","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. Los Estados miembros aplicarán a los nacionales de los demás Estados miembros el trato de nacional en lo que respecta a:","o":["su acceso a los cargos de administración de las sociedades definidas en el Tratado, sin perjuicio de lo dispuesto en otras disposiciones.","su participación financiera en el capital de las sociedades definidas en el Tratado.","su tributación por los beneficios de las sociedades definidas en el Tratado.","su responsabilidad por las deudas de las sociedades definidas en el Tratado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">su participación financiera en el capital de las sociedades definidas en el Tratado</mark></span>El <span class=\"ref-norma\">art. 55 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el trato de nacional en lo que respecta a su participación financiera en el capital de las sociedades\"</span>. Trato de nacional en la participación financiera en el capital. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3532","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. La Comisión publicará todos los años, al menos un mes antes de la apertura del período de sesiones del Parlamento Europeo, un informe general sobre:","o":["la situación económica de la Unión.","las actividades de la Unión.","la aplicación del Derecho de la Unión.","el estado de la Unión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las actividades de la Unión</mark></span>El <span class=\"ref-norma\">art. 249 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"un informe general sobre las actividades de la Unión\"</span>. Informe general anual sobre las actividades de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 262 TFUE — Propiedad intelectual e industrial ✱","q":[{"i":"3-374","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Consejo, con arreglo a un procedimiento legislativo especial y previa consulta al Parlamento Europeo, podrá adoptar disposiciones destinadas a atribuir al Tribunal de Justicia competencia para resolver litigios relativos a títulos europeos de propiedad intelectual o industrial. Se pronunciará:","o":["Por mayoría cualificada.","Por mayoría simple.","Por mayoría absoluta.","Por unanimidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por unanimidad</mark></span>El <span class=\"ref-norma\">art. 262 del TFUE</span> dispone: <span class=\"ref-concepto\">\"el Consejo, por unanimidad, con arreglo a un procedimiento legislativo especial y previa consulta al Parlamento Europeo\"</span>. Unanimidad."},{"i":"3-ia-3607","p":"Tratado de Funcionamiento de la Unión Europea. Propiedad intelectual e industrial. El Consejo, por unanimidad, con arreglo a un procedimiento legislativo especial y previa consulta al Parlamento Europeo, podrá adoptar disposiciones destinadas a atribuir al Tribunal de Justicia la competencia para resolver litigios relativos a la aplicación de los actos por los que se crean títulos europeos de propiedad intelectual o industrial; dichas disposiciones entrarán en vigor:","o":["cuando hayan sido ratificadas por el Parlamento Europeo por mayoría de los miembros que lo componen, conforme al procedimiento que se establezca reglamentariamente.","a los veinte días de su publicación en el Diario Oficial de la Unión Europea.","cuando hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales.","cuando las apruebe el Consejo Europeo por unanimidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cuando hayan sido aprobadas por los Estados miembros de conformidad con sus respectivas normas constitucionales</mark></span>El <span class=\"ref-norma\">art. 262 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Dichas disposiciones entrarán en vigor cuando hayan sido aprobadas por los Estados miembros de conformidad con sus respec\"</span>. Entran en vigor tras su aprobación por los Estados según sus normas constitucionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 268 TFUE — Indemnización por daños","q":[{"i":"3-378","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea será competente para conocer de los litigios relativos a:","o":["La interpretación de los actos del Consejo Europeo.","La elección de los miembros de la Comisión.","La modificación de los Tratados.","La indemnización por daños."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La indemnización por daños</mark></span>El <span class=\"ref-norma\">art. 268 del TFUE</span> dispone: <span class=\"ref-concepto\">\"será competente para conocer de los litigios relativos a la indemnización por daños\"</span>. Es competente en litigios sobre indemnización por daños."},{"i":"3-ia-3622","p":"Tratado de Funcionamiento de la Unión Europea. Responsabilidad extracontractual. El Tribunal de Justicia de la Unión Europea será competente para conocer de los litigios relativos a:","o":["la responsabilidad contractual de la Unión derivada de los contratos que celebre con terceros.","la responsabilidad patrimonial de los Estados miembros por incumplimiento del Derecho de la Unión.","la reparación de los daños causados a las instituciones por sus agentes en el ejercicio de sus funciones, salvo que se disponga otra cosa en la normativa aplicable.","la indemnización por daños a que se refieren los párrafos segundo y tercero del artículo sobre responsabilidad extracontractual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la indemnización por daños a que se refieren los párrafos segundo y tercero del artículo sobre responsabilidad extracontractual</mark></span>El <span class=\"ref-norma\">art. 268 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"competente para conocer de los litigios relativos a la indemnización por daños a que se refieren los párrafos segundo y tercero del artículo 340\"</span>. Litigios de indemnización por responsabilidad extracontractual. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 46 — Cooperación estructurada permanente · R14 ✱ R14","q":[{"i":"3-401","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Cooperación estructurada permanente. Si un Estado miembro participante decide abandonar la cooperación estructurada permanente, notificará su decisión al Consejo, que:","o":["Votará por unanimidad su salida de la cooperación.","Informará al Parlamento Europeo para que la apruebe.","Pedirá a la Comisión un dictamen sobre su salida.","Tomará nota de que ha finalizado la participación de ese Estado miembro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Tomará nota de que ha finalizado la participación de ese Estado miembro</mark></span>El <span class=\"ref-norma\">art. 46.5 del TUE</span> dispone: <span class=\"ref-concepto\">\"notificará su decisión al Consejo, que tomará nota de que ha finalizado la participación de ese Estado miembro\"</span>. Ficha RECUERDA R14. <em style=\"color:var(--texto-gris)\">(ficha RECUERDA R14 del temario)</em>"},{"i":"3-ia-3235","p":"Tratado de la Unión Europea. Cooperación estructurada permanente. Los Estados miembros que deseen participar en la cooperación estructurada permanente notificarán su intención al Consejo y al Alto Representante; en un plazo de tres meses a partir de la notificación, el Consejo adoptará una decisión por la que se establezca la cooperación y se fije la lista de los Estados participantes, pronunciándose:","o":["por unanimidad, tras consultar al Alto Representante.","por mayoría simple, a propuesta del Alto Representante, conforme al procedimiento que se establezca reglamentariamente.","por mayoría cualificada, tras consultar al Alto Representante.","por unanimidad, a propuesta de la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">por mayoría cualificada, tras consultar al Alto Representante</mark></span>El <span class=\"ref-norma\">art. 46.1 y 2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo, tras consultar al Alto Representante, se pronunciará por mayoría cualificada\"</span>. Plazo de tres meses y mayoría cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3236","p":"Tratado de la Unión Europea. Cooperación estructurada permanente. Para confirmar la participación de un Estado miembro que desee incorporarse con posterioridad a la cooperación estructurada permanente, el Consejo se pronunciará por mayoría cualificada y participarán en la votación:","o":["todos los miembros del Consejo, con independencia de su participación.","únicamente los miembros del Consejo que representen a los Estados miembros participantes.","los miembros del Consejo que representen a los Estados participantes y a los candidatos, sin perjuicio de lo dispuesto en otras disposiciones.","únicamente los miembros del Consejo que cumplan los criterios del Protocolo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">únicamente los miembros del Consejo que representen a los Estados miembros participantes</mark></span>El <span class=\"ref-norma\">art. 46.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Únicamente participarán en la votación los miembros del Consejo que representen a los Estados miembros participantes\"</span>. Votan solo los miembros que representan a los Estados participantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3237","p":"Tratado de la Unión Europea. Cooperación estructurada permanente. Si un Estado miembro participante ya no cumple los criterios o ya no puede asumir los compromisos, el Consejo podrá adoptar una decisión por la que se suspenda la participación de dicho Estado; en la votación participarán únicamente los miembros del Consejo que representen a los Estados miembros participantes, con excepción:","o":["del Estado miembro de que se trate.","del Estado miembro que ejerza la presidencia.","del Estado miembro con mayor población.","de los Estados miembros que no participen en la cooperación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">del Estado miembro de que se trate</mark></span>El <span class=\"ref-norma\">art. 46.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con excepción del Estado miembro de que se trate\"</span>. No vota el Estado afectado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3238","p":"Tratado de la Unión Europea. Cooperación estructurada permanente. Las decisiones y recomendaciones del Consejo en el marco de la cooperación estructurada permanente, distintas de las relativas a su establecimiento, participación, suspensión o abandono, se adoptarán por:","o":["mayoría cualificada, definida con los votos de los representantes de los Estados participantes, salvo que se disponga otra cosa en la normativa aplicable.","unanimidad, constituida por los votos de los representantes de todos los Estados miembros.","mayoría simple de los representantes de los Estados miembros participantes.","unanimidad, constituida únicamente por los votos de los representantes de los Estados miembros participantes."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">unanimidad, constituida únicamente por los votos de los representantes de los Estados miembros participantes</mark></span>El <span class=\"ref-norma\">art. 46.5 y 6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se adoptarán por unanimidad. A efectos de la aplicación del presente apartado, la unanimidad estará constituida únicamente por los votos de los representantes de los Estados miembros participantes\"</span>. Unanimidad de los Estados participantes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 34 — Coordinación en organizaciones internacionales ✱","q":[{"i":"3-ia-3201","p":"Tratado de la Unión Europea. Coordinación en organizaciones internacionales. Los Estados miembros coordinarán su acción en las organizaciones internacionales y con ocasión de las conferencias internacionales y defenderán en esos foros las posiciones de la Unión; esa coordinación la organizará:","o":["el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","el Presidente del Consejo Europeo en cada foro internacional, en los términos que establezca la propia norma.","la Presidencia rotatoria del Consejo de la Unión Europea.","el Comité Político y de Seguridad en el seno del Consejo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad</mark></span>El <span class=\"ref-norma\">art. 34.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad organizará dicha coordinación\"</span>. La coordinación en foros internacionales la organiza el Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3202","p":"Tratado de la Unión Europea. Coordinación en organizaciones internacionales. En las organizaciones internacionales y en las conferencias internacionales en las que no participen todos los Estados miembros, aquellos que participen:","o":["informarán a la Comisión de las posiciones defendidas.","actuarán en nombre de todos los Estados miembros.","solicitarán instrucciones del Consejo Europeo.","defenderán las posiciones de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">defenderán las posiciones de la Unión</mark></span>El <span class=\"ref-norma\">art. 34.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"aquellos que participen defenderán las posiciones de la Unión\"</span>. Los Estados presentes defienden las posiciones de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3204","p":"Tratado de la Unión Europea. Coordinación en organizaciones internacionales. Cuando la Unión haya definido una posición sobre un tema incluido en el orden del día del Consejo de Seguridad de las Naciones Unidas, los Estados miembros que sean miembros de éste pedirán que se invite:","o":["al Presidente del Consejo Europeo a presentar la posición de la Unión.","al Alto Representante a presentar la posición de la Unión.","al Presidente de la Comisión a presentar la posición de la Unión.","a un representante del Parlamento Europeo a presentar la posición de la Unión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Alto Representante a presentar la posición de la Unión</mark></span>El <span class=\"ref-norma\">art. 34.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"pedirán que se invite al Alto Representante a presentar la posición de la Unión\"</span>. Se invita al Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3230","p":"Tratado de la Unión Europea. Misiones de la política común de seguridad y defensa. El Alto Representante, bajo la autoridad del Consejo y en contacto estrecho y permanente con el Comité Político y de Seguridad, se hará cargo de:","o":["la dirección operativa de las misiones y de la gestión de crisis.","la designación de los mandos de las misiones civiles y militares.","la financiación de los aspectos civiles y militares de dichas misiones, salvo que se disponga otra cosa en la normativa aplicable.","la coordinación de los aspectos civiles y militares de dichas misiones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la coordinación de los aspectos civiles y militares de dichas misiones</mark></span>El <span class=\"ref-norma\">art. 43.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se hará cargo de la coordinación de los aspectos civiles y militares de dichas misiones\"</span>. Coordina los aspectos civiles y militares. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Tratado de la Unión Europea (TUE)","q":[{"i":"3-ia-3208","p":"Tratado de la Unión Europea. Acuerdos internacionales. La Unión podrá celebrar acuerdos con uno o varios Estados u organizaciones internacionales:","o":["en cualquier ámbito, previa autorización del Parlamento Europeo, sin perjuicio de lo dispuesto en otras disposiciones.","en los ámbitos comprendidos en el capítulo de la política exterior y de seguridad común.","únicamente en los ámbitos de competencia exclusiva de la Unión.","en los ámbitos que determine el Consejo Europeo por unanimidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">en los ámbitos comprendidos en el capítulo de la política exterior y de seguridad común</mark></span>El <span class=\"ref-norma\">art. 37 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión podrá celebrar acuerdos con uno o varios Estados u organizaciones internacionales en los ámbitos\"</span>. Los acuerdos se refieren a los ámbitos de la PESC. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3211","p":"Tratado de la Unión Europea. Protección de datos en la PESC. El Consejo adoptará una decisión que fije las normas sobre protección de las personas físicas respecto del tratamiento de datos de carácter personal por los Estados miembros en el ejercicio de las actividades comprendidas en la PESC; el respeto de dichas normas estará sometido:","o":["al control del Tribunal de Justicia, conforme al procedimiento que se establezca reglamentariamente.","al control del Parlamento Europeo.","al control de autoridades independientes.","al control de la Comisión Europea."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al control de autoridades independientes</mark></span>El <span class=\"ref-norma\">art. 39 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El respeto de dichas normas estará sometido al control de autoridades independientes\"</span>. Control de autoridades independientes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
